INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Graphcore Ltd', 'Graphcore is a Bristol-based AI chip company that developed the Intelligence Processing Unit (IPU), a massively parallel processor purpose-built for machine intelligence workloads. Founded in 2016 by Simon Knowles and Nigel Toon, the company achieved unicorn status after raising over £500 million before being acquired by SoftBank in 2024 for approximately £462 million. The IPU architecture is designed for the highly parallelisable, sparse compute patterns common in AI model training and inference. Graphcore operates offices in Bristol, London, Cambridge, and internationally.', '{"company_type": "AI Chip Design", "website_url": "https://www.graphcore.ai", "contact_email": "info@graphcore.ai", "contact_phone": "+44 (0)117 214 1420", "contact_linkedin": "https://www.linkedin.com/company/graphcore", "location": "Bristol, England, UK", "capabilities": ["IPU chip design", "AI model training acceleration", "Machine learning inference", "Parallel compute architectures", "AI hardware and software stack"], "industries": ["Artificial Intelligence", "Cloud Computing", "High Performance Computing", "Research & Development"], "employees": "500+", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Arm Ltd', 'Arm Holdings is the world''s leading semiconductor IP company, headquartered in Cambridge, designing the processor architectures that power the vast majority of mobile devices, embedded systems, and AI accelerators worldwide. Founded in 1990, Arm licenses its CPU, GPU, and NPU IP to a global network of chip partners with its technology found in over 95% of smartphones. The company''s Neoverse, Cortex, and Ethos product lines are central to AI compute at the edge and in data centres. Arm is majority-owned by SoftBank and listed on NASDAQ, and in 2025 announced a £100 million AI chip design centre investment in Bristol.', '{"company_type": "AI Chip Design", "website_url": "https://www.arm.com", "contact_phone": "+44 (0)1223 400 400", "contact_linkedin": "https://www.linkedin.com/company/arm", "location": "Cambridge, England, UK", "certifications": ["ISO 9001"], "capabilities": ["CPU IP licensing", "GPU IP licensing", "NPU and AI accelerator IP", "RISC-V and ARM ISA design", "Edge AI compute", "Data centre compute IP"], "industries": ["Semiconductors", "Mobile Computing", "Artificial Intelligence", "IoT", "Automotive", "Data Centres"], "employees": "500+", "established": 1990, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Imagination Technologies Ltd', 'Imagination Technologies is a UK semiconductor IP company based in Kings Langley, Hertfordshire, designing GPU, neural network accelerator, and CPU IP cores for mobile, automotive, IoT, and data centre markets. The company''s PowerVR GPU architecture has been licensed into billions of devices globally, and its IMG Series neural network accelerators deliver AI inference at the edge with industry-leading TOPS-per-watt performance. Founded in 1985 and taken private by a Chinese investor consortium in 2017, Imagination continues to serve global chip makers including Apple, MediaTek, and Renesas with licensable silicon IP.', '{"company_type": "AI Chip Design", "website_url": "https://www.imaginationtech.com", "contact_phone": "+44 (0)1923 260511", "contact_linkedin": "https://www.linkedin.com/company/imaginationtech", "location": "Kings Langley, Hertfordshire, UK", "capabilities": ["GPU IP licensing", "Neural network accelerator IP", "CPU IP licensing", "Edge AI inference", "Computer vision acceleration", "Automotive AI processors"], "industries": ["Semiconductors", "Mobile Computing", "Automotive", "IoT", "Artificial Intelligence"], "employees": "500+", "established": 1985, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'XMOS Ltd', 'XMOS is a Bristol-based fabless semiconductor company founded in 2005, specialising in generative Systems-on-Chips (GenSoCs) for AI audio, voice processing, and industrial control applications. The company''s xcore.ai processor platform delivers deterministic, real-time multi-core processing ideal for AI-at-the-edge use cases, with over 35 million deployed units worldwide. XMOS processors combine programmable logic with guaranteed low-latency timing, enabling custom AI and DSP pipelines without fixed-function hardware. The company serves consumer electronics, professional audio, and industrial automation markets globally.', '{"company_type": "AI Chip Design", "website_url": "https://www.xmos.com", "contact_phone": "+44 (0)117 927 6004", "contact_linkedin": "https://www.linkedin.com/company/xmos", "location": "Bristol, England, UK", "capabilities": ["Edge AI processing", "Real-time multi-core SoC design", "AI audio and voice processing", "USB audio chip design", "Industrial IoT processors", "DSP acceleration"], "industries": ["Consumer Electronics", "Professional Audio", "Industrial Automation", "Artificial Intelligence", "IoT"], "employees": "100-249", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pragmatic Semiconductor Ltd', 'Pragmatic Semiconductor, headquartered in Cambridge with its manufacturing facility in Sedgefield, County Durham, pioneers ultra-thin flexible microchips (FlexICs) using thin-film transistor technology. Founded in 2010, the company has built the world''s first billion-unit-per-year production facility for flexible integrated circuits, enabling invisible intelligence to be embedded into packaging, textiles, and everyday objects. FlexICs are thinner than a human hair and manufactured at low cost without conventional silicon wafers. The company serves retail, healthcare, food safety, and IoT markets with AI-enabled flexible chip solutions.', '{"company_type": "AI Chip Design", "website_url": "https://www.pragmaticsemi.com", "contact_email": "info@pragmaticsemi.com", "contact_phone": "+44 (0)1223 855010", "contact_linkedin": "https://www.linkedin.com/company/pragmatic-semiconductor", "location": "Cambridge, England, UK", "capabilities": ["Flexible integrated circuit design", "Thin-film transistor manufacturing", "FlexIC production at scale", "Wearable electronics chips", "IoT sensor integration", "RFID and NFC chip design"], "industries": ["Retail", "Healthcare", "IoT", "Packaging", "Food Safety", "Consumer Electronics"], "employees": "100-249", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fractile Ltd', 'Fractile is a London-based AI chip startup founded in 2022 by Walter Goodwin and Yuhang Song, designing silicon purpose-built to run large language models at dramatically reduced cost and latency. The company emerged from stealth in July 2024 with $15 million in seed funding from investors including Kindred Capital, NATO Innovation Fund, and Oxford Science Enterprises. In early 2026, Fractile announced a £100 million expansion plan to scale its UK team, grow sites in London and Bristol, and build a new hardware engineering facility in Bristol. Its chips target AI inference bottlenecks by redesigning memory and compute architecture specifically for transformer models.', '{"company_type": "AI Chip Design", "website_url": "https://www.fractile.ai", "contact_email": "hello@fractile.ai", "contact_linkedin": "https://www.linkedin.com/company/fractile", "location": "London, England, UK", "capabilities": ["LLM inference chip design", "AI accelerator architecture", "Custom silicon for transformer models", "Energy-efficient AI compute", "Hardware-software co-design"], "industries": ["Artificial Intelligence", "Cloud Computing", "Data Centres", "Enterprise AI"], "employees": "10-49", "established": 2022, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'OLIX Ltd', 'Olix is a London-based photonic AI chip company founded in 2024 by James Dacombe, developing the Optical Tensor Processing Unit (OTPU) — a photonic AI processor designed for inference workloads. In February 2026 the company raised $220 million, achieving a $1 billion unicorn valuation, with the round led by Hummingbird Ventures. The OTPU integrates photonics with SRAM-based memory, bypassing the need for high-bandwidth memory and delivering superior throughput-per-watt versus conventional GPU-based systems. With over 70 employees and first commercial products expected in 2027, Olix is hiring across London, Bristol, and North America.', '{"company_type": "Optical Computing", "website_url": "https://olix.com", "contact_linkedin": "https://www.linkedin.com/company/olix", "location": "London, England, UK", "capabilities": ["Optical Tensor Processing Unit design", "Photonic AI accelerators", "Silicon photonics integration", "AI inference chip design", "Low-power optical compute"], "industries": ["Artificial Intelligence", "Data Centres", "Cloud Computing", "High Performance Computing"], "employees": "50-99", "established": 2024, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lumai Ltd', 'Lumai is an Oxford University spinout commercialising research from Professor Alex Lvovsky''s group, developing a free-space optical computing approach to AI that goes beyond conventional integrated photonics. Based at the Wood Centre for Innovation in Oxford, Lumai''s technology performs AI matrix arithmetic within optical beams travelling through three-dimensional space, bypassing the performance ceiling of silicon GPUs. The company has raised over $10 million in funding and claims its approach can reduce AI inference costs by an order of magnitude compared to today''s state-of-the-art systems. Lumai targets hyperscale data centre operators and cloud AI providers.', '{"company_type": "Optical Computing", "website_url": "https://lumai.ai", "contact_email": "hello@lumai.ai", "contact_phone": "+44 (0)1865 546 516", "contact_linkedin": "https://www.linkedin.com/company/lumaitech", "location": "Oxford, England, UK", "capabilities": ["Free-space optical computing", "3D optical AI acceleration", "Optical matrix-vector multiplication", "Low-energy AI inference", "Photonic deep learning acceleration"], "industries": ["Artificial Intelligence", "Data Centres", "High Performance Computing", "Cloud Computing"], "employees": "10-49", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Optalysys Ltd', 'Optalysys is a Leeds-based photonic chip company founded in 2013 that combines silicon photonics with digital technologies to deliver high-performance computing for AI and cloud infrastructure. The company''s photonic processor is the world''s first to enable Fully Homomorphic Encryption (FHE) at commercially viable speeds, allowing computation on encrypted data without decryption. In January 2026, Optalysys raised £23 million in a Series A extension led by Northern Gritstone, with participation from imec.xpand and the UK National Security Strategic Investment Fund. The company operates from Leeds and Bristol.', '{"company_type": "Optical Computing", "website_url": "https://optalysys.com", "contact_email": "info@optalysys.com", "contact_phone": "+44 (0)113 426 6406", "contact_linkedin": "https://www.linkedin.com/company/optalysys", "location": "Leeds, England, UK", "capabilities": ["Silicon photonics chip design", "Fully Homomorphic Encryption acceleration", "Photonic AI processing", "Always-encrypted cloud computing", "Secure computation hardware"], "industries": ["Artificial Intelligence", "Cybersecurity", "Cloud Computing", "Data Centres", "Government & Defence"], "employees": "10-49", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ORCA Computing Ltd', 'ORCA Computing is a London-based photonic quantum computing company founded in 2019 as a spinout from the University of Oxford, commercialising over 30 years of research by co-founder Professor Ian Walmsley. The company develops full-stack photonic quantum computing systems using room-temperature optical components and integrated quantum memory, avoiding the cryogenic infrastructure required by competing technologies. ORCA delivered the first photonic quantum computing system to the UK''s National Quantum Computing Centre and is collaborating with NVIDIA on quantum-AI integration for data centres. The company has offices in London, Austin, and Toronto.', '{"company_type": "Optical Computing", "website_url": "https://orcacomputing.com", "contact_email": "info@orcacomputing.com", "contact_phone": "+44 (0)208 811 6773", "contact_linkedin": "https://www.linkedin.com/company/orcacomputing", "location": "London, England, UK", "capabilities": ["Photonic quantum computing systems", "Quantum memory integration", "Room-temperature quantum hardware", "Quantum networking", "Quantum-AI hybrid computing"], "industries": ["Quantum Computing", "Artificial Intelligence", "Cybersecurity", "Defence", "Research & Development"], "employees": "50-99", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wave Photonics Ltd', 'Wave Photonics is a Cambridge-based photonic integrated circuit (PIC) design company founded in 2021 by Cambridge quantum photonics PhDs James Lee, Matthew Anderson, and Mateusz Kubica. The company has developed rapid, fabrication-tolerant PIC design software and packaging services, enabling companies to create photonic chips for quantum computing, communications, and photonic sensing without lengthy in-house development cycles. Based at Cambridge Science Park, Wave Photonics secured £4.5 million in venture funding and launched a quantum PIC packaging service in 2024, expanding commercial access to its photonics IP.', '{"company_type": "Optical Computing", "website_url": "https://www.wavephotonics.com", "contact_email": "info@wavephotonics.com", "contact_linkedin": "https://www.linkedin.com/company/wave-photonics", "location": "Cambridge, England, UK", "capabilities": ["Photonic integrated circuit design", "PIC design automation software", "Quantum PIC packaging", "Fabrication-tolerant photonics design", "Silicon photonics", "Quantum photonics IP"], "industries": ["Quantum Computing", "Optical Computing", "Telecommunications", "Sensing", "Photonics"], "employees": "10-49", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Light Trace Photonics Ltd', 'Light Trace Photonics is a Bristol-based photonic chip design company headquartered at the Quantum Technology Innovation Centre, developing the LightCraft platform — a rapid-development access service for pre-validated photonic chip components. Founded in 2021 and backed by QantX Ventures with £600,000 in funding, the company accelerates product development for customers in quantum computing, optical communications, and photonic sensing. LightCraft reduces time-to-market for PIC-based products by providing curated, tested component libraries and design support services, and the company also runs photonics engineering training programmes.', '{"company_type": "Optical Computing", "website_url": "https://www.ltphotonics.co.uk", "contact_email": "contact@ltphotonics.co.uk", "contact_linkedin": "https://www.linkedin.com/company/light-trace-photonics", "location": "Bristol, England, UK", "capabilities": ["Photonic chip component design", "PIC rapid prototyping platform", "LightCraft design platform", "Quantum photonics design tools", "Silicon photonics integration", "Photonics training and education"], "industries": ["Quantum Computing", "Optical Computing", "Telecommunications", "Photonics", "Research & Development"], "employees": "1-9", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Singular Photonics Ltd', 'Singular Photonics is an Edinburgh University spinout founded in February 2024 by Professor Robert Henderson and CEO Shahida Imani, developing the first SPAD (Single Photon Avalanche Diode) image sensors with on-chip signal processing for computer vision, LiDAR, and medical imaging. Based at the Higgs Centre for Innovation at the Royal Observatory, Edinburgh, the company emerged from stealth in January 2025 with a portfolio of advanced imaging sensors that compute directly at the pixel level, eliminating data transfer bottlenecks. Singular Photonics was selected for the government-backed ChipStart UK semiconductor incubator and is a member of the UK Photonics Leadership Group.', '{"company_type": "AI Chip Design", "website_url": "https://singularphotonics.com", "contact_email": "info@singularphotonics.com", "contact_phone": "+44 (0)7944 231 537", "contact_linkedin": "https://www.linkedin.com/company/singular-photonics", "location": "Edinburgh, Scotland, UK", "capabilities": ["SPAD image sensor design", "Single photon detection chips", "On-chip signal processing", "LiDAR sensor chips", "Medical imaging chips", "Photonic sensing"], "industries": ["Computer Vision", "Medical Imaging", "Automotive", "Scientific Instrumentation", "Defence"], "employees": "1-9", "established": 2024, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aegiq Ltd', 'Aegiq is a Sheffield-based quantum technology company and University of Sheffield spinout founded in 2019, building full-stack photonic quantum computing and networking hardware using deterministic single-photon sources based on quantum dots. The company offers products covering quantum-secure cybersecurity, quantum networking, quantum-enhanced sensing, and quantum computing systems. In September 2025, Aegiq commissioned a photonic quantum computer at the UK National Quantum Computing Centre. The company is headquartered at Cooper Buildings, Sheffield and is a key participant in the Sheffield Quantum Centre ecosystem.', '{"company_type": "Optical Computing", "website_url": "https://www.aegiq.com", "contact_linkedin": "https://www.linkedin.com/company/aegiq", "location": "Sheffield, England, UK", "capabilities": ["Photonic quantum computing", "Quantum dot single-photon sources", "Quantum networking hardware", "Quantum-secure communications", "Quantum sensing", "Scalable photonic chips"], "industries": ["Quantum Computing", "Cybersecurity", "Government & Defence", "Research & Development", "Telecommunications"], "employees": "10-49", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Vaire Computing Ltd', 'Vaire Computing is a London and Cambridge-based reversible computing startup founded in 2021 by Rodolfo Rosini, Hannah Earley, and Andrew Sloss (formerly a principal researcher at Arm), pioneering near-zero energy chips for AI and data processing. The company''s architecture recovers and recycles most of the energy used in computation rather than dissipating it as heat, with initial chip tests demonstrating approximately 50% energy savings for AI workloads. Vaire has raised $10 million in total funding and participates in the ChipStart UK government-backed semiconductor incubator. The company targets AI training and inference markets where data centre energy costs are a dominant operational expense.', '{"company_type": "AI Chip Design", "website_url": "https://vaire.co", "contact_linkedin": "https://www.linkedin.com/company/vaire-computing", "location": "London, England, UK", "capabilities": ["Reversible computing chip design", "Near-zero energy processor architecture", "AI compute energy reduction", "Data centre chip efficiency", "Novel semiconductor architecture"], "industries": ["Artificial Intelligence", "Data Centres", "High Performance Computing", "Cloud Computing"], "employees": "10-49", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Blueshift Memory Ltd', 'Blueshift Memory is a Cambridge-based semiconductor company founded to solve the memory bottleneck in high-performance computing and AI through its proprietary Cambridge Architecture, which replaces the modified Harvard architecture to overcome the Von Neumann bottleneck. The design enables up to 1,000 times faster memory access for AI, computer vision, 5G edge, and HPC workloads by tightly coupling memory and processing. Based at the Hauser Forum in Cambridge, the company was selected for the ChipStart UK semiconductor incubator and has presented its technology at major international semiconductor conferences. Blueshift Memory targets AI inference accelerator, machine vision, and IoT applications.', '{"company_type": "AI Chip Design", "website_url": "https://www.blueshiftmemory.com", "contact_email": "info@blueshiftmemory.com", "contact_linkedin": "https://www.linkedin.com/company/blueshift-memory", "location": "Cambridge, England, UK", "capabilities": ["Memory architecture design", "AI memory bottleneck solutions", "High-bandwidth memory chip design", "Cambridge Architecture IP", "HPC memory optimisation", "Edge AI chip design"], "industries": ["Artificial Intelligence", "High Performance Computing", "5G", "AR/VR", "IoT"], "employees": "1-9", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HyperCIM Ltd', 'HyperCIM is a London-based deep tech semiconductor startup incorporated in December 2023 and selected for the ChipStart UK government-backed incubator with Arm co-founder Jamie Urquhart as a mentor. The company is developing the Latency Processing Unit (LPU) — a compute-in-memory co-processor that processes data directly where it is stored to eliminate performance bottlenecks in enterprise AI and data pipelines. Founded by Dr. Tanyaradzwa Mangoma, HyperCIM''s technology aims to deliver real-time, multi-database connectivity at memory speed, targeting AI, analytics, and enterprise workloads with dramatic reductions in latency and power consumption.', '{"company_type": "AI Chip Design", "website_url": "https://www.hypercim.com", "contact_linkedin": "https://www.linkedin.com/company/hypercim", "location": "London, England, UK", "capabilities": ["Compute-in-memory chip design", "Latency Processing Unit (LPU)", "AI data pipeline acceleration", "Enterprise workload optimisation", "Low-power memory processing", "Real-time database processing"], "industries": ["Artificial Intelligence", "Enterprise Computing", "Data Analytics", "Cloud Computing"], "employees": "1-9", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RED Semiconductor Ltd', 'RED Semiconductor is a UK fabless semiconductor company developing advanced RISC-V microprocessors using its proprietary VISC (Versatile Intrinsic Structured Computing) architecture, which delivers highly efficient parallel processing for AI, autonomy, and cryptography. The VISC design executes entire algorithmic routines holistically rather than sequentially, delivering significantly greater performance with lower power consumption than conventional processors. RED Semiconductor was selected for the ChipStart UK government-backed incubator and targets embedded AI, autonomous systems, healthcare data processing, and cryptographic security applications. The company was founded by James Lewis, previously founder of Oxford Semiconductor.', '{"company_type": "AI Chip Design", "website_url": "https://redsemiconductor.com", "contact_email": "contactme@redsemiconductor.com", "contact_linkedin": "https://www.linkedin.com/company/red-semiconductor", "location": "United Kingdom", "capabilities": ["RISC-V processor design", "VISC architecture IP", "AI accelerator chip design", "Cryptographic processing hardware", "Autonomous systems processors", "Edge AI chips"], "industries": ["Artificial Intelligence", "Autonomous Systems", "Cybersecurity", "Healthcare", "Industrial Automation"], "employees": "1-9", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SECQAI Ltd', 'SECQAI is a London-based British semiconductor and quantum technology company founded in 2021 by Rahul Tyagi, focused on delivering secure computing hardware from the data centre to the edge by combining quantum simulation with specialist semiconductor design. The company is a member of NATO''s Defence Innovation Accelerator for the North Atlantic (DIANA), a participant in ChipStart UK, and a member of the NVIDIA Inception Programme. SECQAI''s quantum simulation platform enables organisations to implement quantum-security strategies today, while its semiconductor products help customers secure infrastructure against evolving cyber threats. The company partners with Boston Limited as its global hardware reseller.', '{"company_type": "AI Chip Design", "website_url": "https://www.secqai.com", "contact_linkedin": "https://www.linkedin.com/company/secqai", "location": "London, England, UK", "capabilities": ["Quantum security chip design", "Quantum simulation platform", "Secure semiconductor design", "Post-quantum cryptography hardware", "Edge security chips", "Data centre security hardware"], "industries": ["Cybersecurity", "Defence", "Government", "Quantum Computing", "Semiconductors"], "employees": "1-9", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'MintNeuro Ltd', 'MintNeuro is a London-based semiconductor company and Imperial College London spinout founded by CEO Dorian Haci and CTO Timothy Constandinou, designing purpose-built ultra-low-power microchips for minimally invasive neural implant applications. The company''s chips enable brain-machine interfaces that can sense, stimulate, or modify neuron activity with applications in epilepsy, Parkinson''s disease, dementia, and urinary incontinence. In 2025, MintNeuro won three UK Government ARIA awards totalling £17 million and also secured £1 million in seed investment from Empirical Ventures. The company develops its EXPLORE platform for high-channel-count neural recording and stimulation.', '{"company_type": "Neuromorphic Computing", "website_url": "https://mintneuro.com", "contact_email": "dorian@mintneuro.com", "contact_phone": "+44 (0)7783 524536", "contact_linkedin": "https://www.linkedin.com/company/mintneuro", "location": "London, England, UK", "capabilities": ["Neural implant chip design", "Brain-machine interface semiconductors", "Ultra-low-power neurological chips", "Neurostimulation ASIC design", "Bio-electronic device design", "High-channel-count neural recording chips"], "industries": ["Medical Devices", "Neurotechnology", "Healthcare", "Neuromorphic Computing"], "employees": "1-9", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ceryx Medical Ltd', 'Ceryx Medical is a Cardiff-based bioelectronics company formed in 2016 from research at the Universities of Bath and Bristol, developing smart bioelectronic devices using neuromorphic engineering and central pattern generators (CPGs) that mimic the body''s nerve centres. The company''s lead product, Cysoni, is an intelligent temporary cardiac pacing device that adjusts heart rate in synchrony with a patient''s breathing to treat heart failure, hypertension, and related conditions. Ceryx has raised $15 million for its bioelectronic pacemaker programme and also targets spinal cord injury and endocrine disorders. The company is a member of MediWales and is in active clinical evaluation.', '{"company_type": "Neuromorphic Computing", "website_url": "https://www.ceryxmedical.com", "contact_email": "info@ceryxmedical.com", "contact_phone": "+44 (0)7810 754896", "contact_linkedin": "https://www.linkedin.com/company/ceryx-medical-ltd", "location": "Cardiff, Wales, UK", "capabilities": ["Neuromorphic bioelectronic device design", "Central pattern generator circuits", "Implantable cardiac pacing technology", "Smart neuromodulation hardware", "Bioelectronic signal processing"], "industries": ["Medical Devices", "Cardiology", "Neurotechnology", "Healthcare"], "employees": "10-49", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Grayscale AI Ltd', 'Grayscale AI is a London-based neuromorphic AI company founded in 2020 by Dragos Stanciu, developing optimization-driven artificial intelligence that mimics the human neural network to power fully autonomous drones and robots. The company uses neuromorphic computing for real-time pattern recognition and adaptive decision-making in dynamic environments, targeting logistics, security, and emergency response applications. Grayscale AI is backed by Techstars and has been selected for NATO DIANA''s acceleration programme, won $50,000 from the US Army xTech programme, and received a £100,000 UK government grant for neuromorphic vision testing. The company is registered in England (No. 12551623).', '{"company_type": "Neuromorphic Computing", "website_url": "https://grayscale.ai", "contact_email": "info@grayscale.ai", "contact_linkedin": "https://www.linkedin.com/company/grayscaleai", "location": "London, England, UK", "capabilities": ["Neuromorphic AI algorithms", "Autonomous drone AI systems", "Real-time pattern recognition", "Adaptive decision-making hardware", "Edge AI for robotics", "Neural network optimisation"], "industries": ["Defence & Security", "Logistics", "Emergency Response", "Autonomous Systems", "Robotics"], "employees": "1-9", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quinas Technology Ltd', 'Quinas Technology is a Lancaster University spinout commercialising ULTRARAM, a patented non-volatile memory technology that exploits quantum-mechanical resonant tunnelling to deliver a memory that is simultaneously fast, low-power, and non-volatile. ULTRARAM bridges the performance gap between DRAM and flash storage, retaining data without power and consuming far less energy than conventional RAM, making it highly suitable for AI and edge compute applications. Quinas was selected for the first cohort of the ChipStart UK government-backed semiconductor incubator with Professor Hayne serving as Chief Scientific Officer. The company is based in Lancaster, UK.', '{"company_type": "AI Chip Design", "website_url": "https://quinas.tech", "contact_linkedin": "https://www.linkedin.com/company/quinas-technology", "location": "Lancaster, England, UK", "capabilities": ["ULTRARAM memory chip design", "Resonant tunnelling memory technology", "Non-volatile memory for AI", "Low-power memory semiconductor design", "Edge compute memory chips"], "industries": ["Semiconductors", "Artificial Intelligence", "Edge Computing", "IoT", "High Performance Computing"], "employees": "1-9", "established": 2022, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mach42 Ltd', 'Mach42 (formerly Machine Discovery) is an Oxford Science Park-based AI semiconductor tools company and University of Oxford spinout founded by CTO Brett Larder and CSO Muhammad Kasim, using AI and cloud computing to radically accelerate analog circuit verification in chip design. The company''s proprietary neural network surrogate models generate high-accuracy simulations from minimal data, reducing analog verification time and cost by orders of magnitude and integrating directly with industry-standard EDA tools such as Cadence. Mach42 has formed an AI Advisory Board of semiconductor industry veterans and partners with Cadence Design Systems for next-generation analog verification workflows.', '{"company_type": "AI Chip Design", "website_url": "https://mach42.ai", "contact_email": "info@mach42.ai", "contact_linkedin": "https://www.linkedin.com/company/mach42", "location": "Oxford, England, UK", "capabilities": ["AI-driven analog circuit verification", "Machine learning surrogate models for EDA", "Chip design automation", "Cloud-based simulation acceleration", "Neural network EDA integration"], "industries": ["Semiconductors", "Electronic Design Automation", "Artificial Intelligence", "Chip Design"], "employees": "10-49", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rockley Photonics Ltd', 'Rockley Photonics is a UK-founded silicon photonics company with a registered office in Altrincham, Cheshire, developing silicon photonics platforms for healthcare biometric sensing and data centre optical interconnects. The company designs advanced photonic integrated circuits that combine optical sources, detectors, and modulators on a single chip, enabling non-invasive blood biomarker monitoring and high-bandwidth optical communications. Founded in 2013 and listed on the NYSE (RKLY) in 2021, Rockley serves the medical wearable, consumer electronics, and data centre connectivity markets with its Bioptx and Scorpio photonic platforms. The company exited Chapter 11 restructuring in 2024 and resumed product marketing.', '{"company_type": "Optical Computing", "website_url": "https://rockleyphotonics.com", "contact_email": "contact@rockleyphotonics.com", "contact_linkedin": "https://www.linkedin.com/company/rockley-photonics-limited", "location": "Altrincham, Cheshire, UK", "capabilities": ["Silicon photonics chip design", "Photonic integrated circuit fabrication", "Optical biosensors", "Data centre optical interconnects", "Non-invasive health monitoring chips", "Wearable photonic sensing"], "industries": ["Healthcare", "Consumer Electronics", "Data Centres", "Medical Devices", "Telecommunications"], "employees": "100-249", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Literal Labs Ltd', 'Literal Labs (formerly Mignon Technologies) is a Newcastle upon Tyne-based AI chip company and Newcastle University spinout founded in 2023 by Professor Alex Yakovlev and Dr Rishad Shafik, developing Logic-Based Networks (LBNs) that deliver up to 54 times faster inference with around 52 times less energy consumption than conventional neural networks. The company raised £4.6 million in pre-seed funding from Cambridge Future Tech and doubled its headcount in 2024. Its deterministic, explainable AI chip architecture targets edge, embedded, and industrial AI applications. The company was previously known as Mignon and participated in the ChipStart UK semiconductor incubator.', '{"company_type": "Neuromorphic Computing", "website_url": "https://www.literal-labs.ai", "contact_linkedin": "https://www.linkedin.com/company/literal-labs", "location": "Newcastle upon Tyne, England, UK", "capabilities": ["Logic-Based Network chip design", "Ultra-low-energy AI inference", "Deterministic AI processors", "Explainable AI hardware", "Edge AI chip architecture", "ASIC design for embedded AI"], "industries": ["Artificial Intelligence", "Industrial Automation", "Automotive", "IoT", "Edge Computing"], "employees": "10-49", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Finchetto Ltd', 'Finchetto is a Guildford, Surrey-based photonic computing startup founded in 2020 and based at the Surrey Research Park, developing the world''s first entirely passive, packet-aware photonic network switch for telecoms, data centres, and high-performance computing. The company''s photonic processor leverages light instead of electrons for data routing, delivering faster throughput and significantly lower energy consumption than electronic alternatives, and can compute natively in any numerical base for more efficient data encoding. Finchetto has raised $1.48 million from investors including Silicon Roundabout Ventures, Intel Ignite, and UK Research and Innovation, and won three innovation awards in 2024.', '{"company_type": "Optical Computing", "website_url": "https://finchetto.com", "contact_linkedin": "https://www.linkedin.com/company/finchetto", "location": "Guildford, Surrey, UK", "capabilities": ["Photonic network switch design", "Passive optical networking chips", "Light-speed data routing", "Energy-efficient optical processors", "Photonic computing for HPC", "Multi-base numerical processing"], "industries": ["Data Centres", "Telecommunications", "High Performance Computing", "Networking"], "employees": "1-9", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Paragraf Ltd', 'Paragraf is a Somersham, Cambridgeshire-based semiconductor company and Cambridge University spinout founded in 2015, pioneering the mass production of graphene-based electronic devices using standard semiconductor fabrication processes. The company manufactures Graphene Hall Sensors (GHS) and Graphene Field-Effect Transistors (GFETs) that exploit graphene''s extraordinary electrical and physical properties for applications in quantum sensing, high-frequency electronics, and next-generation memory. In 2024, Paragraf raised $55 million in a Series C round led by UAE sovereign wealth fund Mubadala to scale manufacturing. The company also holds an Innovate UK grant for developing graphene memory devices with Cambridge University.', '{"company_type": "AI Chip Design", "website_url": "https://www.paragraf.com", "contact_email": "enquiries@paragraf.com", "contact_phone": "+44 (0)1223 739782", "contact_linkedin": "https://www.linkedin.com/company/paragrafltd", "location": "Somersham, Cambridgeshire, UK", "capabilities": ["Graphene semiconductor device manufacturing", "Graphene Hall sensor production", "Graphene field-effect transistors", "Novel memory device development", "High-frequency graphene electronics", "Quantum sensor chip fabrication"], "industries": ["Semiconductors", "Quantum Sensing", "High Performance Computing", "Defence", "Scientific Instrumentation"], "employees": "50-99", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Graphcore', 'Graphcore is a British semiconductor company headquartered in Bristol, founded in 2016, that develops Intelligence Processing Units (IPUs) specifically designed for AI and machine learning workloads. Their Colossus MK2 GC200 IPU features 1,472 processor cores and 59.4 billion transistors built on TSMC 7nm process, enabling massively parallel machine intelligence compute for training and inference. Graphcore''s Poplar SDK allows deep integration with major ML frameworks including TensorFlow and PyTorch, and has been adopted by leading cloud and research institutions worldwide. In July 2024 the company was acquired by SoftBank Group for approximately $500 million while continuing to operate under the Graphcore brand from its Bristol headquarters.', '{"company_type": "Inference Accelerator", "website_url": "https://www.graphcore.ai", "contact_email": "info@graphcore.ai", "contact_phone": "+44 117 214 1420", "contact_linkedin": "https://www.linkedin.com/company/graphcore", "location": "Bristol, UK", "capabilities": ["Intelligence Processing Unit (IPU) design", "AI/ML accelerator hardware", "Massively parallel processing", "Machine learning training acceleration", "AI inference acceleration", "Poplar SDK"], "industries": ["Artificial Intelligence", "Machine Learning", "Cloud Computing", "Research & Academia", "Healthcare AI", "Autonomous Systems"], "employees": "500+", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'XMOS', 'XMOS is a Bristol-based fabless semiconductor company founded in 2005 as a University of Bristol spin-out, developing generative Systems-on-Chips (SoCs) that integrate AI inference, digital signal processing, control, and I/O functions in a single low-cost device. Their flagship xcore.ai crossover processor enables real-time AI inferencing at the edge, combining AI capabilities with DSP and communications processing for AIoT applications across voice, audio, and industrial markets. The company has raised over $113 million and its silicon is used in products by Amazon Alexa, Google Assistant-enabled devices, and major consumer audio brands. XMOS also provides the xCORE microcontroller family widely deployed in industrial control and communications systems.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.xmos.com", "contact_email": "info@xmos.com", "contact_phone": "+44 117 927 6004", "contact_linkedin": "https://www.linkedin.com/company/xmos", "location": "Bristol, UK", "capabilities": ["Edge AI processor design", "Digital signal processing SoC", "xcore.ai architecture", "Voice and audio processing hardware", "AIoT hardware development", "Generative SoC design"], "industries": ["Consumer Electronics", "Industrial IoT", "Smart Home", "Automotive", "Voice/Audio Technology", "Embedded Systems"], "employees": "50-99", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pragmatic Semiconductor', 'Pragmatic Semiconductor, headquartered at Cambridge Science Park and manufacturing in Sedgefield, County Durham, is a pioneer in flexible integrated circuit technology, designing and manufacturing ultra-thin FlexICs using thin-film transistor (TFT) processes for IoT, retail, and consumer goods applications. Founded in 2010, Pragmatic opened the UK''s first 300mm semiconductor wafer fabrication line at Pragmatic Park in 2024, enabling high-volume production of flexible chips thinner than a human hair that can be embedded into packaging, wearables, and everyday objects. The company has raised approximately £182 million and launched its Gen 3 flexible ASIC platform in 2025 with a 10x digital power improvement over the previous generation. Pragmatic counts major FMCG, retail, healthcare, and supply chain brands among its growing customer base.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.pragmaticsemi.com", "contact_email": "info@pragmaticsemi.com", "contact_phone": "+44 1223 855010", "contact_linkedin": "https://www.linkedin.com/company/pragmatic-semiconductor", "location": "Cambridge / Sedgefield, Durham, UK", "capabilities": ["Flexible ASIC design", "Thin-film transistor (TFT) fabrication", "FlexIC manufacturing", "300mm wafer fabrication", "NFC flexible chip design", "Low-cost semiconductor manufacturing"], "industries": ["Retail & Packaging", "IoT", "Consumer Goods", "Healthcare", "Wearables", "Supply Chain"], "employees": "250-499", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Paragraf', 'Paragraf is a Cambridge University spin-out founded in 2018 that is the world''s first company to mass-produce graphene-based electronic devices using standard semiconductor fabrication processes, with manufacturing sites in Somersham and Huntingdon, Cambridgeshire. The company manufactures Graphene Hall Sensors (GHS) and Graphene Field-Effect Transistors (GFETs) that outperform silicon equivalents in magnetic sensing, biosensing, and extreme environment applications, including cryogenic quantum computing environments. Paragraf''s proprietary graphene deposition process enables single-atom-thick graphene to be deposited and patterned using conventional semiconductor equipment at wafer scale. The company has raised $140 million across three funding rounds and supplies devices to automotive, industrial automation, cryogenic, and agri-tech markets globally.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.paragraf.com", "contact_email": "enquiries@paragraf.com", "contact_phone": "+44 1223 739782", "contact_linkedin": "https://www.linkedin.com/company/paragrafltd", "location": "Somersham, Cambridgeshire, UK", "capabilities": ["Graphene device fabrication", "Graphene Hall Sensors", "Graphene Field-Effect Transistors", "Semiconductor foundry services", "Magnetic sensing hardware", "Extreme environment electronics"], "industries": ["Automotive", "Industrial Automation", "Healthcare", "Cryogenics", "Defence", "Scientific Instrumentation"], "employees": "50-99", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'EnSilica', 'EnSilica is a publicly listed (London AIM: ENSI) fabless ASIC design and supply company headquartered in Abingdon, Oxfordshire, founded in 2001, specialising in custom chip design for OEMs and system houses across automotive, industrial, healthcare, and communications markets. The company provides world-class expertise in RF, mmWave, mixed-signal, and digital IC design, offering full turnkey ASIC services from specification through to volume production with design centres across the UK, India, and Brazil. Notable recent wins include an ASIC for AST SpaceMobile''s next-generation satellite broadband constellation and AI accelerator chips for industrial edge applications. EnSilica has established itself as one of the UK''s largest and most experienced independent fabless ASIC design houses.', '{"company_type": "FPGA Design", "website_url": "https://www.ensilica.com", "contact_email": "sales@ensilica.com", "contact_phone": "+44 118 321 7310", "contact_linkedin": "https://www.linkedin.com/company/ensilica", "location": "Abingdon, Oxfordshire, UK", "capabilities": ["Custom ASIC design", "RF and mmWave IC design", "Mixed-signal IC design", "SoC architecture", "IC verification and testing", "Turnkey ASIC supply"], "industries": ["Automotive", "Industrial", "Healthcare", "Telecommunications", "Satellite Communications", "Consumer Electronics"], "employees": "100-249", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aion Silicon', 'Aion Silicon (formerly Sondrel, rebranded April 2025) is a premier ASIC and SoC architecture and design partner headquartered in Reading, Berkshire, with over 20 years of experience delivering complex custom chip designs for AI, automotive, HPC, 5G, and networking applications. The company has completed multi-billion transistor chip designs at 5nm for clients including Apple, Sony (PlayStation), Meta (Oculus), Tesla, and Samsung, and joined the Intel Foundry Accelerator programme in 2025. Aion Silicon employs approximately 243 professionals across design centres in the UK, India, Morocco, and Barcelona, and holds ISO 9001 and ISO/IEC 27001 certifications. The company''s proprietary Advanced Modelling Process for AI chips optimises the complex interaction between AI processors and memory hierarchies at the SoC architecture stage.', '{"company_type": "FPGA Design", "website_url": "https://www.aionsilicon.com", "contact_email": "info@aionsilicon.com", "contact_phone": "+44 118 983 0000", "contact_linkedin": "https://www.linkedin.com/company/sondrel", "location": "Reading, Berkshire, UK", "certifications": ["ISO 9001", "ISO/IEC 27001"], "capabilities": ["ASIC design", "SoC architecture", "AI chip design", "5nm chip design", "Front-end and back-end design services", "Advanced AI chip modelling"], "industries": ["Artificial Intelligence", "Automotive", "HPC", "5G Telecommunications", "Consumer Electronics", "Networking"], "employees": "250-499", "established": 2002, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ITDev', 'ITDev is an electronics and software engineering design services company founded in 2000, based at Southampton Science Park in Hampshire, providing specialist FPGA design, embedded software, and hardware development services to defence, aerospace, medical, and commercial sectors. The company works across a wide range of FPGA families from Spartan through to Virtex and Xilinx Zynq programmable SoC platforms, delivering complex real-time signal processing and AI-accelerated systems. ITDev was named Tech Employer at the South Coast Tech Awards and develops its own FPGA video IP cores alongside bespoke customer-specific designs. The firm provides a complete multi-disciplinary engineering team covering FPGA design, hardware design, embedded software, and digital signal processing.', '{"company_type": "FPGA Design", "website_url": "https://www.itdev.co.uk", "contact_email": "info@itdev.co.uk", "contact_phone": "+44 23 8098 8890", "contact_linkedin": "https://www.linkedin.com/company/itdev", "location": "Southampton, Hampshire, UK", "capabilities": ["FPGA design", "Embedded software development", "FPGA IP core development", "SoC design (Xilinx Zynq)", "Real-time signal processing systems", "Hardware and PCB design"], "industries": ["Defence", "Aerospace", "Communications", "Industrial", "Medical Devices", "Research & Development"], "employees": "10-49", "established": 2000, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Doulos', 'Doulos is the global industry leader in training and consulting for digital hardware and semiconductor design, headquartered in Ringwood, Hampshire, UK, and founded in 1990. The company trains engineers in FPGA design, ASIC design, VHDL, SystemVerilog, SystemC, and EDA technologies, having educated engineers at more than 5,400 organisations across 84 countries since setting the industry standard for VHDL training in 1991. Doulos is a certified training partner with AMD/Xilinx, Intel FPGA, Lattice Semiconductor, and Microchip, and provides both open-enrolment and customised in-house training programmes worldwide. With approximately 109 employees across five continents, Doulos also provides specialist consultancy services for complex semiconductor and FPGA design challenges.', '{"company_type": "FPGA Design", "website_url": "https://www.doulos.com", "contact_email": "info@doulos.com", "contact_phone": "+44 1425 471223", "contact_linkedin": "https://www.linkedin.com/company/doulos", "location": "Ringwood, Hampshire, UK", "capabilities": ["FPGA design training", "ASIC design training", "VHDL and SystemVerilog training", "Semiconductor design consulting", "EDA tool training", "Embedded systems training"], "industries": ["Semiconductor", "Defence", "Aerospace", "Automotive", "Consumer Electronics", "Telecommunications"], "employees": "100-249", "established": 1990, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Plextek', 'Plextek is a technology engineering and consulting company founded in 1989, based near Cambridge in Great Chesterford, Essex, specialising in advanced radar, RF communications, sensing, and edge AI hardware development for government and commercial clients. With over 35 years of experience, Plextek designs low-SWaP RF electronics, FPGA-based signal processing systems, and sensor fusion platforms for counter-drone, border security, and autonomous systems applications. The company embeds AI and data science directly into hardware for real-time edge inference in mission-critical scenarios, and has spun out several successful companies including Blighter Surveillance Systems and PRFI. Plextek employs around 85 engineers and scientists, many with SC or DV clearance for classified programme work.', '{"company_type": "FPGA Design", "website_url": "https://www.plextek.com", "contact_email": "hello@plextek.com", "contact_phone": "+44 1799 533200", "contact_linkedin": "https://www.linkedin.com/company/plextek", "location": "Great Chesterford, Essex (near Cambridge), UK", "capabilities": ["FPGA-based signal processing systems", "Radar system design", "Edge AI hardware integration", "RF electronics design", "Sensor fusion platforms", "Counter-drone systems"], "industries": ["Defence", "Border Security", "Aerospace", "Autonomous Systems", "Government", "Industrial Sensing"], "employees": "50-99", "established": 1989, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Iceotope Technologies', 'Iceotope Technologies is the global leader in precision liquid cooling for AI and HPC data centres, headquartered at the Advanced Manufacturing Park in Sheffield, UK, and founded in 2005. The company''s patented chassis-level immersion cooling technology wraps each server in a sealed cooling environment, achieving up to 40% reduction in CO2 emissions, 96% less water use, and 40% less power consumption compared to conventional air-cooled systems. Iceotope''s KUL AI system supports up to 8 high-density GPUs per server and enables 4-6x compute density improvements, specifically designed for the extreme thermal demands of AI accelerator hardware. The company launched Iceotope Labs at its Sheffield HQ in 2024, the industry''s first dedicated liquid cooling research and testing facility, and holds over 175 granted and pending patents.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.iceotope.com", "contact_email": "info@iceotope.com", "contact_phone": "+44 1142 245500", "contact_linkedin": "https://www.linkedin.com/company/iceotope", "location": "Sheffield, South Yorkshire, UK", "capabilities": ["Precision liquid cooling systems", "Chassis-level immersion cooling", "AI infrastructure thermal management", "HPC cooling hardware", "Data centre energy efficiency", "GPU server cooling systems"], "industries": ["Data Centres", "HPC", "Artificial Intelligence", "Telecommunications", "Cloud Computing", "Financial Services"], "employees": "100-249", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kao Data', 'Kao Data is a UK-based developer and operator of advanced data centres specifically engineered for AI, HPC, and high-density compute workloads, founded in 2014 and headquartered in Harlow, Essex. The company operates a growing campus in Harlow east of London and is expanding into Greater Manchester, with all sites incorporating liquid cooling infrastructure and designed to NVIDIA DGX-Ready standards for the most demanding AI hardware. Kao Data hosted the Cambridge-1 AI supercomputer and provides specialist colocation services for research institutions, cloud providers, and enterprises deploying large GPU clusters for AI training and inference. The company is led by CEO Lee Myall and is recognised as the UK''s premier specialist AI and HPC colocation provider.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.kaodata.com", "contact_email": "info@kaodata.com", "contact_phone": "+44 1279 937400", "contact_linkedin": "https://www.linkedin.com/company/kao-data", "location": "Harlow, Essex, UK", "certifications": ["NVIDIA DGX-Ready"], "capabilities": ["AI-optimised colocation", "HPC infrastructure", "High-density GPU hosting", "Liquid cooling data centre infrastructure", "Secure data centre operations", "AI supercomputer hosting"], "industries": ["Artificial Intelligence", "HPC", "Research & Academia", "Cloud Computing", "Life Sciences", "Financial Services"], "employees": "10-49", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nscale', 'Nscale is a UK-founded AI hyperscaler and vertically integrated compute infrastructure company, incorporated in London in May 2024 as a spin-out from renewable energy infrastructure firm Arkon Energy. The company provides GPU compute, networking, storage, and managed AI services through its own and colocated data centres, and has been selected by OpenAI as the host for Stargate UK. Nscale raised $1.1 billion in Series B funding in September 2025 (the largest in European history at the time), committed to investing £2 billion in UK data centre infrastructure, with its first UK site in Loughton, Essex designed to house 23,040 NVIDIA GB300 GPUs. The company has partnered with Microsoft, NVIDIA, and OpenAI and employs approximately 120 professionals.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.nscale.com", "contact_email": "admin@nscale.tech", "contact_linkedin": "https://www.linkedin.com/company/nscale-cloud", "location": "London, UK", "capabilities": ["GPU cluster infrastructure", "AI compute-as-a-service", "Data centre development and operation", "AI training infrastructure", "AI inference infrastructure", "Managed AI services"], "industries": ["Artificial Intelligence", "Cloud Computing", "HPC", "Research & Academia", "Enterprise AI", "Government"], "employees": "100-249", "established": 2024, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'OCF Ltd', 'OCF is a Sheffield-based specialist HPC and AI infrastructure integrator founded in 2002, supplying UK and Irish research institutions, universities, and industry with bespoke high-performance computing clusters, GPU compute systems, and AI deep learning hardware. The company designs, integrates, installs, and supports end-to-end HPC solutions and has built some of the UK''s most powerful university research computing facilities. OCF holds IBM Business Partner status and employs approximately 64 professionals, many with security clearance (SC and DV) for government and defence-adjacent projects. The company also delivers cloud HPC solutions, storage systems, and AI-optimised compute environments for enterprise clients.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.ocf.co.uk", "contact_email": "support@ocf.co.uk", "contact_phone": "+44 114 257 2200", "contact_linkedin": "https://www.linkedin.com/company/ocf-limited", "location": "Sheffield, South Yorkshire, UK", "capabilities": ["HPC cluster integration", "GPU computing infrastructure", "AI deep learning systems", "Storage solutions", "Cloud HPC", "Systems support and managed services"], "industries": ["Research & Academia", "Government", "Defence", "Life Sciences", "Engineering", "Financial Services"], "employees": "50-99", "established": 2002, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fractile', 'Fractile is a British AI chip startup founded in 2022 by Dr Walter Goodwin (University of Oxford Robotics PhD), headquartered in London with engineering operations in Bristol and a new facility planned following a £100 million UK investment commitment. The company is developing in-memory compute chips specifically designed to run large language models at least 100x faster and 10x cheaper than Nvidia GPU equivalents by eliminating the data movement bottleneck inherent in conventional processor-memory architectures. Fractile raised $15 million in seed funding in July 2024 backed by Kindred Capital, NATO Innovation Fund, Oxford Science Enterprises, and former Intel CEO Pat Gelsinger. The chips are designed as server-grade AI inference infrastructure targeting large-scale LLM deployment in cloud and enterprise environments.', '{"company_type": "Inference Accelerator", "website_url": "https://www.fractile.ai", "contact_email": "hello@fractile.ai", "contact_linkedin": "https://www.linkedin.com/company/fractile", "location": "London / Bristol, UK", "capabilities": ["In-memory compute chip design", "LLM inference acceleration", "AI chip architecture", "Custom silicon for AI inference", "On-chip memory compute", "AI inference server hardware"], "industries": ["Artificial Intelligence", "Large Language Models", "Cloud Computing", "AI Infrastructure", "Research & Development"], "employees": "10-49", "established": 2022, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Olix', 'Olix (formerly Flux Computing) is a London-based photonic AI chip startup founded in 2024 by James Dacombe, developing the Optical Tensor Processing Unit (OTPU), a next-generation AI inference accelerator that integrates SRAM-based memory architecture with photonics to dramatically outperform conventional GPU systems in energy efficiency and inference throughput per watt. The company raised $250 million in total funding including a $220 million round led by Hummingbird Ventures at a $1 billion valuation, making it one of the UK''s newest unicorns. Olix employs over 70 professionals across London, Bristol, Austin, San Francisco, and Toronto, with first commercial OTPU products targeted for 2027. The architecture eliminates the need for expensive high-bandwidth memory (HBM), significantly reducing cost and energy per inference token.', '{"company_type": "Inference Accelerator", "website_url": "https://www.olix.com", "contact_email": "info@olix.com", "contact_linkedin": "https://www.linkedin.com/company/olix-computing", "location": "London / Bristol, UK", "capabilities": ["Photonic AI chip design", "Optical Tensor Processing Unit (OTPU)", "AI inference acceleration", "SRAM memory architecture integration", "Photonic integrated circuit design", "Next-generation AI accelerator hardware"], "industries": ["Artificial Intelligence", "Cloud Computing", "Data Centres", "HPC", "AI Infrastructure"], "employees": "50-99", "established": 2024, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lumai', 'Lumai is an Oxford University spin-out founded in 2022, based at the Wood Centre for Innovation in Headington, Oxford, developing 3D optical computing processors for AI data centre applications that bypass the energy and bandwidth limitations of silicon GPUs and conventional integrated photonics. The company''s technology processes transformer model matrix multiply operations within optical beams propagating through three-dimensional free space, targeting order-of-magnitude improvements in AI compute energy efficiency and throughput. Lumai raised over $10 million in Series A funding in April 2025 led by Constructor Capital, and has received Innovate UK Smart Grant support. Founded by CEO Dr Xianxin Guo and CTO Dr James Spall, both former University of Oxford physics researchers, the company targets data centre AI inference acceleration.', '{"company_type": "Inference Accelerator", "website_url": "https://www.lumai.ai", "contact_email": "hello@lumai.ai", "contact_phone": "+44 1865 546516", "contact_linkedin": "https://www.linkedin.com/company/lumaitech", "location": "Oxford, UK", "capabilities": ["3D optical computing", "Photonic AI processor design", "LLM inference acceleration", "Optical data centre hardware", "Free-space optical compute", "Energy-efficient AI hardware"], "industries": ["Artificial Intelligence", "Data Centres", "Cloud Computing", "HPC", "Research & Academia"], "employees": "10-49", "established": 2022, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Vaire Computing', 'Vaire Computing is a London and Cambridge-based deep tech semiconductor company founded in 2021, pioneering reversible computing architecture to deliver near-zero energy AI processing chips for data centres and edge deployments. The company''s reversible computing approach allows energy to be recovered and recycled during computation rather than dissipated as heat, with initial test chips demonstrating up to 50% energy savings compared to conventional silicon processors running equivalent AI workloads. Vaire''s technology targets the thermodynamic limits of conventional CMOS computing that constrain AI infrastructure''s exponential growth, aiming to become an alternative architecture to GPUs for AI inference. Founded by CEO Rodolfo Rosini and CTO Dr Hannah Earley (Cambridge Applied Mathematics PhD), the company raised $4.5 million in seed funding in 2024.', '{"company_type": "Inference Accelerator", "website_url": "https://www.vaire.co", "contact_email": "hello@vaire.co", "contact_linkedin": "https://www.linkedin.com/company/vaire-computing", "location": "London / Cambridge, UK", "capabilities": ["Reversible computing chip design", "Near-zero energy processors", "AI compute hardware", "Energy recovery computing architecture", "Custom semiconductor design", "Low-power AI processing"], "industries": ["Artificial Intelligence", "Data Centres", "Cloud Computing", "Research & Development", "HPC"], "employees": "10-49", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HyperCIM', 'HyperCIM is a London-based deep tech semiconductor startup incorporated in December 2023, developing the Latency Processing Unit (LPU), a compute-in-memory co-processor designed to accelerate AI and machine learning data pipelines by processing data directly where it is stored, eliminating the memory bandwidth bottleneck of conventional processor architectures. The company''s technology targets latency-critical applications including high-frequency trading FIX protocol processing, e-commerce dynamic pricing, real-time gaming cheat detection, and 5G network management use cases. Founded by CEO Dr Tanyaradzwa N. Mangoma, HyperCIM is a participant in the UK''s SiliconCatalyst ChipStart accelerator programme. The LPU is positioned as a power-efficient, ultra-low-latency complement to conventional CPU and GPU architectures.', '{"company_type": "Inference Accelerator", "website_url": "https://www.hypercim.com", "contact_email": "info@hypercim.com", "contact_linkedin": "https://www.linkedin.com/company/hypercim", "location": "London, UK", "capabilities": ["Compute-in-memory hardware", "Latency Processing Unit (LPU) design", "AI inference acceleration", "Low-latency co-processor design", "Memory architecture innovation", "Custom semiconductor design"], "industries": ["Financial Services", "Artificial Intelligence", "Gaming", "Telecommunications", "E-commerce", "Data Analytics"], "employees": "10-49", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Chipletti', 'Chipletti is a Cambridge-based fabless semiconductor design startup incorporated in February 2024, developing advanced memory chiplets and licensable chiplet interconnect IP to overcome the memory bandwidth bottleneck that limits large-scale AI inference workloads. The company enables cost-effective 3D stacking of memory and compute dies through its proprietary interconnect technology, targeting AI inference accelerator and data centre processor designers who need to dramatically increase memory capacity and bandwidth without resorting to expensive high-bandwidth memory (HBM). Chipletti is a participant in the UK''s SiliconCatalyst ChipStart incubator programme and presented at the UK Microelectronics 2025 conference. The company represents a new generation of UK fabless semiconductor design addressing AI-specific memory architecture challenges.', '{"company_type": "Inference Accelerator", "website_url": "https://www.chipletti.com", "contact_email": "info@chipletti.com", "contact_linkedin": "https://www.linkedin.com/company/chipletti", "location": "Cambridge, UK", "capabilities": ["3D chiplet design", "Memory chiplet development", "Chiplet interconnect IP licensing", "AI inference memory solutions", "3D stacking technology", "Fabless chip design"], "industries": ["Artificial Intelligence", "Data Centres", "HPC", "AI Inference", "Semiconductor IP"], "employees": "10-49", "established": 2024, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'StackHPC', 'StackHPC is a Bristol-based HPC and cloud infrastructure specialist founded in 2016, focusing on the convergence of high-performance computing, AI infrastructure, and OpenStack cloud technologies for research and enterprise clients across the UK and globally. The company builds and manages large-scale GPU cluster deployments and AI compute environments, and was a key vendor partner for the UK''s DAWN AI supercomputer project at Cambridge, one of the UK''s first national AI Research Resource systems. StackHPC provides software-defined HPC infrastructure, container orchestration for AI workloads, and OpenStack cloud management, and is recognised as one of Europe''s leading OpenStack consultancies. The company employs around 12 engineers with deep specialised expertise in HPC system administration and AI infrastructure deployment.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.stackhpc.com", "contact_email": "info@stackhpc.com", "contact_linkedin": "https://www.linkedin.com/company/stackhpc-ltd", "location": "Bristol, UK", "capabilities": ["OpenStack cloud deployment", "HPC cluster management", "GPU infrastructure for AI", "AI compute environments", "Software-defined networking", "Container orchestration for HPC"], "industries": ["Research & Academia", "Government", "HPC", "Artificial Intelligence", "Cloud Computing"], "employees": "10-49", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'FlexEnable', 'FlexEnable is a Cambridge-based flexible electronics technology company founded in 2015 as a University of Cambridge Cavendish Laboratory spin-out, developing flexible organic thin-film transistor (OTFT) technology and FlexiOM materials for displays, active optics, and sensing applications at the edge. The company holds approximately 450 patents globally for OTFT processes and device architectures, and has established technology transfer programmes with major Asian display manufacturers for high-volume production. FlexEnable''s ultra-low-temperature processing (below 100°C) enables organic transistors to be fabricated on low-cost flexible plastic substrates, enabling new form factors for AI-enabled sensing, gesture recognition, and display systems in automotive and consumer electronics applications. The company won the Society of Information Display Display Component of the Year Award in 2025 for its FlexiOM OTFT materials.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.flexenable.com", "contact_email": "info@flexenable.com", "contact_phone": "+44 1223 706000", "contact_linkedin": "https://www.linkedin.com/company/flexenable", "location": "Cambridge, UK", "capabilities": ["Flexible organic TFT design", "OTFT materials development", "Flexible display technology", "Active optics hardware", "Flexible sensor arrays", "FlexiOM material supply"], "industries": ["Automotive", "Consumer Electronics", "Healthcare", "Industrial", "Wearables", "Display Technology"], "employees": "50-99", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Salience Labs', 'Salience Labs is an Oxford University spin-out founded in 2021 by Vaysh Kewada and Johannes Feldmann, based at Milton Park near Oxford, developing photonic switches for AI data centre networking infrastructure to solve the bandwidth and latency bottlenecks that limit large AI training and inference clusters. The company''s silicon photonic switch technology enables all-optical, multi-hop large cluster connectivity between GPU and AI accelerator nodes, building on over 10 years of research into silicon photonics at the University of Oxford and University of Münster. Salience Labs raised $11.5 million in seed funding in 2022 led by Cambridge Innovation Capital and Oxford Science Enterprises, and a further $30 million in 2025 to expand its photonic switch product line. The company''s switches are designed to be compatible with existing data centre architecture, enabling drop-in upgrades to optical networking.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.saliencelabs.ai", "contact_email": "info@saliencelabs.ai", "contact_linkedin": "https://www.linkedin.com/company/salience-labs", "location": "Oxford (Milton Park), UK", "capabilities": ["Silicon photonic switch design", "All-optical AI networking", "Data centre interconnect hardware", "Photonic integrated circuit fabrication", "Low-latency optical networking", "AI cluster connectivity"], "industries": ["Data Centres", "Artificial Intelligence", "HPC", "Cloud Computing", "Telecommunications"], "employees": "10-49", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oriole Networks', 'Oriole Networks is a London-based photonic networking startup founded in 2023 as a University College London (UCL) spin-out, developing PRISM (Photonic Routing Infrastructure for Scalable Models), claimed to be the world''s first full-photonic switched network designed for AI data centres and HPC deployments. The company''s all-optical network replaces electrical switching fabric with photonic switches, dramatically reducing the latency, power consumption, and cost of interconnecting thousands of AI accelerators in large GPU training and inference clusters. Oriole Networks raised $22 million in Series A funding in October 2024 backed by leading deep tech investors. Founded by James Regan, Joshua Benjamin, Georgios Zervas, and Alessandro Ottino, the company is headquartered at City Road, London.', '{"company_type": "Data Centre Hardware", "website_url": "https://www.oriolenetworks.com", "contact_email": "info@oriolenetworks.com", "contact_linkedin": "https://www.linkedin.com/company/oriole-networks", "location": "London, UK", "capabilities": ["All-optical network switching", "Photonic AI data centre networking", "PRISM photonic fabric", "GPU cluster interconnect", "Low-latency optical switching", "Scalable AI networking hardware"], "industries": ["Data Centres", "Artificial Intelligence", "HPC", "Cloud Computing", "Networking"], "employees": "10-49", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'FocalPoint Positioning', 'FocalPoint Positioning is a Cambridge University spin-out founded in 2015 by Dr Ramsey Faragher, developing AI-powered Supercorrelation GNSS signal processing technology that dramatically improves the accuracy, reliability, and resilience of GPS and satellite navigation in urban environments, near structures, and under electronic jamming or spoofing attacks. The company''s chip-level software works within existing GNSS receivers without additional hardware, and has been licensed to u-blox and STMicroelectronics for integration into next-generation automotive and consumer positioning chips. FocalPoint has raised over £29 million in total funding, signed a strategic partnership with General Motors for automotive GPS, and operates from Cambridge and Bristol with a US office.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.focalpointpositioning.com", "contact_email": "info@focalpointpositioning.com", "contact_linkedin": "https://www.linkedin.com/company/fppnt", "location": "Cambridge, UK", "capabilities": ["AI-powered GNSS signal processing", "Supercorrelation technology", "GNSS resilience algorithms", "Anti-spoofing and anti-jamming", "Automotive positioning IP", "Edge AI signal processing"], "industries": ["Automotive", "Drones & UAV", "IoT", "Maritime", "Defence", "Smart Cities"], "employees": "10-49", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CML Micro Design Services', 'CML Micro Design Services (formerly PRFI Ltd, originally Plextek RF Integration) is a specialist microwave and millimetre-wave IC design house based in Ickleton, Cambridge, providing custom MMIC and RFIC design services for radar, communications, electronic warfare, and 5G infrastructure applications. The company''s RF and microwave ASIC design capability was developed within Plextek from 1996, spun out as an independent company in 2015, and acquired by CML Microsystems in 2020, providing continuity of specialist GaAs, GaN, and SiGe chip design services. CML Micro Design Services covers frequency ranges from MHz through to W-band (94 GHz) and was appointed as a GaAs MMIC design services partner for 5G by Sanan IC, one of China''s largest compound semiconductor foundries. The company serves defence primes, commercial radar OEMs, satellite manufacturers, and 5G equipment vendors.', '{"company_type": "FPGA Design", "website_url": "https://www.prfi.com", "contact_email": "designservices@cmlmicro.com", "contact_phone": "+44 1799 796464", "contact_linkedin": "https://www.linkedin.com/company/plextek-rf-integration", "location": "Ickleton, Cambridge, UK", "capabilities": ["MMIC chip design", "RF ASIC design", "GaAs/GaN/SiGe chip design", "mmWave circuit design to W-band", "Radar IC development", "Electronic warfare chip design"], "industries": ["Defence", "Aerospace", "Radar", "Electronic Warfare", "5G Telecommunications", "Satellite"], "employees": "10-49", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nallatech', 'Nallatech is a pioneering Scottish FPGA computing company founded in 1993 in Cumbernauld, North Lanarkshire by Allan Cantle, and one of the earliest companies globally to commercialise FPGA-based high-performance computing acceleration boards for signal processing and HPC markets. The company designs FPGA acceleration cards and PCIe-based compute platforms for signal processing, networking, HPC, and AI inference, and has a long history supplying FPGA hardware to defence, intelligence, and high-performance computing clients in the UK, Europe, and North America. Nallatech was acquired by Interconnect Systems in 2008 and subsequently by Molex in 2016, and continues as a specialist FPGA hardware supplier with European design and support operations. The company was a founding member of the Scottish FPGA High Performance Computing Alliance formed in 2005.', '{"company_type": "FPGA Design", "website_url": "https://www.nallatech.com", "contact_email": "info@nallatech.com", "contact_phone": "+44 1236 789567", "contact_linkedin": "https://www.linkedin.com/company/nallatech", "location": "Cumbernauld, North Lanarkshire, Scotland, UK", "capabilities": ["FPGA acceleration board design", "FPGA-based HPC acceleration", "Signal processing hardware", "AI inference FPGA platforms", "PCIe accelerator cards", "FPGA system integration"], "industries": ["Defence", "Signal Processing", "Telecommunications", "HPC", "AI Acceleration", "Networking"], "employees": "50-99", "established": 1993, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Embecosm', 'Embecosm is a Southampton-based open-source compiler and AI toolchain specialist founded in 2008, providing custom GCC and LLVM compiler development, RISC-V toolchain engineering, and AI software optimisation services for semiconductor companies, SoC designers, and edge AI hardware manufacturers worldwide. The company develops production-quality open-source compilers and has contributed significantly to the GCC and LLVM communities, serving clients including leading semiconductor companies building AI-specific processor architectures. Embecosm extended PyTorch AI support to RISC-V embedded devices in partnership with Ashling in 2025, and provides the full software stack needed to bring AI capabilities to custom edge silicon. With 17 employees across offices in Southampton (UK), Nuremberg (Germany), and France, Embecosm serves some of the world''s most demanding embedded and edge AI compute customers.', '{"company_type": "Edge AI Hardware", "website_url": "https://www.embecosm.com", "contact_email": "info@embecosm.com", "contact_phone": "+44 23 8076 6877", "contact_linkedin": "https://www.linkedin.com/company/embecosm", "location": "Southampton, Hampshire, UK", "capabilities": ["GCC and LLVM compiler development", "RISC-V toolchain engineering", "AI software stack for custom silicon", "Edge AI toolchain optimisation", "Open-source compiler consulting", "Embedded OS services"], "industries": ["Semiconductor", "Edge AI", "Automotive", "Industrial IoT", "Research & Academia", "Embedded Systems"], "employees": "10-49", "established": 2008, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


