INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Quantum Circuits (OQC)', 'Oxford Quantum Circuits (OQC) is a UK quantum computing company founded in 2017 as a spin-out from the University of Oxford. It is Europe''s first Quantum-Compute-as-a-Service (QCaaS) provider and the only company deploying superconducting quantum systems into commercial data centres. OQC builds processors using its proprietary Coaxmon architecture and operates deployments in London and Tokyo. The company completed a landmark $100 million Series B in 2024, one of the largest quantum funding rounds in Europe.', '{"company_type": "Quantum Processor", "website_url": "https://oqc.tech", "contact_linkedin": "https://uk.linkedin.com/company/oqc", "location": "Reading, Berkshire, UK", "capabilities": ["Superconducting qubit processors (Coaxmon architecture)", "Quantum-Compute-as-a-Service (QCaaS)", "Quantum error correction", "Quantum cloud access", "Commercial data centre quantum deployments"], "industries": ["Finance", "Pharmaceuticals", "Defence", "Logistics", "Research"], "employees": "100-200", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Riverlane', 'Riverlane is a Cambridge-based quantum computing company building the error correction stack for quantum computers, founded in 2016 by Steve Brierley. The company develops quantum error correction (QEC) hardware and software working across all qubit types, with its Deltaflow platform providing real-time error decoding. Riverlane raised $75 million in its Series C round, is a UK Quantum Missions Pilot participant, and integrated its second-generation QEC technology with OQC quantum computers in 2025.', '{"company_type": "Quantum Software", "website_url": "https://www.riverlane.com", "contact_linkedin": "https://www.linkedin.com/company/river-lane-research-ltd", "location": "Cambridge, UK", "capabilities": ["Quantum error correction (QEC)", "Deltaflow quantum operating system", "Real-time error decoding hardware", "Multi-platform QEC stack integration", "Fault-tolerant quantum computing"], "industries": ["Quantum Computing", "Defence", "Research", "Finance"], "employees": "51-200", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Motion', 'Quantum Motion is a London-based quantum computing company pioneering silicon-based quantum processors using standard CMOS manufacturing. Founded in 2017 by Professor John Morton (UCL) and Professor Simon Benjamin (Oxford), the company delivered the industry''s first full-stack silicon CMOS quantum computer to the UK National Quantum Computing Centre in 2025, using 300mm wafer technology. Quantum Motion raised £42 million in the largest single quantum investment in UK history.', '{"company_type": "Quantum Processor", "website_url": "https://quantummotion.com", "contact_linkedin": "https://uk.linkedin.com/company/quantum-motion-tech", "location": "London, UK", "capabilities": ["Silicon CMOS spin qubit processors", "Full-stack silicon quantum computing", "300mm wafer CMOS fabrication compatibility", "Silicon qubit characterisation", "Scalable quantum processor design"], "industries": ["Semiconductors", "Quantum Computing", "Defence", "Research"], "employees": "100-200", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Ionics', 'Oxford Ionics was an Oxford-based quantum computing company that developed Electronic Qubit Control (EQC), enabling trapped ions to be controlled using classical chips rather than lasers. Founded by Dr Tom Harty and Dr Chris Ballance, the company held world records in single-qubit gate fidelity, two-qubit gate fidelity, and state preparation and measurement. Oxford Ionics delivered a full-stack trapped-ion quantum computer to the UK NQCC before being acquired by IonQ in September 2025 in a $1.1 billion deal.', '{"company_type": "Ion Trap Systems", "website_url": "https://www.oxionics.com", "contact_linkedin": "https://www.linkedin.com/company/oxfordionics", "location": "Oxford, UK", "capabilities": ["Trapped-ion quantum processors", "Electronic Qubit Control (EQC)", "World-record quantum gate fidelity", "Ion trap chip fabrication", "Full-stack trapped-ion systems"], "industries": ["Quantum Computing", "Defence", "Research", "Finance"], "employees": "51-150", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ORCA Computing', 'ORCA Computing is a London-based quantum computing company developing full-stack photonic quantum computers operating at room temperature, eliminating cryogenic cooling. Founded in 2019 as a University of Oxford spin-out by Professor Ian Walmsley, Dr Richard Murray, and Dr Josh Nunn, the company has delivered photonic quantum systems to the UK Ministry of Defence and the National Quantum Computing Centre. ORCA''s proprietary quantum memory fiber loop technology uses single photons to process quantum information.', '{"company_type": "Quantum Photonics", "website_url": "https://orcacomputing.com", "contact_phone": "+44 20 8068 2935", "contact_linkedin": "https://uk.linkedin.com/company/orcacomputing", "location": "London, UK", "capabilities": ["Room-temperature photonic quantum computing", "Quantum memory fiber loop technology", "On-premises quantum system deployment", "Photonic quantum-AI hybrid applications", "Quantum machine learning"], "industries": ["Defence", "Finance", "Quantum Computing", "Research", "Cybersecurity"], "employees": "51-100", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nu Quantum', 'Nu Quantum is a Cambridge-based quantum networking company developing photonic hardware to enable distributed quantum computing, founded in 2018 as a University of Cambridge spin-out. The company produces Qubit-Photon Interfaces and Quantum Networking Units connecting processors of any qubit modality. Nu Quantum raised $60 million in its Series A round, opened a dedicated trapped-ion quantum networking laboratory in Cambridge in 2026, and collaborates with CERN on White Rabbit quantum timing technology.', '{"company_type": "Quantum Networking", "website_url": "https://www.nu-quantum.com", "contact_linkedin": "https://uk.linkedin.com/company/nu-quantum", "location": "Cambridge, UK", "capabilities": ["Qubit-Photon Interfaces (QPIs)", "Quantum Networking Units (QNUs)", "Distributed quantum computing networks", "Entanglement distribution", "Quantum repeater technology"], "industries": ["Quantum Computing", "Telecommunications", "Defence", "Research"], "employees": "46-100", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantinuum', 'Quantinuum is the world''s largest integrated quantum computing company, formed in 2021 from the merger of Cambridge Quantum Computing and Honeywell Quantum Solutions, and headquartered in Cambridge, UK. The company develops trapped-ion H-Series quantum processors, the TKET quantum software platform, Quantum Origin cybersecurity, and InQuanto quantum chemistry tools. With over 630 employees including 370+ scientists across the UK, US, Germany, and Japan, Quantinuum is a global leader in full-stack quantum solutions.', '{"company_type": "Quantum Processor", "website_url": "https://www.quantinuum.com", "contact_email": "info@cambridgequantum.com", "contact_phone": "+44 20 33019333", "contact_linkedin": "https://www.linkedin.com/company/quantinuumqc", "location": "Cambridge, UK", "capabilities": ["Trapped-ion H-Series quantum processors", "TKET open-source quantum SDK", "Quantum Origin entropy and cybersecurity", "InQuanto quantum chemistry platform", "Quantum error correction R&D"], "industries": ["Finance", "Pharmaceuticals", "Cybersecurity", "Materials Science", "Logistics"], "employees": "500-1000", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'PQShield', 'PQShield is an Oxford University spin-out founded in 2018 by Dr Ali El Kaafarani, providing post-quantum cryptography solutions for chips, applications, and the cloud. The company is the largest collaboration of post-quantum cryptographers globally and was first to deploy quantum-safe cryptography at the hardware level. PQShield raised $70 million total, was deeply involved in developing NIST PQC standards, and serves semiconductor companies, governments, and financial institutions with a 90-strong team across 10 countries.', '{"company_type": "Quantum Software", "website_url": "https://pqshield.com", "contact_linkedin": "https://uk.linkedin.com/company/pqshield", "location": "Oxford, UK", "capabilities": ["Post-quantum cryptography (PQC) hardware IP", "Quantum-safe software libraries", "Quantum-resistant semiconductor IP", "NIST PQC standard implementation", "Cryptographic algorithm R&D"], "industries": ["Cybersecurity", "Semiconductors", "Finance", "Government", "IoT"], "employees": "51-200", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Phasecraft', 'Phasecraft is a quantum algorithms company founded in 2019 by Professors Toby Cubitt, Ashley Montanaro, and John Morton from UCL and the University of Bristol. Based in London and Bristol, the company develops hardware-agnostic quantum algorithms for materials discovery, chemistry, energy, and logistics optimisation. Phasecraft raised $34 million in its 2025 Series B round and is the only quantum software company with simultaneous partnerships with Google, IBM, and Rigetti hardware providers.', '{"company_type": "Quantum Software", "website_url": "https://www.phasecraft.io", "contact_email": "info@phasecraft.io", "contact_linkedin": "https://uk.linkedin.com/company/phasecraft", "location": "London / Bristol, UK", "capabilities": ["Near-term quantum algorithm development", "Materials and chemistry quantum simulation", "Quantum optimisation algorithms", "Quantum-classical hybrid methods", "Hardware-agnostic quantum software"], "industries": ["Materials Science", "Pharmaceuticals", "Energy", "Logistics", "Research"], "employees": "25-50", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Dice', 'Quantum Dice is an Oxford University spin-out founded in 2020 developing the world''s fastest compact quantum random number generator (QRNG). The company''s patented DISC protocol enables continuous self-certification of quantum randomness, providing verifiably secure entropy for enterprise cybersecurity. Quantum Dice collaborated with HSBC on quantum-enhanced financial Monte Carlo simulations and has launched an Authorised Partner Programme for global distribution of its APEX QRNG PCIe cards.', '{"company_type": "Quantum Random Number Generator", "website_url": "https://www.quantum-dice.com", "contact_email": "info@quantum-dice.com", "contact_linkedin": "https://uk.linkedin.com/company/quantum-dice", "location": "Oxford, UK", "capabilities": ["Self-certifying QRNG (DISC protocol)", "APEX PCIe QRNG hardware", "High-speed quantum randomness", "Cryptographic entropy provisioning", "Enterprise cybersecurity integration"], "industries": ["Cybersecurity", "Finance", "Telecommunications", "Gaming", "Defence"], "employees": "11-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Arqit Quantum Inc.', 'Arqit is a London-headquartered quantum cybersecurity company founded in 2017 providing symmetric key agreement encryption that makes any networked device secure against quantum threats. Listed on Nasdaq (ARQQ), Arqit won the GSMA Global Mobile Award for Best Mobile Security Solution at MWC 2024. The company''s QuantumCloud PaaS delivers quantum-safe encryption via satellite and terrestrial infrastructure, with 82 employees as of fiscal year-end 2024.', '{"company_type": "Quantum Software", "website_url": "https://arqit.uk", "contact_email": "contactus@arqit.uk", "contact_linkedin": "https://uk.linkedin.com/company/arqit", "location": "London, UK", "capabilities": ["Quantum-safe symmetric encryption", "QuantumCloud PaaS", "Zero-trust encryption architecture", "Network endpoint encryption", "Satellite-delivered quantum security"], "industries": ["Cybersecurity", "Defence", "Telecommunications", "Finance", "Government"], "employees": "51-100", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'KETS Quantum Security', 'KETS Quantum Security is a University of Bristol spin-out founded in 2016 by Drs Philip Sibson, Jake Kennard, and Chris Erven, developing chip-scale quantum key distribution and quantum random number generation. Regarded as the UK''s most commercially advanced quantum-safe encryption company, KETS deploys integrated photonic QKD chips that are compact and field-deployable. The company has received multiple Innovate UK contracts and participated in the PAQNet quantum network packaging solutions project.', '{"company_type": "Quantum Networking", "website_url": "https://kets-quantum.com", "contact_email": "enquiry@kets-quantum.com", "contact_linkedin": "https://www.linkedin.com/company/kets-quantum", "location": "Bristol, UK", "capabilities": ["Chip-scale quantum key distribution (QKD)", "Quantum random number generation (QRNG)", "Integrated photonic circuit design", "Quantum network deployment", "Quantum-safe communications systems"], "industries": ["Cybersecurity", "Telecommunications", "Defence", "Finance", "Government"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Universal Quantum', 'Universal Quantum is a Haywards Heath-based full-stack trapped-ion quantum computing company founded in 2018 as a University of Sussex spin-out by Professors Sebastian Weidt and Winfried Hensinger. The company develops fully integrated electronic trapped-ion quantum computing modules manufactured using silicon technology, with a modular scaling approach called UQ Connect for building fault-tolerant quantum computers at scale. Universal Quantum has 59 employees and offices in both the UK and Germany.', '{"company_type": "Ion Trap Systems", "website_url": "https://universalquantum.com", "contact_linkedin": "https://www.linkedin.com/company/universal-quantum/", "location": "Haywards Heath, West Sussex, UK", "capabilities": ["Electronic trapped-ion quantum processors", "Silicon-manufactured ion trap modules", "UQ Connect modular scaling", "Full-stack quantum computing", "Fault-tolerant quantum architecture"], "industries": ["Quantum Computing", "Defence", "Finance", "Pharmaceuticals", "Research"], "employees": "51-100", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aquark Technologies', 'Aquark Technologies is a Hampshire-based quantum hardware company founded in 2021 that builds the world''s smallest and most deployable cold atom quantum sensors using a proprietary supermolasses trap method. The company demonstrated quantum sensing at sea with the Royal Navy in 2024 and won multiple Innovate UK contracts for quantum timing systems and commercial cold atom clocks. Aquark is developing compact quantum sensors for defence navigation, telecommunications timing, and scientific applications.', '{"company_type": "Quantum Sensor", "website_url": "https://www.aquarktechnologies.com", "contact_email": "info@aquarktechnologies.com", "contact_linkedin": "https://uk.linkedin.com/company/aquark-technologies", "location": "Romsey, Hampshire, UK", "capabilities": ["Miniaturised cold atom quantum sensors", "Quantum atomic clock development", "Deployable cold atom trap systems", "Quantum sensing for maritime and defence", "Compact quantum timing hardware"], "industries": ["Defence", "Navigation", "Telecommunications", "Oil & Gas", "Scientific Research"], "employees": "11-50", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Delta.g Ltd', 'Delta.g is a University of Birmingham spin-out founded in 2023 that built the world''s first field-deployable quantum gravity gradiometer for mapping underground space. Led by CEO Tony Lowe with scientific co-founders Professor Mike Holynski, Dr Jonathan Winch, and Dr Andrew Lamb, the company uses cold atom interferometry to detect underground infrastructure, geology, and subsurface voids. Delta.g won the 2025 Institute of Physics Business and Innovation Prize and secured £4.6 million in an oversubscribed seed round.', '{"company_type": "Quantum Sensor", "website_url": "https://www.delta-g.co.uk", "contact_email": "contactinfo@delta-g.co.uk", "contact_linkedin": "https://www.linkedin.com/company/delta-g-ltd", "location": "Birmingham, UK", "capabilities": ["Quantum gravity gradiometry", "Field-deployable underground mapping", "Cold atom interferometry sensors", "Subsurface infrastructure detection", "Quantum inertial sensing"], "industries": ["Civil Engineering", "Mining", "Defence", "Oil & Gas", "Urban Infrastructure"], "employees": "11-30", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cerca Magnetics', 'Cerca Magnetics is a Nottingham-based quantum brain imaging company, a joint venture formed in 2020 between the University of Nottingham and Magnetic Shields Limited. The company develops the world''s most advanced wearable OPM-MEG brain scanner using arrays of optically pumped magnetometers in a lightweight helmet, allowing patients to move freely during scanning. Led by CEO David Woolger, Cerca''s technology is being developed for diagnosing dementia and epilepsy, and for assessing military blast exposure effects.', '{"company_type": "Quantum Sensor", "website_url": "https://www.cercamagnetics.com", "contact_email": "enquiries@cercamagnetics.com", "contact_phone": "01580 891521", "contact_linkedin": "https://www.linkedin.com/company/cerca-magnetics", "location": "Nottingham, UK", "capabilities": ["Wearable OPM-MEG brain scanning", "Optically pumped magnetometer arrays", "Quantum neuroimaging systems", "Magnetic field shielding integration", "Clinical and research brain imaging"], "industries": ["Healthcare", "Neuroscience", "Defence", "Medical Devices", "Research"], "employees": "11-30", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ICEoxford', 'ICEoxford is an Oxford-based manufacturer of ultra-low temperature and high magnetic field cryogenic systems for quantum computing and scientific research, founded in 2004 by Chris Busby and Paul Kelly. The company supplies custom-designed cryogenic systems including cryogen-free dry dilution refrigerators operating below 10mK to quantum computing laboratories and research institutions worldwide. ICEoxford is a specialist UK cryogenics supplier serving superconducting and spin qubit quantum technology developers.', '{"company_type": "Cryogenics", "website_url": "https://www.iceoxford.com", "contact_email": "sales@iceoxford.com", "contact_phone": "+44 1993 706444", "contact_linkedin": "https://www.linkedin.com/company/iceoxford", "location": "Oxford, UK", "capabilities": ["Dry dilution refrigerators (<10mK)", "Cryogen-free cryostats", "Wet liquid helium systems", "Custom ultra-low temperature design", "High magnetic field cryogenic environments"], "industries": ["Quantum Computing", "Physics Research", "Materials Science", "Neutron Scattering", "Condensed Matter"], "employees": "11-50", "established": 2004, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Design Oxford', 'Quantum Design Oxford (formerly Oxford Instruments NanoScience) is based in Abingdon, Oxfordshire, and designs, supplies, and supports advanced cryogenic research tools for quantum technologies. Originally the first commercial Oxford University spin-out, founded in 1959, the NanoScience division was acquired by Quantum Design in January 2026 in a £60 million deal. The company produces the Proteox dilution refrigerator series and cryogen-free measurement platforms essential for quantum computing hardware development.', '{"company_type": "Cryogenics", "website_url": "https://www.qd-oxford.com", "contact_phone": "+44 1865 393200", "contact_linkedin": "https://www.linkedin.com/company/oxford-instruments", "location": "Abingdon, Oxfordshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Proteox dilution refrigerators", "Cryogen-free quantum measurement platforms", "Superconducting magnet systems", "Ultra-low temperature device characterisation", "Helium-3 and dilution insert systems"], "industries": ["Quantum Computing", "Condensed Matter Physics", "Materials Science", "Nanotechnology", "Research"], "employees": "100-500", "established": 1959, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Photon Force', 'Photon Force is an Edinburgh-based company founded in 2015 as a University of Edinburgh spin-out from the CMOS Sensors and Systems Group, led by CEO Dr Richard Walker. The company designs and manufactures time-resolved single-photon sensitive cameras and SPAD array sensors with the highest throughput on the market. Photon Force cameras serve quantum physics experiments, bio-medical fluorescence imaging, quantum communications characterisation, LIDAR, and time-correlated single photon counting applications.', '{"company_type": "Quantum Photonics", "website_url": "https://www.photon-force.com", "contact_email": "enquiries@photon-force.com", "contact_phone": "+44 131 651 7944", "contact_linkedin": "https://www.linkedin.com/company/photon-force", "location": "Edinburgh, Scotland, UK", "capabilities": ["Single-photon counting cameras", "SPAD array photon detectors", "Time-correlated single photon counting (TCSPC)", "Quantum optics measurement instrumentation", "LIDAR and fluorescence lifetime imaging"], "industries": ["Quantum Physics", "Biomedical Imaging", "Quantum Communications", "LIDAR", "Research"], "employees": "11-50", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'QuantrolOx', 'QuantrolOx is an Oxford-based quantum control software company founded in 2021 by Professor Andrew Briggs, Vishal Chatrath, Professor Natalia Ares, and Dominic Lennon. The company develops machine learning-based software automating quantum chip bring-up, characterisation, and tuning, with its Quantum EDGE platform maximising quantum computer uptime. QuantrolOx has 33 employees, raised £1.4 million in initial funding, and partners with quantum hardware providers to reduce manual calibration overhead.', '{"company_type": "Quantum Software", "website_url": "https://quantrolox.com", "contact_email": "sales@quantrolox.com", "contact_linkedin": "https://www.linkedin.com/company/quantrolox", "location": "Oxford, UK", "capabilities": ["AI-driven qubit tuning automation", "Machine learning quantum chip control", "Quantum EDGE software platform", "Qubit characterisation and calibration", "Quantum processor uptime optimisation"], "industries": ["Quantum Computing", "Semiconductor Research", "Defence", "Research"], "employees": "11-50", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SEEQC UK', 'SEEQC UK is the British entity of SEEQC, developing the first fully digital quantum computing platform by combining superconductor classical electronics with quantum processors. Based in London at Cargo Works, Hatfields, SEEQC UK received £1.8 million in Innovate UK grants and achieved the first integration of all key functions toward an on-chip quantum operating system. The company provides superconducting chip foundry services and quantum hardware to commercial and research clients, operating since 2018.', '{"company_type": "Quantum Processor", "website_url": "https://seeqc.com", "contact_email": "info@seeqc.com", "contact_linkedin": "https://www.linkedin.com/company/seeqc-us", "location": "London, UK", "capabilities": ["Superconducting quantum processors", "Digital quantum computing platform", "Single-flux quantum (SFQ) co-processing", "Quantum chip foundry services", "Cryogenic control electronics integration"], "industries": ["Quantum Computing", "Finance", "Defence", "Pharmaceuticals", "Research"], "employees": "11-100", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Duality Quantum Photonics', 'Duality Quantum Photonics is a Bristol-based integrated quantum photonics company founded in 2020 as a University of Bristol spin-out by Professor Anthony Laing and Professor Alberto Politi. The company designs and tests photonic chips for quantum computing in Bristol, with fabrication at the University of Southampton''s clean room. Duality develops scalable photonic integrated circuits enabling quantum computing, communications, and sensing applications using a Bristol-Southampton dual-site model.', '{"company_type": "Quantum Photonics", "website_url": "https://www.dualityqp.com", "contact_email": "helloworlds@dualityqp.com", "contact_linkedin": "https://uk.linkedin.com/company/dualityqp", "location": "Bristol, UK", "capabilities": ["Photonic integrated circuit (PIC) design", "Quantum photonic chip development", "Silicon and silica photonics for quantum", "Integrated quantum optics", "Quantum photonics foundry services"], "industries": ["Quantum Computing", "Quantum Communications", "Research", "Photonics"], "employees": "11-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wave Photonics', 'Wave Photonics is a Cambridge-based quantum photonics design company founded in 2021 that develops on-chip photonics designs for quantum technologies, sensors, and datacentres. The company secured £4.5 million in funding and leads Innovate UK-funded projects for quantum photonic integrated circuit (QPIC) packaging solutions. Wave Photonics provides a PDK platform enabling foundries to design photonic components, and collaborates with Oxford Ionics on photonic chips for trapped-ion quantum computers.', '{"company_type": "Quantum Photonics", "website_url": "https://www.wavephotonics.com", "contact_email": "info@wavephotonics.com", "contact_linkedin": "https://www.linkedin.com/company/wave-photonics", "location": "Cambridge, UK", "capabilities": ["Silicon nitride photonic chip design", "Quantum photonic integrated circuits (QPICs)", "PDK design platform for photonics", "QPIC packaging solutions", "Photonics design automation tools"], "industries": ["Quantum Computing", "Quantum Communications", "Datacentre", "Sensing", "Research"], "employees": "11-50", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Base Ltd', 'Quantum Base is a Lancaster University spin-out founded in 2013 using quantum materials to create unique, unclonable product authentication solutions. The company''s Q-ID technology generates atomic-scale quantum fingerprints from nanoscale semiconductor structures providing tamper-proof authentication for physical items. Quantum Base co-developed one of the first practical quantum random number generators with Lancaster University, serving brand protection, supply chain security, and IoT applications with 26 employees.', '{"company_type": "Quantum Random Number Generator", "website_url": "https://quantumbase.com", "contact_linkedin": "https://www.linkedin.com/company/quantum-base", "location": "Lancaster, UK", "capabilities": ["Quantum dot product authentication (Q-ID)", "Quantum random number generation", "Anti-counterfeit quantum fingerprinting", "IoT device security integration", "Supply chain authentication"], "industries": ["Cybersecurity", "Consumer Goods", "Pharmaceuticals", "IoT", "Defence"], "employees": "11-50", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Crypta Labs', 'Crypta Labs is a London-based quantum security startup founded in 2014 specialising in quantum random number generators (QRNGs) and quantum-secured encryption software. The company holds patents in QRNG technology and developed the world''s first space-compliant QRNG for UKRI and the UK Space Agency. Crypta Labs has partnered with Coventry University on quantum security for connected and autonomous vehicles, providing true quantum-derived entropy for security appliances, IoT devices, and cloud applications.', '{"company_type": "Quantum Random Number Generator", "website_url": "https://cryptalabs.com", "contact_email": "sales@cryptalabs.com", "contact_linkedin": "https://uk.linkedin.com/company/crypta-labs", "location": "London, UK", "capabilities": ["Quantum random number generation (QRNG)", "Space-compliant QRNG systems", "QRNG hardware design for OEMs", "Cryptographic entropy services", "Automotive and IoT quantum security"], "industries": ["Cybersecurity", "Aerospace", "Automotive", "IoT", "Finance"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Infleqtion UK', 'Infleqtion (formerly ColdQuanta UK) maintains an R&D laboratory and production facility in Kidlington, Oxfordshire developing cold atom quantum sensors and navigation technology. The Oxford team develops Photonically Integrated Cold Atom Source (PICAS) technology and quantum positioning systems including gyroscopes for GPS-denied navigation. The company flew un-jammable quantum navigation technology with the UK military and has approximately 40 UK employees at its Oxford Technology Park facility.', '{"company_type": "Quantum Sensor", "website_url": "https://infleqtion.com", "contact_phone": "+44 1865 582144", "contact_linkedin": "https://www.linkedin.com/company/infleqtion-uk", "location": "Kidlington, Oxfordshire, UK", "capabilities": ["Cold atom quantum sensors", "Quantum positioning and navigation systems", "Photonically integrated cold atom sources (PICAS)", "Cold atom quantum computing", "Quantum inertial navigation for defence"], "industries": ["Defence", "Navigation", "Telecommunications", "Research", "Aerospace"], "employees": "11-50", "established": 2007, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'PsiQuantum Ltd (UK)', 'PsiQuantum has a UK-registered entity and an R&D facility at STFC''s Daresbury Laboratory in Cheshire, backed by £9 million in UK government investment. Originally founded in 2016 in California by Professor Jeremy O''Brien and colleagues from the University of Bristol, PsiQuantum UK focuses on developing advanced cryogenic systems for large-scale photonic quantum computing. The company uses silicon photonics to manufacture photonic qubits at scale and partners with the Hartree Centre for fault-tolerant application development.', '{"company_type": "Quantum Photonics", "website_url": "https://www.psiquantum.com", "contact_linkedin": "https://www.linkedin.com/company/psiquantum-ltd", "location": "Daresbury, Cheshire, UK", "capabilities": ["Photonic quantum computing", "Silicon photonics chip fabrication at scale", "Cryogenic quantum systems", "Fault-tolerant photonic quantum computing", "Photonic qubit generation and routing"], "industries": ["Quantum Computing", "Pharmaceuticals", "Finance", "Defence", "Research"], "employees": "500-1000", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Science Ltd', 'Quantum Science Ltd is a Daresbury-based company founded in 2018 at Sci-Tech Daresbury that manufactures advanced quantum dot materials for infrared imaging and sensing applications. The company''s proprietary INFIQ Quantum Dots deliver high-performance, low-cost infrared sensing materials for electronics and healthcare markets. Quantum Science recently expanded into new manufacturing facilities to scale production of quantum dot materials for commercial OEM deployment in photodetectors and imaging systems.', '{"company_type": "Quantum Sensor", "website_url": "https://quantumscis.com", "contact_email": "info@qscis.com", "contact_phone": "+44 1925 807980", "contact_linkedin": "https://uk.linkedin.com/company/quantum-science-ltd", "location": "Daresbury, Warrington, UK", "capabilities": ["Quantum dot material synthesis", "Infrared sensing materials (INFIQ)", "Near-infrared photodetector materials", "Quantum dot manufacturing scale-up", "Infrared imaging component materials"], "industries": ["Healthcare", "Electronics", "Defence", "Automotive", "Industrial Sensing"], "employees": "11-50", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Chronos Technology Ltd', 'Chronos Technology is a Lydbrook, Gloucestershire-based employee-owned company and global authority in resilient synchronisation, timing, and GNSS solutions for critical national infrastructure, founded in 1986. The company provides precision atomic timing systems including cesium frequency standards, PTP/NTP synchronisation equipment, and GNSS time servers for telecom, defence, utilities, and finance sectors. Chronos is a key UK supplier of precision timing infrastructure that underpins quantum technology deployments.', '{"company_type": "Quantum Sensor", "website_url": "https://chronos.uk", "contact_email": "sales@chronos.uk", "contact_phone": "+44 1594 862200", "contact_linkedin": "https://uk.linkedin.com/company/chronos-technology-ltd", "location": "Lydbrook, Gloucestershire, UK", "certifications": ["ISO 9001"], "capabilities": ["Cesium atomic frequency standards", "GNSS-based timing systems", "IEEE 1588 PTP synchronisation", "NTP/PPS time servers", "Resilient timing for critical infrastructure"], "industries": ["Telecommunications", "Defence", "Utilities", "Finance", "Critical Infrastructure"], "employees": "11-63", "established": 1986, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantopticon', 'Quantopticon is a Guildford-based quantum photonics simulation software company founded in 2017 by Dr Gaby Slavcheva (CSO) and Mirella Koleva (CEO). The company develops Quantillion, the world''s first automated simulation platform for design and optimisation of quantum photonic components including single-photon emitters, beam splitters, and QPICs. Resident at Harwell Campus, Quantopticon serves global quantum hardware companies who need to model and validate photonic quantum devices before fabrication.', '{"company_type": "Quantum Software", "website_url": "https://quantopticon.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/quantopticon-ltd.", "location": "Guildford, Surrey, UK", "capabilities": ["Quantum photonic simulation (Quantillion)", "Single-photon emitter design and modelling", "QPIC component optimisation", "Quantum photonics device physics modelling", "Automated photonic component design"], "industries": ["Quantum Computing", "Quantum Communications", "Photonics", "Research"], "employees": "1-10", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Crypto Quantique', 'Crypto Quantique is a London-based quantum-driven cybersecurity company founded in 2016 providing silicon IP and an end-to-end security platform for embedded and IoT devices. The company''s QuarkLink platform delivers device identity, quantum-safe key management, and NIST PQC-compliant post-quantum cryptography for connected devices. Crypto Quantique won the IET Innovation Award for Cybersecurity and serves semiconductor partners including STMicroelectronics, with offices in the UK, US, Europe, and Taiwan.', '{"company_type": "Quantum Software", "website_url": "https://www.cryptoquantique.com", "contact_linkedin": "https://uk.linkedin.com/company/crypto-quantique", "location": "London, UK", "capabilities": ["Quantum-driven IoT device security", "Post-quantum cryptography platform", "QuarkLink device identity management", "Quantum CMOS silicon IP", "NIST PQC-compliant IoT security"], "industries": ["IoT", "Cybersecurity", "Semiconductors", "Automotive", "Industrial"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Instruments plc', 'Oxford Instruments plc is a publicly listed UK company headquartered in Abingdon providing high technology tools for quantum technology, semiconductor manufacturing, and scientific research. The Plasma Technology division produces quantum device fabrication equipment including plasma etch and deposition systems, while NanoAnalysis provides electron microscopy tools for quantum material characterisation. Founded as a University of Oxford spin-out in 1959, Oxford Instruments underpins quantum device fabrication globally with over 2,000 employees.', '{"company_type": "Quantum Processor", "website_url": "https://www.oxinst.com", "contact_phone": "+44 1865 393200", "contact_linkedin": "https://www.linkedin.com/company/oxford-instruments", "location": "Abingdon, Oxfordshire, UK", "certifications": ["ISO 9001", "ISO 14001"], "capabilities": ["Quantum device fabrication equipment", "Plasma etch and deposition systems", "Atomic layer deposition (ALD)", "Electron beam lithography support", "Quantum material characterisation tools"], "industries": ["Quantum Technology", "Semiconductor Manufacturing", "Materials Science", "Research", "Defence"], "employees": "2000+", "established": 1959, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gravitilab Aerospace Services', 'Gravitilab Aerospace Services is a Kettering-based UK company founded in 2018 providing accessible microgravity and space environment testing services using UAV and suborbital platforms. The company supports quantum sensor and cold atom experiment development by enabling quantum device validation in near-zero-gravity conditions, serving quantum technology researchers developing space-based quantum sensors and navigation systems. Gravitilab enables accessible quantum technology testing outside costly orbital missions.', '{"company_type": "Quantum Sensor", "website_url": "https://gravitilab.space", "contact_email": "hello@gravitilab.space", "contact_phone": "+44 1603 738459", "contact_linkedin": "https://uk.linkedin.com/company/gravitilab-aerospace-services", "location": "Kettering, Northamptonshire, UK", "capabilities": ["Microgravity testing for quantum sensors", "UAV parabolic flight platforms", "Space environment simulation", "Cold atom experiment support in microgravity", "Quantum device zero-g validation"], "industries": ["Aerospace", "Space Technology", "Quantum Technology", "Defence", "Research"], "employees": "1-10", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Torr Scientific Ltd', 'Torr Scientific Ltd is a Bexhill-on-Sea, East Sussex company specialising in ultra-high vacuum (UHV) components and optical coatings that form critical enabling infrastructure for quantum devices. The company manufactures vacuum viewports, anti-reflective coatings, metal-ceramic vacuum feedthroughs, and X-ray anodes used in ion trap systems, cold atom experiments, and quantum sensor fabrication. Torr Scientific participates in UK quantum technology programmes including the QTEAM (Quantum Technologies Enabled by Additive Manufacturing) project.', '{"company_type": "Cryogenics", "website_url": "https://torrscientific.co.uk", "contact_email": "sales@torrscientific.co.uk", "contact_phone": "+44 1424 225228", "contact_linkedin": "https://www.linkedin.com/company/torr-scientific-ltd", "location": "Bexhill-on-Sea, East Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["Ultra-high vacuum (UHV) viewports and components", "Anti-reflective optical coatings", "Metal-ceramic vacuum feedthroughs", "UHV components for ion traps and cold atoms", "X-ray and electron source anodes"], "industries": ["Quantum Technology", "Scientific Instrumentation", "Defence", "Research", "Semiconductor"], "employees": "11-50", "established": 1997, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Exponential Group plc', 'Quantum Exponential Group plc (QEG) is the UK''s first specialist quantum technology investment company, listed on the Aquis Stock Exchange in London. QEG builds a diversified portfolio of investments in companies commercialising quantum computing, sensing, communications, and cybersecurity. In November 2025, QEG launched fundraising for a £100 million venture capital fund dedicated to UK quantum technologies, with two-thirds of investments targeting UK-based companies including portfolio companies such as Delta.g.', '{"company_type": "Quantum Software", "website_url": "https://www.quantumexp.co.uk", "contact_email": "info@quantumexp.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/quantum-exponential", "location": "London, UK", "capabilities": ["Quantum technology investment", "Quantum portfolio management", "Quantum sector advisory services", "Early-stage quantum company support", "Quantum market development"], "industries": ["Investment", "Quantum Computing", "Quantum Sensing", "Quantum Communications", "Cybersecurity"], "employees": "1-10", "established": 2021, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Covesion Ltd', 'Covesion Ltd is a Southampton-based world-leading manufacturer of periodically poled lithium niobate (MgO:PPLN) crystals and waveguides for nonlinear photonics and quantum applications, established as a spin-out from the University of Southampton''s Optoelectronics Research Centre in 2009. The company produces PPLN crystals and waveguides used for quantum entangled photon pair generation, frequency conversion for quantum communications, and quantum key distribution systems. Covesion won the 2024 Institute of Physics Business Innovation Award and is part of the Hawthorn Photonics Group.', '{"company_type": "Quantum Photonics", "website_url": "https://covesion.com", "contact_email": "sales@covesion.com", "contact_phone": "+44 1794 521638", "contact_linkedin": "https://www.linkedin.com/company/covesion", "location": "Southampton, UK", "capabilities": ["Periodically poled lithium niobate (PPLN) crystals", "Quantum entangled photon pair generation", "Nonlinear frequency conversion", "Quantum communications photonics", "Waveguide fabrication for quantum systems"], "industries": ["Quantum Communications", "Quantum Computing", "Defence", "Scientific Instrumentation", "Research"], "employees": "11-50", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Quantum Detectors Ltd', 'Quantum Detectors Ltd is a Harwell Campus-based company founded in 2007 as a spin-out from STFC and Diamond Light Source, developing and manufacturing advanced detector technology and electronics for world-leading laboratories. The company produces hybrid pixel detectors, single-photon counting detectors, and detector electronics used in quantum physics experiments and synchrotron facilities including CERN, Diamond Light Source, and STFC Daresbury. With 37 employees, Quantum Detectors serves quantum photonics characterisation and quantum sensing measurement applications.', '{"company_type": "Quantum Photonics", "website_url": "https://quantumdetectors.com", "contact_phone": "01235 445795", "contact_linkedin": "https://uk.linkedin.com/company/quantum-detectors-ltd-", "location": "Harwell, Oxfordshire, UK", "capabilities": ["Hybrid pixel photon detectors", "Single-photon counting detectors", "Detector electronics and readout", "X-ray and electron detector systems", "Quantum photonics measurement instruments"], "industries": ["Quantum Physics", "Synchrotron Science", "Defence", "Medical Imaging", "Research"], "employees": "11-50", "established": 2007, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Magnetic Shields Limited', 'Magnetic Shields Limited is a world-leading manufacturer of magnetic shielding technology based in Staplehurst, Kent, with over 65 years of experience fabricating precision shields from mu-metal (nickel-iron alloy). The company designs and manufactures bespoke quantum magnetic shielding solutions, including magnetically shielded rooms (MSRs) for optically pumped magnetometers used in quantum brain scanning (MEG) and quantum sensing applications. Its lightweight MuRoom MSR design was used in leading quantum biology and quantum sensing research, and the company supplies quantum technology labs globally. Magnetic Shields Limited integrates full in-house hydrogen heat treatment to guarantee the final magnetic properties of all shields.', '{"company_type": "Quantum Sensing", "website_url": "https://www.magneticshields.co.uk", "contact_phone": "+44 1580 891521", "contact_linkedin": "https://uk.linkedin.com/company/magnetic-shields-limited", "location": "Staplehurst, Kent, UK", "capabilities": ["Mu-metal (MuMetal) magnetic shielding fabrication", "Magnetically shielded rooms (MSR) for quantum sensors", "Bespoke quantum shielding design", "Hydrogen heat treatment for magnetic alloys", "Shielding for optically pumped magnetometers (OPM/MEG)"], "industries": ["Quantum Sensing", "Medical Imaging", "Defence", "Research", "Quantum Computing"], "employees": "11-50", "established": 1957, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kelvin Nanotechnology Ltd', 'Kelvin Nanotechnology Ltd (KNT) is an internationally recognised UK nanofabrication foundry founded in 1997 as the commercialisation vehicle for the University of Glasgow''s James Watt Nanofabrication Centre (JWNC), which is one of the world''s leading nanofabrication facilities. The company provides advanced photonics and quantum components, including gMOT grating chips for cold-atom quantum sensors and atomic clocks, as well as superconducting quantum circuit fabrication for quantum computing and sensing. KNT is partnering with the University of Glasgow Quantum Circuit Group to develop an industrial-grade superconducting process toolkit for commercial quantum hardware foundry services. With over 25 years of experience, KNT serves quantum technology customers globally through electron beam lithography, device prototyping, and multi-material system processing.', '{"company_type": "Quantum Sensor", "website_url": "https://kntnano.com", "contact_email": "enquiries@KNTnano.com", "contact_phone": "+44 141 330 4869", "contact_linkedin": "https://uk.linkedin.com/company/kelvin-nanotechnology", "location": "Glasgow, Scotland, UK", "capabilities": ["Electron beam lithography (EBL) for quantum components", "gMOT grating fabrication for cold-atom quantum sensors", "Superconducting quantum circuit fabrication", "Photonic integrated circuit prototyping", "Multi-material device nanofabrication foundry services"], "industries": ["Quantum Computing", "Quantum Sensing", "Quantum Photonics", "Defence", "Research"], "employees": "11-50", "established": 1997, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Qontrol Ltd', 'Qontrol Ltd is a Bristol-based company designing and manufacturing scalable control electronics for photonic integrated circuits (PICs) and quantum photonic processors, founded in 2016 by Joshua Silverstone following experiments at the University of Bristol''s quantum photonics lab. The company develops multi-channel electronic control modules, wiring solutions, and motion control systems used to operate complex photonic integrated circuits including quantum photonic chips. Qontrol''s products are deployed in quantum computing research groups worldwide, including being the first commercial customer for a quantum photonic processor from QuiX Quantum. Operating sustainably from its Bristol headquarters, the company serves the growing photonic quantum computing and quantum communications hardware supply chain.', '{"company_type": "Quantum Photonics", "website_url": "https://qontrol.co.uk", "contact_email": "hello@qontrol.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/qontrol-systems", "location": "Bristol, UK", "capabilities": ["Multi-channel photonic control electronics", "Scalable control modules for quantum PICs", "Wiring solutions for quantum photonic chips", "Motion control for photonics", "Electronic infrastructure for quantum photonic processors"], "industries": ["Quantum Photonics", "Quantum Computing", "Quantum Communications", "Research", "Defence"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sitehop Ltd', 'Sitehop Ltd is a Sheffield-based cybersecurity company developing FPGA-powered quantum-safe encryption hardware for protecting data in motion across critical networks, founded in 2019. The company''s flagship SAFE Series product delivers post-quantum cryptography (PQC) compliant encryption with sub-microsecond latency, making it suited for latency-sensitive environments including telecom, financial services, and critical national infrastructure. Sitehop was the first UK SME granted access to BT''s flagship quantum encryption test facility for a breakthrough quantum-safe encryption trial in 2024. The company raised £7.5 million in a funding round in October 2025 to accelerate UK quantum-safe encryption hardware deployment.', '{"company_type": "Quantum Software", "website_url": "https://sitehop.com", "contact_email": "info@sitehop.com", "contact_phone": "0114 478 2366", "contact_linkedin": "https://uk.linkedin.com/company/sitehop", "location": "Sheffield, UK", "capabilities": ["FPGA-powered post-quantum cryptography (PQC) encryption", "Quantum-safe data-in-motion protection", "Sub-microsecond latency encryption hardware", "NIST PQC standard compliance", "Quantum-ready network security for critical infrastructure"], "industries": ["Cybersecurity", "Telecommunications", "Finance", "Critical National Infrastructure", "Defence"], "employees": "11-50", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Post-Quantum', 'Post-Quantum is a London-based quantum-safe cybersecurity pioneer founded in 2009, with a 15-year track record of deep R&D delivering encryption algorithms resistant to quantum computing attacks. The company is one of the longest-established post-quantum cryptography firms globally and developed Classic McEliece, the only remaining finalist in the code-based category of NIST''s Post-Quantum Cryptography standardisation programme. Post-Quantum provides production-ready quantum-safe security solutions including hybrid VPN (using the RFC9370 standard), quantum-safe messaging, and quantum-safe identity tools currently protecting NATO communications and critical infrastructure in active conflict zones. The company addresses the ''harvest now, decrypt later'' threat by enabling organisations to become quantum-safe before large-scale quantum computers arrive.', '{"company_type": "Quantum Software", "website_url": "https://www.post-quantum.com", "contact_email": "info@post-quantum.com", "contact_phone": "+44 20 8106 6913", "contact_linkedin": "https://uk.linkedin.com/company/post-quantum", "location": "London, UK", "capabilities": ["Post-quantum cryptography (PQC) algorithm development", "NIST Classic McEliece finalist encryption", "Hybrid quantum-safe VPN (RFC9370)", "Quantum-safe identity and authentication", "Quantum-safe messaging and communications security"], "industries": ["Cybersecurity", "Defence", "Government", "Critical National Infrastructure", "Finance"], "employees": "11-50", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


