INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CMR Surgical', 'CMR Surgical is a global medical devices company headquartered in Cambridge, dedicated to transforming surgery with Versius, a next-generation modular surgical robot for minimal access surgery. Founded in 2014, it has grown into a multi-national operation with Versius deployed in over 20 countries and used in more than 18,000 procedures. The company manufactures its products at a facility in Ely, Cambridgeshire, and has raised over $1.35 billion including a Series F round.', '{"company_type": "Surgical Robotics", "website_url": "https://cmrsurgical.com", "contact_email": "hello@cmrsurgical.com", "contact_phone": "+44 (0)1223 755 300", "contact_linkedin": "https://uk.linkedin.com/company/cmrsurgical", "location": "Cambridge, Cambridgeshire, UK", "certifications": ["CE Mark", "ISO 13485", "FDA 510(k)"], "capabilities": ["Surgical robotic system design and manufacture", "Minimal access surgery enablement", "Surgeon training and support", "Digital surgery data platforms", "Global surgical robotics deployment"], "industries": ["Healthcare", "Medical Devices", "Surgery"], "employees": "501-1000", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Shadow Robot Company', 'The Shadow Robot Company is a London-based pioneer in dexterous robotic hand technology, producing the Shadow Dexterous Hand, widely regarded as the world''s most advanced commercially available robotic hand. Founded in 1997, the company has collaborated with Google DeepMind and other leading AI research organisations to develop cutting-edge teleoperation and autonomous manipulation systems. Their DEX-EE product is designed specifically for humanoid robot applications and has been jointly developed with Google DeepMind.', '{"company_type": "Collaborative Robotics", "website_url": "https://shadowrobot.com", "contact_email": "contact@shadowrobot.com", "contact_phone": "+44 207 700 2487", "contact_linkedin": "https://uk.linkedin.com/company/shadow-robot", "location": "London (Camden), UK", "capabilities": ["Dexterous robotic hand design and manufacture", "Teleoperation systems", "Autonomous manipulation", "Research and development robotics platforms", "Humanoid hand integration"], "industries": ["Research & Development", "Defence", "Industrial Automation", "Healthcare"], "employees": "51-200", "established": 1997, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Automata Technologies', 'Automata is a London-based lab automation company that develops the LINQ platform, an end-to-end robotic automation solution for life sciences and biotech laboratories. Founded in 2015, the company builds collaborative robotic arms and software enabling scientists to automate repetitive lab workflows including pipetting, sample handling, and liquid dispensing. In 2025, Automata closed a $45 million Series C round led by Dimension, with participation from Danaher Ventures and Octopus Ventures.', '{"company_type": "Laboratory Robotics", "website_url": "https://automata.tech", "contact_email": "hello@automata.tech", "contact_linkedin": "https://uk.linkedin.com/company/automata-technologies", "location": "London (Islington), UK", "capabilities": ["Laboratory automation platform", "Collaborative robot arm design", "Lab workflow software", "Liquid handling automation", "Sample processing automation"], "industries": ["Life Sciences", "Biotech", "Pharmaceuticals", "Healthcare"], "employees": "51-200", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Tharsus', 'Tharsus is the UK''s leading designer and manufacturer of autonomous robotic systems and strategic machines, based in Blyth, Northumberland. Founded in 1964, the company pivoted from general engineering to specialise in designing and scaling electro-mechanical autonomous systems, counting Ocado and other major logistics operators among its clients. Tharsus operates from sites in Blyth, Durham, and Cambridge and employs around 400 people across its operations.', '{"company_type": "Industrial Robotics", "website_url": "https://tharsus.com", "contact_email": "hello@tharsus.co.uk", "contact_phone": "+44 (0) 1670 368000", "contact_linkedin": "https://www.linkedin.com/company/tharsus-group", "location": "Blyth, Northumberland, UK", "certifications": ["ISO 9001"], "capabilities": ["Autonomous robotic system design", "Strategic machine manufacture", "Electro-mechanical systems engineering", "Product scale-up and volume manufacture", "AMR and autonomous vehicle development"], "industries": ["Logistics", "Retail", "Manufacturing", "Agriculture", "Healthcare"], "employees": "201-500", "established": 1964, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Engineered Arts', 'Engineered Arts is a Falmouth, Cornwall-based company and global leader in social humanoid robotics, producing the Ameca, Mesmer, and RoboThespian platforms. Founded in 2004 by Will Jackson, the company designs and manufactures robots for entertainment, education, and research, with robots deployed in science centres, museums, and theme parks worldwide. Their Ameca platform has become a leading testbed for embodied AI research and is widely recognised for its lifelike facial expressions.', '{"company_type": "Humanoid Robotics", "website_url": "https://engineeredarts.co.uk", "contact_email": "info@engineeredarts.co.uk", "contact_phone": "+44 (0)1326 378 129", "contact_linkedin": "https://uk.linkedin.com/company/engineered-arts-ltd", "location": "Falmouth, Cornwall, UK", "capabilities": ["Humanoid robot design and manufacture", "Embodied AI platform development", "Animatronics and robotic character creation", "Robot management software", "Teleoperation and remote presence"], "industries": ["Entertainment", "Education", "Research & Development", "Museums & Attractions"], "employees": "51-200", "established": 2004, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dogtooth Technologies', 'Dogtooth Technologies is a Cambridgeshire-based agri-robotics company that develops AI-powered robots for harvesting soft fruits such as strawberries and raspberries. Founded in 2014, Dogtooth uses computer vision and machine learning to identify, pick, and grade ripe fruit in polytunnels and open fields. The company has raised over $20 million in funding and serves a growing base of UK and international berry growers facing acute labour shortages.', '{"company_type": "Agricultural Robotics", "website_url": "https://dogtooth.tech", "contact_email": "info@dogtoothtech.com", "contact_phone": "+44 (0) 1763 268463", "contact_linkedin": "https://www.linkedin.com/company/dogtooth-technologies-limited", "location": "Melbourn, Cambridgeshire, UK", "capabilities": ["Autonomous soft fruit harvesting robots", "Computer vision for fruit detection", "Yield forecasting and crop analytics", "Crop health monitoring", "Robotic fleet management software"], "industries": ["Agriculture", "Food Production", "Horticulture"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Saga Robotics', 'Saga Robotics develops the Thorvald platform, a multi-purpose autonomous agricultural robot designed for polytunnel and field crop operations, with UK operational hubs in Lincoln and Kent. The Thorvald robots perform UV-C light treatment against powdery mildew, autonomous harvesting of strawberries and salads, and crop scouting. By 2025, Thorvald robots covered approximately 20% of the UK tabletop strawberry market and achieved 97% uptime across a fleet of 150+ robots.', '{"company_type": "Agricultural Robotics", "website_url": "https://sagarobotics.com", "contact_email": "info@sagarobotics.com", "contact_linkedin": "https://uk.linkedin.com/company/saga-robotics", "location": "Lincoln, Lincolnshire, UK", "capabilities": ["Autonomous agricultural robots", "UV-C disease treatment robots", "Soft fruit harvesting", "Crop scouting and mapping", "Modular robot platform development"], "industries": ["Agriculture", "Horticulture", "Food Production"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Consequential Robotics', 'Consequential Robotics is a London-based robotics company that develops companion and assistive robots for healthcare and social care environments. Registered in 2014, the company is best known for the MiRo biologically-inspired robot, designed as a research platform and social companion for use in therapy, education, and eldercare. MiRo robots have been deployed in NHS trusts, care homes, and research universities across the UK and internationally.', '{"company_type": "Healthcare & Social Robotics", "website_url": "http://consequentialrobotics.com", "contact_email": "info@consequentialrobotics.com", "contact_linkedin": "https://www.linkedin.com/company/consequential-robotics", "location": "London, UK", "capabilities": ["Companion robot design and development", "Biologically-inspired robotics", "Social care robotics", "Research robotics platforms", "Human-robot interaction systems"], "industries": ["Healthcare", "Social Care", "Education", "Research & Development"], "employees": "1-10", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Open Bionics', 'Open Bionics is a Bristol-based medical devices company that designs and manufactures the Hero Arm, an advanced 3D-printed myoelectric prosthetic limb for upper-limb amputees. Founded in 2014 by Joel Gibbard and Samantha Payne MBE, the company has partnered with Disney, Marvel, and Konami to create character-themed bionic arms, making prosthetics aspirational for young wearers. The Hero Arm is UKCA-certified and CE-marked as a Class I medical device.', '{"company_type": "Medical Robotics", "website_url": "https://openbionics.com", "contact_email": "hello@openbionics.com", "contact_linkedin": "https://www.linkedin.com/company/openbionics", "location": "Bristol, UK", "certifications": ["CE Mark", "UKCA"], "capabilities": ["Myoelectric prosthetic limb design and manufacture", "3D printing of bespoke prosthetics", "Electromyography (EMG) control systems", "Clinical fitting and aftercare services", "Bionic arm customisation"], "industries": ["Medical Devices", "Healthcare", "Prosthetics & Orthotics"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rivelin Robotics', 'Rivelin Robotics is a Sheffield-based company that develops robotic post-processing systems for metal additive manufacturing (3D printing). Founded in 2017, Rivelin produces the NetShape platform, which automates support removal, grinding, polishing, and inspection of metal AM parts using industrial robots combined with proprietary sensing and software. Their systems address the finishing bottleneck in aerospace, defence, and high-value manufacturing.', '{"company_type": "Industrial Robotics", "website_url": "https://rivelinrobotics.com", "contact_email": "info@rivelinrobotics.com", "contact_phone": "0114 700 3984", "contact_linkedin": "https://uk.linkedin.com/company/rivelin-robotics", "location": "Sheffield, South Yorkshire, UK", "capabilities": ["Robotic metal AM post-processing", "Automated support removal", "Robotic grinding and polishing", "In-process inspection and measurement", "Post-processing software and path planning"], "industries": ["Aerospace", "Defence", "Industrial Manufacturing", "Additive Manufacturing"], "employees": "11-50", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Saab Seaeye', 'Saab Seaeye is the world''s leading manufacturer of electric underwater remotely operated vehicles (ROVs) and autonomous underwater systems, headquartered in Fareham, Hampshire. A division of the Saab Group since 2007, the company produces the Falcon, Leopard, Tiger, Jaguar, and Panther ROV families used extensively in offshore energy, defence, and scientific research. Their electric ROV technology is renowned for reliability, precision, and environmental performance.', '{"company_type": "Marine & Subsea Robotics", "website_url": "https://saabseaeye.com", "contact_email": "solutions@saabseaeye.com", "contact_phone": "+44 (0)300 303 3820", "contact_linkedin": "https://uk.linkedin.com/company/saab-seaeye-ltd.", "location": "Fareham, Hampshire, UK", "certifications": ["ISO 9001", "DNV Type Approval"], "capabilities": ["Electric ROV design and manufacture", "Autonomous underwater vehicle (AUV) systems", "Subsea inspection and intervention", "ROV operator training and support", "Custom underwater robotics solutions"], "industries": ["Offshore Energy", "Defence", "Marine Science", "Subsea Infrastructure"], "employees": "201-500", "established": 1985, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Q-Bot', 'Q-Bot is a London-based robotics company that uses autonomous robots and AI to carry out underfloor insulation installation and building energy retrofit work in spaces inaccessible to humans. Founded in 2012 by Tom Lipinski and Professor Peter Childs of Imperial College London, Q-Bot''s robots crawl into sub-floor cavities to survey, clean, and spray insulating foam, delivering significant energy savings to the UK housing stock. The company has installed underfloor insulation in thousands of UK homes.', '{"company_type": "Construction & Inspection Robotics", "website_url": "https://q-bot.co", "contact_email": "info@q-bot.co", "contact_phone": "+44 (0) 20 4579 7361", "contact_linkedin": "https://www.linkedin.com/company/q-bot-ltd", "location": "Wandsworth, London, UK", "capabilities": ["Autonomous underfloor insulation installation", "Building survey robots", "AI-driven crawlspace mapping", "Energy retrofit automation", "Thermal performance assessment"], "industries": ["Construction", "Energy Retrofit", "Housing", "Facilities Management"], "employees": "11-50", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
