INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Acuity Robotics', 'Acuity Robotics is a Leeds-based University of Leeds spinout that develops miniaturised inspection robots for safety-critical metallic infrastructure. The company''s Stoat and Squirrel platforms are designed to inspect pipework, vessels, and structures in confined spaces using non-destructive testing (NDT) sensors, capturing data and generating automated inspection reports. Acuity serves the oil and gas, nuclear, chemical, and civil infrastructure sectors.', '{"company_type": "Inspection Robotics", "website_url": "https://acuityrobotics.co.uk", "contact_email": "info@acuityrobotics.co.uk", "contact_phone": "+44 (0) 113 418 0219", "contact_linkedin": "https://uk.linkedin.com/company/acuity-robotics", "location": "Leeds, West Yorkshire, UK", "capabilities": ["Miniature infrastructure inspection robots", "Non-destructive testing (NDT) robotics", "Confined space inspection", "Pipeline and vessel inspection", "Inspection data reporting software"], "industries": ["Oil & Gas", "Nuclear", "Chemical", "Civil Infrastructure", "Water"], "employees": "1-10", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
