INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Createc', 'Createc is a Cockermouth, Cumbria-based technology company specialising in robotics, imaging, and AI for nuclear decommissioning and extreme environment inspection. Founded in 2010, Createc is a global leader in radiation mapping and robotic characterisation, deploying Boston Dynamics Spot robots adapted for nuclear environments. In 2024, the company signed a strategic agreement with Curtiss-Wright to expand its nuclear robotics capabilities globally.', '{"company_type": "Nuclear & Industrial Robotics", "website_url": "https://createc.co.uk", "contact_email": "info@createc.co.uk", "contact_phone": "+44 (0) 1900 828112", "contact_linkedin": "https://www.linkedin.com/company/createc", "location": "Cockermouth, Cumbria, UK", "capabilities": ["Nuclear radiation mapping robots", "Robotic characterisation and surveying", "N-Visage imaging and mapping software", "Remote inspection systems", "Spot robot adaptation for nuclear environments"], "industries": ["Nuclear", "Defence", "Industrial Inspection", "Energy"], "employees": "11-50", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Forth Engineering (Cumbria) Ltd', 'Forth Engineering is a Cumbria-based remote engineering and robotics company providing specialist inspection, manipulation, and decommissioning solutions for nuclear and extreme environments. Founded in 2000, Forth develops bespoke robotic and tooling systems for operations too hazardous or inaccessible for human workers, with particular expertise in nuclear power plant decommissioning at Sellafield. The company operates from Maryport and Barrow-in-Furness and serves clients across the nuclear, offshore, and defence sectors.', '{"company_type": "Nuclear & Industrial Robotics", "website_url": "https://forth.uk.com", "contact_email": "info@forth.uk.com", "contact_phone": "01900 816000", "contact_linkedin": "https://www.linkedin.com/company/forth-engineering-cumbria-limited", "location": "Maryport, Cumbria, UK", "certifications": ["ISO 9001"], "capabilities": ["Nuclear decommissioning robotics", "Remote handling systems", "Bespoke manipulator design", "Underwater inspection ROVs", "Radiation-tolerant robotic systems"], "industries": ["Nuclear", "Offshore", "Defence", "Industrial"], "employees": "51-200", "established": 2000, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Frazer-Nash Consultancy', 'Frazer-Nash Consultancy is a leading UK systems, engineering, and technology consultancy with over 1,400 employees across 11 UK offices, and part of the KBR Group. The company provides robotics, autonomous systems, and AI engineering consultancy to defence, nuclear, energy, and transport clients, covering the full lifecycle from requirements through safety assurance to deployment. Frazer-Nash is actively involved in Innovate UK programmes and DSTL-funded autonomous systems projects.', '{"company_type": "Robotics Engineering Consultancy", "website_url": "https://fnc.co.uk", "contact_email": "enquiries@fnc.co.uk", "contact_phone": "+44 (0)333 032 9500", "contact_linkedin": "https://uk.linkedin.com/company/frazer-nash-consultancy", "location": "Leatherhead, Surrey, UK", "certifications": ["ISO 9001", "ISO 27001", "Cyber Essentials Plus"], "capabilities": ["Autonomous systems engineering", "Robotics hardware and embedded software", "Safety assurance for autonomous systems", "Systems integration and test", "AI and machine learning for robotics"], "industries": ["Defence", "Nuclear", "Energy", "Transport", "Space"], "employees": "1001-5000", "established": 1983, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Labman Automation', 'Labman Automation is a North Yorkshire-based company with over 40 years of experience designing and building bespoke laboratory automation systems and robots for pharmaceutical, biotech, and chemical research organisations. Founded in 1979 in Stokesley, Labman designs, manufactures, and supports custom automation equipment including robotic workstations, sample processing systems, and high-throughput screening platforms. They serve major global pharmaceutical companies and research institutions.', '{"company_type": "Laboratory Robotics", "website_url": "https://labmanautomation.com", "contact_email": "enquiries@labman.co.uk", "contact_phone": "+44 1642 710580", "contact_linkedin": "https://uk.linkedin.com/company/labman", "location": "Stokesley, North Yorkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Custom laboratory automation design", "Robotic liquid handling systems", "High-throughput screening automation", "Process skid and instrument integration", "LIMS and lab software integration"], "industries": ["Pharmaceuticals", "Biotech", "Chemical Research", "Diagnostics", "Food & Beverage"], "employees": "51-200", "established": 1979, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Wootzano', 'Wootzano is a Sedgefield, County Durham-based robotics company that has developed a unique electronic skin technology enabling robots to handle delicate items like tomatoes, grapes, and other soft produce without damage. Founded in 2018 by Dr Atif Syed, Wootzano''s Wanda robots are deployed in fresh produce packaging operations in the UK and US. The electronic skin uses AI to mimic human tactile sensing, enabling highly dexterous robotic manipulation of irregular, fragile objects.', '{"company_type": "Agricultural Robotics", "website_url": "https://wootzano.com", "contact_email": "hello@wootzano.com", "contact_phone": "+44 (0) 333 5779 668", "contact_linkedin": "https://uk.linkedin.com/company/wootzano-ltd", "location": "Sedgefield, County Durham, UK", "capabilities": ["Electronic skin tactile sensing technology", "Soft produce handling robots", "Fruit and vegetable packaging automation", "Dexterous robotic manipulation", "AI-driven object recognition and gripping"], "industries": ["Agriculture", "Food Production", "Packaging", "Horticulture"], "employees": "11-50", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Robotical', 'Robotical is an Edinburgh-based company, spun out from the University of Edinburgh, that designs and manufactures Marty, a programmable walking robot for STEM education in schools and universities. Robotical provides Marty robots along with a curriculum-aligned software platform supporting Python, Scratch, and block coding. Marty is deployed in primary, secondary, and higher education institutions across the UK and internationally, with growth funded by Scottish EDGE and Techscaler.', '{"company_type": "Educational Robotics", "website_url": "https://robotical.io", "contact_email": "hello@robotical.io", "contact_phone": "+44 131 564 0922", "contact_linkedin": "https://uk.linkedin.com/company/robotical", "location": "Edinburgh, Scotland, UK", "certifications": ["CE Mark"], "capabilities": ["Educational walking robot design and manufacture", "STEM curriculum programming platforms", "Python, Scratch, and block coding support", "Sensor integration for education", "Teacher training and curriculum support"], "industries": ["Education", "EdTech", "STEM"], "employees": "1-10", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'BladeBUG', 'BladeBUG is a West London robotics startup developing a crawler robot for non-destructive testing (NDT) and maintenance of wind turbine blades, both onshore and offshore. Founded in 2017, BladeBUG completed the world''s first robotic blade walk on an offshore wind turbine in 2020 and has received funding from Innovate UK and the Offshore Renewable Energy Catapult. Their robot uses ultrasonic sensors to detect structural defects without requiring rope access technicians.', '{"company_type": "Inspection Robotics", "website_url": "https://bladebug.co.uk", "contact_email": "info@bladebug.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/bladebug", "location": "London (Brent), UK", "capabilities": ["Turbine blade crawler robot", "Ultrasonic NDT inspection", "Offshore wind turbine maintenance robotics", "Lightning protection system (LPS) inspection", "Remote inspection without rope access"], "industries": ["Offshore Wind", "Onshore Wind", "Renewable Energy"], "employees": "1-10", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ross Robotics (Robosynthesis)', 'Ross Robotics, trading as Robosynthesis, is a Marlow, Berkshire-based company that develops a modular, reconfigurable robotic platform deployable across nuclear, oil and gas, security, agriculture, and defence applications. The company''s building-block approach allows its robots to be quickly re-configured in the field for different tasks including inspection, surveillance, and manipulation. Ross Robotics platforms have been deployed in Chernobyl''s exclusion zone, poultry inspection, and critical infrastructure security.', '{"company_type": "Industrial Robotics", "website_url": "https://robosynthesis.com", "contact_email": "info@robosynthesis.com", "contact_linkedin": "https://uk.linkedin.com/company/ross-robotics", "location": "Marlow, Berkshire, UK", "capabilities": ["Modular reconfigurable robotic platforms", "Nuclear environment inspection robots", "Oil and gas pipeline inspection", "Agriculture and confined space robots", "Field-reconfigurable robot assembly"], "industries": ["Nuclear", "Oil & Gas", "Agriculture", "Security", "Defence"], "employees": "11-50", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Arondite', 'Arondite is a London-based defence technology company building Cobalt, a software platform for Frontier Autonomy that enables operators to connect, control, and manage autonomous systems, sensors, and effectors at scale. Founded in 2023 by former British Army officer Will Blyth and Rob Underhill, the company raised over €10.5 million in Seed funding led by Index Ventures in 2025. Arondite has announced plans to invest £100 million in the UK and tripled its headcount during 2025.', '{"company_type": "Defence Robotics & Autonomous Systems", "website_url": "https://arondite.com", "contact_email": "hello@arondite.com", "contact_linkedin": "https://uk.linkedin.com/company/arondite", "location": "London, UK", "capabilities": ["Autonomous systems management platform", "Multi-sensor and effector integration", "AI-driven mission autonomy", "Human-machine teaming software", "Defence and critical infrastructure robotics"], "industries": ["Defence", "Security", "Critical Infrastructure", "Humanitarian"], "employees": "11-50", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Cyberselves (BOW)', 'Cyberselves, now rebranded as BOW, is a Sheffield-based University of Sheffield spinout that develops the Animus SDK and Teleport platform enabling software developers to write and port applications across different robot hardware makes and to teleoperate robots immersively. Founded in 2020, the company has worked with DASA (Defence and Security Accelerator) and Dstl on telepresence robots for bomb disposal and nuclear decommissioning, and reached the finals of the global Avatar XPRIZE competition.', '{"company_type": "Collaborative Robotics", "website_url": "https://cyberselves.com", "contact_email": "info@cyberselves.com", "contact_linkedin": "https://www.linkedin.com/company/cyberselves", "location": "Sheffield, South Yorkshire, UK", "capabilities": ["Universal robot SDK (Animus)", "Teleoperation and telepresence software", "Robot application portability across hardware", "Bomb disposal telepresence systems", "Nuclear decommissioning teleoperation"], "industries": ["Defence", "Nuclear", "Research & Development", "Security"], "employees": "1-10", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ocado Intelligent Automation', 'Ocado Intelligent Automation (OIA) is the technology commercialisation division of Ocado Group plc, headquartered in Hatfield, Hertfordshire. OIA delivers Ocado''s proprietary warehouse robotics, AI, and automation systems to third-party retailers and logistics operators worldwide, including its Ocado Storage and Retrieval System (OSRS). The company has pioneered grocery warehouse robotics since 2002 and in 2025 trialled humanoid robots within its automated facilities.', '{"company_type": "Industrial Robotics", "website_url": "https://ocadointelligentautomation.com", "contact_email": "enquiries@ocadogroup.com", "contact_phone": "+44 345 656 1345", "contact_linkedin": "https://www.linkedin.com/company/ocadointelligentautomation", "location": "Hatfield, Hertfordshire, UK", "certifications": ["ISO 9001", "ISO 27001"], "capabilities": ["Warehouse robotics and automation systems", "Autonomous mobile robots (AMRs) for fulfilment", "AI-driven warehouse orchestration software", "End-to-end e-commerce fulfilment solutions", "Robotic picking and sortation systems"], "industries": ["Grocery Retail", "E-commerce", "Logistics", "Warehousing"], "employees": "1001-5000", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

