VALUES ('Products', 'Manufacturer', 'HORIBA MIRA', 'HORIBA MIRA is an automotive engineering and development consultancy headquartered at Nuneaton, Warwickshire, operating a world-class 1,000-acre proving ground. A member of the HORIBA Group, the company provides connected and autonomous vehicle (CAV) testing, development, and validation services, with over 15 years of dedicated autonomous systems expertise. HORIBA MIRA supports clients from requirements through to full autonomous system certification and real-world deployment.', '{"company_type": "Autonomous Vehicle Robotics", "website_url": "https://horiba-mira.com", "contact_email": "info@horiba-mira.com", "contact_phone": "+44 0 24 7635 5000", "contact_linkedin": "https://uk.linkedin.com/company/horiba-mira", "location": "Nuneaton, Warwickshire, UK", "certifications": ["ISO 9001", "ISO 17025", "UKAS"], "capabilities": ["Connected and autonomous vehicle testing", "ADAS and robotics system validation", "Proving ground and simulation testing", "Cyber security for autonomous systems", "Type approval and certification support"], "industries": ["Automotive", "Defence", "Autonomous Vehicles", "Transport"], "employees": "501-1000", "established": 1946, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Antobot', 'Antobot is a Chelmsford, Essex-based agricultural robotics startup that provides affordable autonomous robots for sustainable horticulture. Founded in 2016, the company develops the Insight crop scouting system and the Assist autonomous fruit carrier that supports pickers during harvest by autonomously transporting loaded trays. Antobot focuses on soft fruit, apples, and grapes, aiming to improve the economic, social, and environmental sustainability of the horticulture sector.', '{"company_type": "Agricultural Robotics", "website_url": "https://antobot.ai", "contact_email": "talent@antobot.ai", "contact_linkedin": "https://uk.linkedin.com/company/antobot", "location": "Chelmsford, Essex, UK", "capabilities": ["Autonomous fruit carrier robots", "AI-driven crop scouting (Insight)", "Harvesting support automation", "Precision horticulture data analytics", "Embedded AI for agri-robotics"], "industries": ["Agriculture", "Horticulture", "Food Production"], "employees": "1-10", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'OC Robotics (GE Aerospace)', 'OC Robotics, now a GE Aerospace company, is a Bristol-based manufacturer of snake-arm robots for confined and hazardous environments, acquired by GE Aviation in 2017. The company developed the world''s first commercial snake-arm robots with reaches of over 3 metres and cumulative bends exceeding 180 degrees, enabling inspection and maintenance in spaces inaccessible to conventional robots. Their systems are deployed in aerospace, nuclear, petrochemical, and security sectors globally.', '{"company_type": "Industrial Robotics", "website_url": "https://ocrobotics.com", "contact_email": "info@ocrobotics.com", "contact_linkedin": "https://uk.linkedin.com/company/oc-robotics", "location": "Bristol, UK", "certifications": ["ISO 9001"], "capabilities": ["Snake-arm robot design and manufacture", "Confined space inspection robots", "Robotic systems for hazardous environments", "Aerospace engine inspection robots", "Nuclear remote inspection tooling"], "industries": ["Aerospace", "Nuclear", "Oil & Gas", "Defence", "Security"], "employees": "11-50", "established": 1997, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fieldwork Robotics', 'Fieldwork Robotics is a Cambridge-based company developing autonomous soft-fruit harvesting robots, most notably its Fieldworker 1 robot designed for raspberry and strawberry picking at speeds comparable to human workers. Founded in 2016 as a University of Plymouth and University of the West of England spinout, the company has deployed robots on farms in the UK and Portugal, with fruit sold to UK supermarkets including M&S, Sainsbury''s, and Waitrose. The company is backed by Frontier IP and has raised multiple funding rounds.', '{"company_type": "Agricultural Robotics", "website_url": "https://fieldworkrobotics.com", "contact_email": "info@fieldworkrobotics.com", "contact_phone": "+44 (0)1223 210 376", "contact_linkedin": "https://uk.linkedin.com/company/fwr-ltd", "location": "Cambridge, Cambridgeshire, UK", "capabilities": ["Autonomous soft fruit harvesting robots", "Computer vision for fruit detection", "Multi-arm robotic picking systems", "Selective and gentle harvesting", "Agricultural robot fleet deployment"], "industries": ["Agriculture", "Horticulture", "Food Production"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Touchlab', 'Touchlab is an Edinburgh-based robotics company that has developed e-skin, a tactile sensing electronic skin thinner than human skin that can be retrofitted onto robotic hands and grippers to provide real-time pressure and location sensing. Founded by Dr Zaki Hussein and based at the National Robotarium at Heriot-Watt University, the company raised $4.8 million in Seed funding led by Octopus Ventures. Touchlab is developing its e-skin as a platform for avatar teleoperation and collaborative robotics, and released an open-source ecosystem at ROSCon UK.', '{"company_type": "Collaborative Robotics", "website_url": "https://touchlab.io", "contact_email": "hello@touchlab.io", "contact_linkedin": "https://www.linkedin.com/company/touchlab-limited", "location": "Edinburgh, Scotland, UK", "capabilities": ["Tactile e-skin sensing technology", "Robotic haptic feedback systems", "Gripper and hand tactile retrofit", "Teleoperation and avatar technology", "Open-source robotics sensing platform"], "industries": ["Research & Development", "Industrial Automation", "Healthcare", "Defence"], "employees": "1-10", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
