VALUES ('Products', 'Manufacturer', 'Callen-Lenz Associates Ltd', 'Callen-Lenz is a leading UK SME and UAV specialist based in Wiltshire, founded in 2007, offering operationally proven unmanned aerial vehicle products, services, and pilot training across the uncrewed air market. The company designs and manufactures a range of multi-rotor, fixed-wing, and hybrid UAV platforms with up to 70% UK-sourced components. Callen-Lenz serves military, government, and commercial customers with bespoke unmanned systems and managed services.', '{"company_type": "Drone/UAV Manufacturer", "website_url": "https://callenlenz.com", "contact_email": "enquiries@callenlenz.com", "contact_phone": "+44 (0)1722 744946", "contact_linkedin": "https://uk.linkedin.com/company/callen-lenz", "location": "Salisbury, Wiltshire, England", "capabilities": ["Bespoke UAV design and manufacture", "Multi-rotor and fixed-wing platforms", "UAV pilot training", "Managed drone services", "Autonomy integration"], "industries": ["Defence", "Government", "Civil Surveying", "Emergency Services"], "employees": "51-200", "established": 2007, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

