VALUES ('Products', 'Manufacturer', 'Automata Technologies Ltd', 'Automata is a London-based lab automation company founded in 2015, originally developing the Eva desktop robotic arm before pivoting to focus exclusively on life sciences laboratory automation. The company''s LINQ platform integrates laboratory instruments, robotics, and software to streamline and automate scientific workflows in drug discovery and diagnostics. Automata has raised over $90 million and serves major pharmaceutical and biotech clients globally.', '{"company_type": "Warehouse Automation", "website_url": "https://www.automata.tech", "contact_linkedin": "https://uk.linkedin.com/company/automata-technologies", "location": "London, England", "capabilities": ["Laboratory automation platforms", "Robotic arm integration", "LINQ workflow automation software", "Drug discovery automation", "Life sciences robotics"], "industries": ["Life Sciences", "Pharmaceuticals", "Biotechnology", "Diagnostics"], "employees": "201-500", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Engineered Arts Ltd', 'Engineered Arts is a Falmouth, Cornwall-based company founded in 2004 that designs and manufactures social humanoid robots, including the internationally renowned Ameca, Mesmer, and RoboThespian platforms. The company''s robots are equipped with embodied AI capabilities and are deployed globally in science centres, museums, entertainment venues, and corporate environments. Engineered Arts is the global leader in social humanoid robotics and has developed an integrated robot management software suite.', '{"company_type": "Motion Control", "website_url": "https://engineeredarts.com", "contact_phone": "+44 1326 378 129", "contact_linkedin": "https://www.linkedin.com/company/engineered-arts-ltd", "location": "Falmouth, Cornwall, England", "capabilities": ["Social humanoid robot design and manufacture", "Embodied AI integration", "Robot management software", "Animatronic systems", "Human-robot interaction"], "industries": ["Entertainment", "Education", "Research", "Corporate Events", "Museums & Science Centres"], "employees": "51-100", "established": 2004, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HAL Robotics Ltd', 'HAL Robotics is a London-based robot programming software company founded in 2014 by architects and robotics experts, developing flexible simulation, programming, and control software for industrial robots in challenging manufacturing environments. The company''s decode platform enables manufacturers to rapidly program robots for variable, non-repetitive tasks including construction, aerospace, and food processing. HAL Robotics serves clients across the UK, Europe, North America, Asia, and Australia.', '{"company_type": "Motion Control", "website_url": "https://hal-robotics.com", "contact_email": "the-team@hal-robotics.com", "contact_linkedin": "https://uk.linkedin.com/company/hal-robotics-ltd", "location": "London, England", "capabilities": ["Robot programming software (decode)", "Robot simulation and digital twin", "Multi-robot orchestration", "CAD-to-robot workflow integration", "Flexible manufacturing automation"], "industries": ["Aerospace", "Automotive", "Construction", "Food & Beverage", "Manufacturing"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Open Bionics Ltd', 'Open Bionics is a Bristol-based company founded in 2014 by Joel Gibbard MBE and Samantha Payne MBE, developing clinically approved 3D-printed bionic arms for upper-limb amputees. The company''s Hero Arm is a multi-grip powered prosthetic arm that uses myoelectric signals to control grip patterns, and has been licensed by global brands including Disney, Marvel, and Konami for custom designs. Open Bionics operates from Future Space, co-located with Bristol Robotics Laboratory.', '{"company_type": "Motion Control", "website_url": "https://openbionics.com", "contact_linkedin": "https://uk.linkedin.com/company/open-bionics", "location": "Bristol, England", "certifications": ["CE Mark", "UKCA Mark", "FDA Registered"], "capabilities": ["3D-printed bionic prosthetic arms", "Myoelectric control systems", "Multi-grip robotic prosthetics", "Clinical rehabilitation robotics", "Custom prosthetic design"], "industries": ["Healthcare", "Medical Devices", "Rehabilitation"], "employees": "51-100", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dogtooth Technologies Ltd', 'Dogtooth Technologies is a Cambridge-based agricultural robotics company founded in 2014, developing intelligent robots for selective harvesting of soft fruits including strawberries and raspberries. The company''s robots use state-of-the-art computer vision and machine learning to achieve harvesting speed and accuracy comparable to human pickers, directly addressing the UK''s agricultural labour shortage. Dogtooth employs approximately 46 people and has commercially deployed its harvesting robots on UK farms.', '{"company_type": "Autonomous Vehicle", "website_url": "https://dogtooth.tech", "contact_linkedin": "https://www.linkedin.com/company/dogtooth-technologies-limited/", "location": "Haslingfield, Cambridgeshire, England", "capabilities": ["Autonomous soft fruit harvesting robots", "Computer vision for agriculture", "Machine learning crop detection", "Mobile autonomous platforms", "Yield analytics software"], "industries": ["Agriculture", "Horticulture", "Food Production"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Muddy Machines Ltd', 'Muddy Machines is a London-based agricultural robotics startup founded in 2020 that builds battery-powered autonomous field robots for selective harvesting and precision applications in horticulture. The company''s Sprout robot is an all-terrain platform designed for asparagus harvesting, using cutting-edge AI and sensor technology to autonomously navigate fields and perform precision tasks. Muddy Machines raised £7.8 million to commercialise its robotic harvesting technology for UK and European growers.', '{"company_type": "Autonomous Vehicle", "website_url": "https://www.muddymachines.com", "contact_linkedin": "https://uk.linkedin.com/company/muddymachines", "location": "London, England", "capabilities": ["Autonomous asparagus harvesting robot", "Electric agricultural field robots", "AI-based crop detection", "Precision horticulture automation", "All-terrain autonomous navigation"], "industries": ["Agriculture", "Horticulture", "Food Production"], "employees": "11-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zelim Ltd', 'Zelim is an Edinburgh-based maritime safety technology company founded in 2017 by mariners, developing the world''s first unmanned man overboard rescue vessel and AI-powered person-in-water detection systems. The company''s three products — ZOE (AI detection and tracking), Swift (fast recovery device), and Guardian (remote-operated rescue vessel) — are designed to save lives of offshore wind workers and seafarers. Zelim employs 38 people and has received funding to commercialise its life-saving autonomous rescue technology.', '{"company_type": "Autonomous Vehicle", "website_url": "https://www.zelim.co", "contact_linkedin": "https://uk.linkedin.com/company/zelimmarine", "location": "Edinburgh, Scotland", "capabilities": ["Unmanned man overboard rescue vessel", "AI maritime person detection (ZOE)", "Autonomous rescue craft", "Offshore worker safety systems", "Remote-operated marine vehicles"], "industries": ["Offshore Wind Energy", "Maritime", "Search & Rescue", "Oil & Gas"], "employees": "11-50", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


