INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ilika plc', 'Ilika is a UK-based pioneer in solid-state battery technology, developing both Stereax micro batteries for Industrial IoT and medical devices, and Goliath large-format batteries for electric vehicles. Founded in 2004 as a University of Southampton spin-out, the company is publicly listed on the London Stock Exchange (AIM: IKA). Their solid-state cells offer improved safety, energy density, and longevity over conventional lithium-ion. Headquartered in Romsey, Hampshire, Ilika works with major industrial partners including Toyota and Murata.', '{"company_type": "Battery Manufacturing", "website_url": "https://www.ilika.com", "contact_email": "info@ilika.com", "contact_phone": "+44 (0)23 8011 1400", "contact_linkedin": "https://uk.linkedin.com/company/ilika-plc", "location": "Romsey, Hampshire, UK", "capabilities": ["Solid-state battery development", "Micro battery manufacturing (Stereax)", "Large-format EV battery development (Goliath)", "Materials discovery", "Battery cell characterisation"], "industries": ["Electric Vehicles", "Medical Devices", "Industrial IoT", "Consumer Electronics"], "employees": "51-200", "established": 2004, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nexeon Ltd', 'Nexeon is a world leader in engineered silicon-based anode materials for lithium-ion batteries, founded in 2006 as an Imperial College London spin-out. Their NSP2 silicon anode technology enables up to 50% greater cell energy density compared to conventional graphite anodes. Based at Milton Park, Abingdon, Oxfordshire, they supply commercial quantities of silicon anode material to major battery manufacturers including Panasonic. Nexeon operates additional technical facilities in Japan and serves global OEMs in automotive and consumer electronics.', '{"company_type": "Battery Manufacturing", "website_url": "https://www.nexeonglobal.com", "contact_email": "info@nexeon.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/nexeon-ltd", "location": "Abingdon, Oxfordshire, UK", "capabilities": ["Silicon anode material manufacturing", "Battery material R&D", "Lithium-ion battery optimisation", "Commercial-scale anode supply", "Battery performance enhancement"], "industries": ["Electric Vehicles", "Consumer Electronics", "Energy Storage", "Battery Manufacturing"], "employees": "101-250", "established": 2006, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nyobolt Ltd', 'Nyobolt is a Cambridge-based energy storage technology company commercialising ultra-fast-charging lithium-ion batteries for high-power applications. Built on over a decade of battery research led by Professor Dame Clare Grey at the University of Cambridge, their niobium oxide anode technology enables charging in minutes without degradation. Nyobolt targets industrial equipment, power tools, and future ultra-rapid EV charging applications. The company is based at Evolution Business Park, Cambridge, with additional offices in the USA, Germany, and Japan.', '{"company_type": "Battery Manufacturing", "website_url": "https://nyobolt.com", "contact_phone": "+44 1223 865661", "contact_linkedin": "https://uk.linkedin.com/company/nyobolt", "location": "Cambridge, UK", "capabilities": ["Ultra-fast-charging battery cells", "Niobium oxide anode technology", "High-power battery systems", "Battery R&D", "Industrial power storage"], "industries": ["Electric Vehicles", "Industrial Equipment", "Consumer Electronics", "Energy Storage"], "employees": "51-200", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AESC UK Ltd (Envision AESC)', 'AESC UK, a subsidiary of Envision AESC, operates the UK''s largest battery gigafactory in Sunderland, Tyne and Wear, with 15.8 GWh initial planned capacity supplying over 200,000 electric vehicles per year. The facility predominantly supplies Nissan''s Sunderland manufacturing plant with battery cells for the Nissan Leaf and Ariya. AESC has been producing lithium-ion batteries in Sunderland since 2013 and commenced full gigafactory operations in December 2025. A second plant is in planning with UK Infrastructure Bank support.', '{"company_type": "Battery Manufacturing", "website_url": "https://aesc.co.uk", "contact_linkedin": "https://www.linkedin.com/company/envision-aesc", "location": "Sunderland, Tyne and Wear, UK", "certifications": ["ISO 9001", "IATF 16949"], "capabilities": ["Lithium-ion cell manufacturing", "Battery module assembly", "EV battery pack production", "Gigafactory operations", "Battery cell R&D"], "industries": ["Electric Vehicles", "Automotive"], "employees": "1000+", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Dukosi Ltd', 'Dukosi is a global fabless semiconductor company headquartered in Edinburgh, Scotland, developing battery management ICs that use contactless NFC-based technology to monitor individual battery cells. Their technology removes over 95% of the wiring from battery packs, making batteries simpler, safer, and more sustainable. Dukosi''s cell-level monitoring solutions are quality-certified for xEV, industrial transport, and stationary storage (BESS) applications. The company has commercial agreements with Arrow Electronics and serves customers in automotive and industrial sectors globally.', '{"company_type": "Battery Manufacturing", "website_url": "https://www.dukosi.com", "contact_linkedin": "https://uk.linkedin.com/company/dukosi", "location": "Edinburgh, Scotland, UK", "certifications": ["AEC-Q100", "ISO 26262"], "capabilities": ["Battery management ICs", "Contactless cell monitoring", "NFC-based battery sensing", "Fabless semiconductor design", "EV battery intelligence"], "industries": ["Electric Vehicles", "Industrial Transport", "Battery Energy Storage Systems", "Consumer Electronics"], "employees": "51-200", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Superdielectrics Ltd', 'Superdielectrics is a Cambridge-based energy storage technology company developing a breakthrough aqueous polymer-based storage technology that combines characteristics of supercapacitors and batteries. Based at Chesterford Research Park, Little Chesterford, Essex, their Faraday technology uses abundant, non-toxic materials with no critical or rare earth metals. The company has a development partnership with E.ON for home energy storage and previously worked with Rolls-Royce. Superdielectrics launched its Faraday 2 residential system in 2024 and is pursuing a fundraise of up to £60 million for commercial scale-up.', '{"company_type": "Battery Manufacturing", "website_url": "https://superdielectrics.com", "contact_phone": "+44 (0) 1223 679 460", "contact_linkedin": "https://www.linkedin.com/company/superdielectrics-ltd-technology", "location": "Little Chesterford, Cambridge, UK", "capabilities": ["Aqueous polymer energy storage", "Supercapacitor-battery hybrid technology", "Home energy storage systems", "Non-toxic energy storage materials", "Battery R&D"], "industries": ["Home Energy Storage", "Renewable Energy", "Grid Storage", "Aerospace"], "employees": "11-50", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Connected Energy Ltd', 'Connected Energy is a global leader in repurposing end-of-life electric vehicle batteries into second-life battery energy storage systems (BESS). Based across commercial headquarters in Newcastle upon Tyne and technical headquarters at Hethel Engineering Centre in Norfolk, the company deploys containerised BESS systems for commercial and grid applications. Connected Energy has deployed systems using batteries from Renault, BMW, and Nissan across projects in the UK and Europe. Their E-STOR systems double battery working lives, reducing waste and lowering the cost of energy storage.', '{"company_type": "Battery Manufacturing", "website_url": "https://connected-energy.co.uk", "contact_email": "info@connected-energy.co.uk", "contact_phone": "0191 495 7321", "contact_linkedin": "https://uk.linkedin.com/company/connected-energy", "location": "Newcastle upon Tyne, Tyne and Wear, UK", "capabilities": ["Second-life EV battery repurposing", "Battery energy storage system deployment", "Grid-scale BESS", "Commercial BESS", "Battery testing and qualification"], "industries": ["Grid Storage", "Commercial Energy Storage", "Renewable Energy Integration", "Fleet Operations"], "employees": "51-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Invinity Energy Systems plc', 'Invinity Energy Systems is the UK''s largest manufacturer of grid-scale vanadium flow batteries (VFBs), with manufacturing facilities in Motherwell and Bathgate, Scotland. Listed on the Aquis Stock Exchange (IES), Invinity produces its VS3 vanadium flow battery system for commercial, industrial, and utility-scale energy storage. Their batteries can cycle indefinitely without capacity loss, making them ideal for long-duration storage alongside renewable energy. Invinity quadrupled its UK manufacturing capacity in 2024 and has deployed projects at Energy Superhub Oxford and internationally.', '{"company_type": "Battery Manufacturing", "website_url": "https://invinity.com", "contact_email": "connect@invinity.com", "contact_phone": "+44 204 526 5789", "contact_linkedin": "https://www.linkedin.com/company/invinity-energy-systems", "location": "Motherwell, Scotland, UK", "certifications": ["UL 9540", "IEC 62619"], "capabilities": ["Vanadium flow battery manufacturing", "Grid-scale energy storage", "Long-duration energy storage", "Battery system integration", "O&M services"], "industries": ["Utility Grid Storage", "Renewable Energy", "Commercial & Industrial Storage", "Microgrids"], "employees": "51-200", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sunamp Ltd', 'Sunamp develops, designs, and manufactures compact thermal energy storage heat batteries at its headquarters and factory in Macmerry, East Lothian, Scotland. Their phase-change material (PCM) technology stores thermal energy up to ten times more densely than water, enabling compact hot water and heating solutions for residential and commercial buildings. Sunamp received the prestigious King''s Award for Enterprise in Innovation in 2024. The company distributes products through approved installers across the UK, Europe, and Australia, with annual revenues of approximately £8.8 million.', '{"company_type": "Battery Manufacturing", "website_url": "https://sunamp.com", "contact_email": "info@sunamp.com", "contact_phone": "+44 (0)1875 610001", "contact_linkedin": "https://uk.linkedin.com/company/sunamp", "location": "Macmerry, East Lothian, Scotland, UK", "certifications": ["MCS", "ErP Directive compliant"], "capabilities": ["Phase-change material heat battery manufacturing", "Thermal energy storage", "Domestic hot water systems", "Space heating integration", "Grid-interactive thermal storage"], "industries": ["Residential Heating", "Commercial Buildings", "Renewable Energy Integration", "Smart Homes"], "employees": "51-200", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Highview Power Ltd', 'Highview Power is a long-duration energy storage pioneer headquartered in London, developing and deploying liquid air energy storage (LAES) at grid scale. Their CRYOBattery systems store electricity by cooling air to -196°C, then expanding it to regenerate power on demand. In June 2024, Highview secured £300 million backed by UK Infrastructure Bank, Centrica, Goldman Sachs, and Rio Tinto. Their 300 MWh Carrington project near Manchester is scheduled to commission in 2026, with further multi-GWh projects planned at Hunterston and Killingholme.', '{"company_type": "Battery Manufacturing", "website_url": "https://highviewpower.com", "contact_email": "info@highviewpower.com", "contact_phone": "+44 (0) 203 350 1000", "contact_linkedin": "https://uk.linkedin.com/company/highview-power-storage", "location": "London, UK", "capabilities": ["Liquid air energy storage (LAES)", "Long-duration grid storage", "CRYOBattery systems", "Renewable energy integration", "Grid balancing services"], "industries": ["Utility Grid Storage", "Renewable Energy", "Long-Duration Energy Storage", "Industrial"], "employees": "51-200", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Storelectric Ltd', 'Storelectric is a UK developer of large-scale compressed air energy storage (CAES) using underground salt caverns for long-duration energy storage. Based in Chester, the company has acquired CAES technology assets and is developing its flagship TeesCAES project in Teesside, having exchanged contracts for approximately 550 acres of industrial land from SABIC. TeesCAES has progressed through Ofgem''s LDES cap-and-floor scheme''s initial phase. Storelectric''s technology stores renewable energy at times of surplus for dispatch during peak demand, targeting multi-GWh grid storage.', '{"company_type": "Battery Manufacturing", "website_url": "https://storelectric.com", "contact_email": "enquiries@storelectric.com", "contact_phone": "+44 (0) 203 318 6049", "contact_linkedin": "https://uk.linkedin.com/company/storelectric", "location": "Chester, Cheshire, UK", "capabilities": ["Compressed air energy storage (CAES)", "Underground cavern storage", "Long-duration grid storage", "Renewable energy integration", "LDES project development"], "industries": ["Utility Grid Storage", "Renewable Energy", "Long-Duration Energy Storage", "Industrial"], "employees": "11-50", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AMTE Power plc', 'AMTE Power was the UK''s leading next-generation lithium-ion and sodium-ion battery cell manufacturer, operating a production facility in Thurso, Caithness, Scotland. Founded to commercialise advanced battery cell technology including Ultra High Power and sodium-ion cells, AMTE Power was listed on AIM. Following administration in 2024, the manufacturing assets and IP at Thurso were acquired by Dutch battery technology firm LionVolt, which is continuing operations at the site. The facility remains a strategically important UK battery manufacturing capability for defence, industrial, and EV applications.', '{"company_type": "Battery Manufacturing", "website_url": "https://www.amtepower.com", "contact_linkedin": "https://uk.linkedin.com/company/amte-power-ltd.", "location": "Thurso, Caithness, Scotland, UK", "capabilities": ["Lithium-ion cell manufacturing", "Sodium-ion cell manufacturing", "Ultra High Power cells", "Battery R&D", "Prismatic and cylindrical cell formats"], "industries": ["Defence", "Industrial", "Electric Vehicles", "Marine", "Energy Storage"], "employees": "51-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pod Point Ltd (Pod Energy)', 'Pod Point is one of the UK''s leading electric vehicle charging companies, operating the third-largest public charging network in the UK with over 9,200 bays. Founded in 2009 and majority-owned by EDF Energy, Pod Point supplies and installs smart home chargers for residential customers and commercial charging solutions for workplaces, retail, and fleets. Rebranded to Pod Energy and operating via podenergy.com, the company provides 24/7 customer support. Pod Point chargers are available across major UK supermarkets, hospitals, car parks, and motorway services.', '{"company_type": "EV Charging", "website_url": "https://podenergy.com", "contact_email": "info@pod-point.com", "contact_phone": "+44 20 7247 4114", "contact_linkedin": "https://uk.linkedin.com/company/pod-point", "location": "London, UK", "certifications": ["OZEV-approved installer", "MCS"], "capabilities": ["Home EV charger supply and installation", "Commercial charge point deployment", "Public charging network operation", "Fleet charging solutions", "Smart charging software"], "industries": ["Electric Vehicles", "Retail", "Hospitality", "Fleet Management", "Property Development"], "employees": "201-500", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'bp pulse (Chargemaster Ltd)', 'bp pulse, operating through Chargemaster Ltd acquired by BP in 2018, is one of the UK''s largest electric vehicle charging network operators with thousands of charge points nationwide. Headquartered in Milton Keynes, the company provides home, workplace, and public rapid charging infrastructure. bp pulse manages the UK''s largest rapid charging hub in Milton Keynes and works with major businesses, retailers, and fleet operators to deploy charging solutions. The brand provides hardware, software, and managed network services for EV charging.', '{"company_type": "EV Charging", "website_url": "https://www.bppulse.co.uk", "contact_phone": "0800 464 3444", "contact_linkedin": "https://uk.linkedin.com/company/bppulse", "location": "Milton Keynes, Buckinghamshire, UK", "certifications": ["OZEV-approved"], "capabilities": ["Public EV rapid charging", "Workplace charging solutions", "Home charging supply", "Charge point network management", "Fleet charging"], "industries": ["Electric Vehicles", "Retail", "Fleet Management", "Workplace", "Hospitality"], "employees": "201-500", "established": 2008, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Andersen EV plc', 'Andersen EV is a UK-based designer and manufacturer of premium design-led home electric vehicle charging points, headquartered at Stewartby Business Park, Bedfordshire. Founded in 2015 and a registered PLC, Andersen produces the award-winning A2 and A3 home EV charger ranges featuring bespoke finishes, interchangeable faceplates, and smart app-based controls. The chargers are manufactured in the UK and sold through authorised installers. Andersen has won multiple product design awards and targets the premium residential and luxury property market.', '{"company_type": "EV Charging", "website_url": "https://andersen-ev.com", "contact_email": "helpdesk@andersen-ev.com", "contact_phone": "01234 916125", "contact_linkedin": "https://uk.linkedin.com/company/andersenev", "location": "Stewartby, Bedfordshire, UK", "certifications": ["OZEV-approved", "CE Marked"], "capabilities": ["Premium home EV charger design and manufacture", "Smart charging app integration", "Bespoke finish options", "OZEV-approved installation network", "Solar PV integration"], "industries": ["Electric Vehicles", "Residential", "Property Development"], "employees": "11-50", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GRIDSERVE Sustainable Energy Ltd', 'GRIDSERVE is a technology-enabled sustainable energy business headquartered in Swindon, Wiltshire, specialising in electric vehicle charging infrastructure and solar-plus-storage energy generation. The company operates the GRIDSERVE Electric Highway, a nationwide high-power EV charging network, including Electric Forecourts with 30+ high-power charge points at single locations. Founded in 2017, GRIDSERVE acquired the Ecotricity Electric Highway network in 2021. The company builds solar farms with battery storage and develops its EV network under a ''sun-to-wheel'' strategy.', '{"company_type": "EV Charging", "website_url": "https://www.gridserve.com", "contact_email": "info@gridserve.co.uk", "contact_phone": "0800 240 4242", "contact_linkedin": "https://uk.linkedin.com/company/gridserve", "location": "Swindon, Wiltshire, UK", "certifications": ["OZEV-approved"], "capabilities": ["High-power EV charging network", "Electric forecourt operation", "Solar farm development", "Battery energy storage", "EV leasing"], "industries": ["Electric Vehicles", "Renewable Energy", "Retail", "Transport"], "employees": "201-500", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Connected Kerb Ltd', 'Connected Kerb is a UK-based on-street and kerbside electric vehicle charging company, operating over 6,800 charge points nationally and serving over 27 local authorities. Headquartered in London''s Soho district, the company focuses on delivering inclusive EV charging infrastructure for the 60% of UK residents without off-street parking. Following its acquisition of assets from Trojan Energy in February 2026, Connected Kerb expanded its pavement-level charging capabilities. The company plans, funds, deploys, and operates local charging networks in partnership with councils.', '{"company_type": "EV Charging", "website_url": "https://connectedkerb.com", "contact_email": "hello@connectedkerb.com", "contact_phone": "0800 029 1696", "contact_linkedin": "https://uk.linkedin.com/company/connected-kerb", "location": "London, UK", "certifications": ["OZEV-approved"], "capabilities": ["On-street kerbside EV charging", "Local authority charging networks", "Charge point operation", "Pavement-flush charger technology", "Network management software"], "industries": ["Local Government", "Electric Vehicles", "Urban Infrastructure", "Property"], "employees": "51-200", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Be.EV Ltd', 'Be.EV is a rapidly growing UK public EV charging network operator, headquartered in Manchester and operating over 2,500 rapid and ultra-rapid charge bays across the country. Founded in 2019, Be.EV is backed by Octopus Energy Group and focuses on high-power public charging at motorway services, retail parks, and urban destinations. In 2025, Be.EV expanded significantly by acquiring the UK public charging network of Mer. The company provides 24/7 customer support and operates the Manchester Charging Oasis, one of the UK''s largest urban charging hubs.', '{"company_type": "EV Charging", "website_url": "https://be-ev.co.uk", "contact_email": "support@be-ev.co.uk", "contact_phone": "0800 917 3208", "contact_linkedin": "https://uk.linkedin.com/company/be-ev", "location": "Manchester, UK", "certifications": ["OZEV-approved"], "capabilities": ["Public rapid EV charging network", "Ultra-rapid charge point operation", "EV charging network expansion", "Charge point management software", "24/7 customer support"], "industries": ["Electric Vehicles", "Retail", "Motorway Services", "Urban Infrastructure"], "employees": "11-50", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Osprey Charging Network Ltd', 'Osprey Charging is a UK independent rapid electric vehicle charging network operator, headquartered in Canterbury, Kent. Founded in 2016 (originally as Engenie Electric Vehicle Rapid Charging), Osprey operates a national network of rapid and ultra-rapid charge points at forecourts, convenience stores, and destination sites. The company is backed by Cube Infrastructure Fund and focuses on deploying 75 kW and 175 kW chargers at high-footfall locations across England, Scotland, and Wales. Osprey provides 24/7 customer support and uses the latest payment technology.', '{"company_type": "EV Charging", "website_url": "https://www.ospreycharging.co.uk", "contact_email": "support@ospreycharging.co.uk", "contact_phone": "+44 3300 101 757", "contact_linkedin": "https://uk.linkedin.com/company/osprey-charging-network", "location": "Canterbury, Kent, UK", "certifications": ["OZEV-approved"], "capabilities": ["Public rapid EV charging", "Ultra-rapid charge point operation", "Forecourt charging solutions", "Charge point network management", "Revenue-share site partnerships"], "industries": ["Electric Vehicles", "Retail", "Fuel Retail", "Transport"], "employees": "51-200", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zest (Zest Eco Ltd)', 'Zest is one of the UK''s fastest-growing electric vehicle charge point operators (CPOs), headquartered in Leeds, West Yorkshire. Founded as a B Corp certified business backed by Zouk Capital and the Charging Infrastructure Investment Fund, Zest provides fully funded, zero upfront cost EV charging solutions for local authorities, brands, and destinations. The company specialises in deploying and managing commercial charging infrastructure and has secured partnerships with major retailers and councils across the UK. Zest targets accessible and affordable EV charging for all drivers.', '{"company_type": "EV Charging", "website_url": "https://www.zest.uk.com", "contact_email": "customersupport@zest.uk.com", "contact_linkedin": "https://uk.linkedin.com/company/zestcharging", "location": "Leeds, West Yorkshire, UK", "certifications": ["OZEV-approved", "B Corp Certified"], "capabilities": ["Commercial EV charge point deployment", "Fully funded charging solutions", "Charge point operation and management", "Fleet charging partnerships", "Local authority EV strategies"], "industries": ["Electric Vehicles", "Local Government", "Retail", "Commercial Real Estate"], "employees": "51-200", "established": 2022, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Evolt Charging (SWARCO Smart Charging Ltd)', 'Evolt Charging, trading name of SWARCO Smart Charging Ltd, is a UK EV charging infrastructure provider based in Hemel Hempstead, Hertfordshire, with over 180 staff and more than 13,000 commercial charging stations installed across the UK. The company rebranded from SWARCO Smart Charging to Evolt Charging in April 2024 and provides end-to-end EV charging solutions including design, connection, installation, software, and nationwide service and maintenance. Evolt serves local authorities, fleets, workplaces, and charge point operators across the UK.', '{"company_type": "EV Charging", "website_url": "https://evoltcharging.co.uk", "contact_email": "driversupport.uk@swarco.com", "contact_phone": "0808 281 3508", "contact_linkedin": "https://uk.linkedin.com/company/swarco-smart-charging", "location": "Hemel Hempstead, Hertfordshire, UK", "certifications": ["OZEV-approved", "ISO 9001"], "capabilities": ["Commercial EV charger installation", "Charge point management software", "Fleet and workplace charging", "Local authority charging networks", "EV infrastructure maintenance"], "industries": ["Electric Vehicles", "Fleet Management", "Local Government", "Workplace", "Retail"], "employees": "201-500", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ITM Power plc', 'ITM Power is a Sheffield-based manufacturer of proton exchange membrane (PEM) electrolysers for green hydrogen production, listed on the London Stock Exchange (AIM: ITM). The company opened the world''s largest electrolyser manufacturing facility at its Sheffield Gigafactory (1 GW/year capacity) in 2023. ITM provides electrolysers for industrial decarbonisation, transport, power-to-gas, and energy storage projects across Europe and beyond. Major partnerships include Linde, Shell, and Ørsted. ITM designs, manufactures, and integrates complete hydrogen production systems.', '{"company_type": "Hydrogen Electrolyser", "website_url": "https://itm-power.com", "contact_phone": "+44 (0)114 263 7646", "contact_linkedin": "https://www.linkedin.com/company/itm-power", "location": "Sheffield, South Yorkshire, UK", "certifications": ["ISO 9001", "CE Marked", "ATEX"], "capabilities": ["PEM electrolyser manufacturing", "Green hydrogen production systems", "Gigafactory-scale electrolyser production", "Hydrogen storage integration", "Power-to-gas systems"], "industries": ["Green Hydrogen", "Industrial Decarbonisation", "Power Generation", "Transport", "Renewable Energy"], "employees": "201-500", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'HiiROC Ltd', 'HiiROC is a Hull-based UK hydrogen technology company that produces hydrogen from biomethane, flare gas, or natural gas using its patented Thermal Plasma Electrolysis (TPE) process with zero CO2 emissions and solid carbon as a by-product. Founded in 2019, HiiROC has raised £26 million in funding and operates a facility at Ideal Business Park, Hull. Their technology enables low-cost, zero-emission hydrogen production at a comparable cost to conventional steam methane reforming. HiiROC is developing projects across the UK and Scottish Highlands.', '{"company_type": "Hydrogen Electrolyser", "website_url": "https://hiiroc.com", "contact_email": "info@hiiroc.com", "contact_phone": "+44.1892616233", "contact_linkedin": "https://uk.linkedin.com/company/hiiroc", "location": "Hull, East Yorkshire, UK", "capabilities": ["Thermal Plasma Electrolysis hydrogen production", "Biomethane to hydrogen conversion", "Flare gas utilisation", "Solid carbon by-product", "Modular hydrogen systems"], "industries": ["Green Hydrogen", "Industrial Decarbonisation", "Oil & Gas", "Waste Utilisation", "Power Generation"], "employees": "11-50", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ceres Power Holdings plc', 'Ceres Power is a leading developer and licensor of solid oxide electrolyser cell (SOEC) and solid oxide fuel cell (SOFC) technology, headquartered in Horsham, West Sussex. Listed on AIM (CWR), Ceres'' SteelCell technology is licensed to global partners including Bosch, Doosan, and Weichai Power for manufacture at scale. Their cells operate as both fuel cells for power generation and electrolysers for green hydrogen production using a variety of fuels. Ceres operates an asset-light licensing model, generating royalties from partner manufacturing.', '{"company_type": "Fuel Cell", "website_url": "https://www.ceres.tech", "contact_email": "info@cerespower.com", "contact_phone": "+44 1293 400 400", "contact_linkedin": "https://uk.linkedin.com/company/ceres-power", "location": "Horsham, West Sussex, UK", "certifications": ["ISO 9001"], "capabilities": ["Solid oxide fuel cell technology licensing", "Solid oxide electrolyser technology", "SteelCell manufacturing", "Green hydrogen production", "Distributed power generation"], "industries": ["Green Hydrogen", "Power Generation", "Industrial Decarbonisation", "Data Centres", "Transport"], "employees": "201-500", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Intelligent Energy Ltd', 'Intelligent Energy is a leading independent hydrogen PEM fuel cell manufacturer with 30+ years of experience, headquartered at Holywell Park, Loughborough, Leicestershire. The company manufactures fuel cell power systems from 800 W to 300 kW+ for automotive, aerospace (including world-record-density UAV fuel cells), telecoms, marine, and rail sectors. The company secured £17 million in 2024 to advance zero-emission hydrogen flight technology. Intelligent Energy has global operations in the USA, Japan, South Korea, and China, with manufacturing in Loughborough.', '{"company_type": "Fuel Cell", "website_url": "https://www.intelligent-energy.com", "contact_phone": "+44 (0)1509 271271", "contact_linkedin": "https://www.linkedin.com/company/intelligent-energy", "location": "Loughborough, Leicestershire, UK", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["PEM fuel cell manufacturing", "Hydrogen fuel cell system integration", "UAV/drone fuel cells", "Automotive fuel cell stacks", "Hydrogen power systems 800W to 300kW+"], "industries": ["Aerospace & Defence", "Automotive", "Marine", "Rail", "Telecoms"], "employees": "201-500", "established": 1994, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AFC Energy plc', 'AFC Energy is a UK-listed (AIM: AFC) developer of alkaline hydrogen fuel cell technology for stationary and maritime power generation, headquartered at Dunsfold Park, Cranleigh, Surrey. Their H-Power fuel cell systems displace diesel generators, generating zero-emission electricity from hydrogen for construction sites, events, maritime vessels, and data centres. AFC Energy has deployed systems with partners including Speedy Hire and Cummins, and demonstrated the UK''s first hydrogen-powered construction site generator. The company is advancing its H-Power system for military and maritime applications.', '{"company_type": "Fuel Cell", "website_url": "https://www.afcenergy.com", "contact_email": "info@afcenergy.com", "contact_phone": "+44 1483 276726", "contact_linkedin": "https://uk.linkedin.com/company/afc-energy", "location": "Cranleigh, Surrey, UK", "certifications": ["CE Marked", "ISO 9001"], "capabilities": ["Alkaline fuel cell systems", "H-Power generator systems", "Hydrogen power for construction", "Maritime hydrogen power", "Fuel cell system integration"], "industries": ["Construction", "Events", "Maritime", "Data Centres", "Power Generation"], "employees": "51-200", "established": 2006, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Fuel Cell Systems Ltd', 'Fuel Cell Systems Ltd (FCSL) is a UK specialist in fuel cell solutions and hydrogen refuelling systems with over 15 years of expertise, based in Hungerford, Berkshire with an additional production site in Swindon. The company designs, supplies, installs, and maintains fuel cell power systems for off-grid and backup power applications including telecoms, industrial, and remote sites. FCSL provides complete hydrogen power solutions from refuelling infrastructure to fuel cell stacks, and their Swindon facility supports increased production capacity and fuel cell recycling operations.', '{"company_type": "Fuel Cell", "website_url": "https://www.fuelcellsystems.co.uk", "contact_email": "enquiries@fuelcellsystems.co.uk", "contact_phone": "01488 507050", "contact_linkedin": "https://uk.linkedin.com/company/fuel-cell-systems-ltd-", "location": "Hungerford, Berkshire, UK", "certifications": ["ISO 9001"], "capabilities": ["Fuel cell system supply and installation", "Hydrogen refuelling infrastructure", "Off-grid fuel cell power", "Backup power systems", "Fuel cell maintenance and recycling"], "industries": ["Telecoms", "Industrial", "Remote Power", "Transport", "Military"], "employees": "11-50", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Bramble Energy Ltd', 'Bramble Energy is a Crawley-based hydrogen PEM fuel cell developer that invented the Printed Circuit Board Fuel Cell (PCBFC), a patent-protected fuel cell manufacturable on standard PCB production lines at far lower cost than conventional fuel cells. Founded in 2016 as a UCL and Imperial College London spin-out, Bramble has grown to 85 employees at its purpose-built Hydrogen Innovation Hub at Tilgate Business Park, Crawley. The company secured £12 million in 2024 for a hydrogen bus project and demonstrated the world''s first PCBFC-powered narrowboat.', '{"company_type": "Fuel Cell", "website_url": "https://www.brambleenergy.com", "contact_email": "enquiries@brambleenergy.com", "contact_phone": "+44 (0)207 679 3310", "contact_linkedin": "https://uk.linkedin.com/company/brambleenergyltd", "location": "Crawley, West Sussex, UK", "capabilities": ["PCBFC printed circuit board fuel cell manufacturing", "PEM fuel cell stacks", "Hydrogen bus fuel cells", "Marine fuel cells", "Scalable low-cost fuel cell production"], "industries": ["Transport", "Marine", "Power Generation", "Aviation", "Industrial"], "employees": "51-200", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Johnson Matthey – Hydrogen Technologies Division', 'Johnson Matthey''s Hydrogen Technologies division is the world''s leading supplier of catalyst coated membranes (CCMs) for PEM fuel cells and PEM electrolysers, manufactured at facilities in Swindon and a new £80 million gigafactory in Royston, Hertfordshire. As the only integrated supplier with in-house catalyst, membrane, and manufacturing capabilities, JM supplies CCMs to Tier 1 automotive OEMs and electrolyser manufacturers globally. The division supports both the hydrogen fuel cell vehicle market and green hydrogen production. JM has over 25 years of experience in hydrogen technologies.', '{"company_type": "Fuel Cell", "website_url": "https://matthey.com", "contact_email": "jmpr@matthey.com", "contact_phone": "+44 207 269 8001", "contact_linkedin": "https://uk.linkedin.com/company/johnson-matthey", "location": "Swindon, Wiltshire, UK", "certifications": ["ISO 9001", "IATF 16949", "ISO 14001"], "capabilities": ["Catalyst coated membrane (CCM) manufacturing", "PEM fuel cell components", "PEM electrolyser components", "Membrane electrode assembly (MEA)", "PGM catalyst development"], "industries": ["Automotive", "Green Hydrogen", "Industrial", "Power Generation", "Energy Storage"], "employees": "10000+", "established": 1817, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Arcola Energy Ltd', 'Arcola Energy is a UK hydrogen fuel cell systems integrator and Tier 1 supplier, now a wholly-owned subsidiary of Ballard Power Systems following acquisition in November 2021. Based in London with a manufacturing and engineering facility in Liverpool, Arcola integrates hydrogen fuel cell powertrains into heavy-duty vehicles including buses, refuse trucks, and trains. The company developed the proprietary A-Drive hydrogen fuel cell powertrain platform and works with Transport for London and local authorities on zero-emission fleet transitions, retrofitting both new builds and existing diesel vehicles.', '{"company_type": "Fuel Cell", "website_url": "https://www.arcolaenergy.com", "contact_phone": "0207 503 1386", "contact_linkedin": "https://www.linkedin.com/company/arcola-energy", "location": "London, UK", "certifications": ["ISO 9001"], "capabilities": ["Hydrogen fuel cell powertrain integration", "Heavy-duty vehicle hydrogen retrofitting", "A-Drive powertrain platform", "Fleet hydrogen transition", "Bus and truck fuel cell systems"], "industries": ["Transport", "Municipal Fleet", "Public Transit", "Freight"], "employees": "51-200", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Luxfer Gas Cylinders Ltd', 'Luxfer Gas Cylinders is a UK manufacturer of high-pressure composite and aluminium gas cylinders, with its European headquarters at Colwick Industrial Estate, Nottingham. A division of Luxfer Holdings PLC (NYSE: LXFR), the company produces lightweight type 3 (aluminium-lined) and type 4 (fully composite) cylinders for hydrogen storage and transport applications. Their G-Stor H2 and G-Stor Pro cylinder ranges are widely used in hydrogen fuel cell vehicles, HRS stations, and distributed hydrogen networks. Luxfer is a member of the UK Hydrogen Energy Association and is a key enabler of the hydrogen supply chain.', '{"company_type": "Hydrogen Electrolyser", "website_url": "https://www.luxfercylinders.com", "contact_email": "LGCN-InsideSales@Luxfer.com", "contact_phone": "+44 (0)115 980 3800", "contact_linkedin": "https://www.linkedin.com/company/luxfer", "location": "Nottingham, Nottinghamshire, UK", "certifications": ["ISO 9001", "DOT", "EC/PED", "TPED"], "capabilities": ["High-pressure hydrogen cylinder manufacturing", "Composite cylinder production (Type 3 & Type 4)", "Aluminium cylinder manufacturing", "Hydrogen storage solutions", "Alternative fuel cylinders"], "industries": ["Green Hydrogen", "Transport", "Industrial Gas", "Defence", "Aerospace"], "employees": "201-500", "established": 1898, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Viritech Ltd', 'Viritech is a UK hydrogen fuel cell powertrain technology company based at MIRA Technology Park, Nuneaton, Warwickshire. The company develops plug-and-play hydrogen fuel cell and combustion powertrains, generators, and enabling systems for automotive, HGV trucks, aerospace, marine, and distributed power applications. Viritech has received Advanced Propulsion Centre and government funding to develop the ICEBreaker hydrogen-electric HGV powertrain with HORIBA MIRA and collaborated with Nuvera on commercial FCEV powertrains. The company also launched the H2 Fill hydrogen refuelling solution in 2024.', '{"company_type": "Fuel Cell", "website_url": "https://www.viritech.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/viritech", "location": "Nuneaton, Warwickshire, UK", "capabilities": ["Hydrogen fuel cell powertrain development", "Hydrogen combustion engine integration", "HGV hydrogen systems", "H2 Fill hydrogen refuelling", "Distributed hydrogen power"], "industries": ["Transport", "Heavy Goods Vehicles", "Aerospace", "Marine", "Power Generation"], "employees": "11-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mer Charging UK Ltd', 'Mer UK is a specialist electric vehicle fleet charging solutions provider, backed by Statkraft, Europe''s largest renewable energy producer. Based in Consett, County Durham, Mer UK provides comprehensive EV charging infrastructure for last-mile delivery and logistics, construction, public sector, and workplace fleets. The company previously operated a public charging network that was acquired by Be.EV in 2025, and now focuses exclusively on B2B fleet solutions. Mer UK serves clients including Durham County Council and the Port of Tyne, deploying both hardware and managed services.', '{"company_type": "EV Charging", "website_url": "https://uk.mer.eco", "contact_email": "accounts.uk@mer.eco", "contact_phone": "020 3884 2768", "contact_linkedin": "https://uk.linkedin.com/company/mer-charging", "location": "Consett, County Durham, UK", "certifications": ["OZEV-approved"], "capabilities": ["Fleet EV charging infrastructure", "Workplace charging solutions", "EV charging hardware supply", "Charge point management software", "Fleet electrification consultancy"], "industries": ["Fleet Management", "Logistics", "Construction", "Local Government", "Utilities"], "employees": "51-200", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Equans UK (GeniePoint Network)', 'Equans UK operates the GeniePoint Network, the third-largest rapid public EV charging network in the UK, with over 900 rapid charge points at convenient locations nationwide. Part of French utilities giant Equans (formerly ENGIE), the UK operations are based in the North East of England (NE12 8EX). Equans also provides B2B EV infrastructure solutions covering installation, charge point management software, and fleet charging for workplaces and local authorities. The GeniePoint network provides 50 kW rapid chargers capable of an 80% charge in 45 minutes.', '{"company_type": "EV Charging", "website_url": "https://www.equans.co.uk/ev-solutions", "contact_email": "geniesupport@equans.com", "contact_phone": "0800 999 4240", "contact_linkedin": "https://uk.linkedin.com/company/equans-uk", "location": "North East, England, UK", "certifications": ["OZEV-approved"], "capabilities": ["Public rapid EV charging network (GeniePoint)", "Workplace charging solutions", "Charge point management software", "Fleet electrification", "EV infrastructure installation and maintenance"], "industries": ["Electric Vehicles", "Fleet Management", "Workplace", "Local Government", "Retail"], "employees": "1000+", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Clean Power Hydrogen plc (CPH2)', 'Clean Power Hydrogen plc (CPH2) is a Doncaster-based designer and manufacturer of the proprietary Membrane-Free Electrolyser™, which produces green hydrogen without the costly polymer membranes used in conventional PEM systems. Listed on the London Stock Exchange AIM market (ticker: CPH2) since February 2022, the company targets industrial, transport, and energy storage applications with a scalable modular electrolyser design. CPH2 holds ISO 9001, ISO 14001, ISO 45001 certifications and has been awarded ''Fit for Hydrogen'' status by the Nuclear AMRC. Their facility at Doncaster serves as both R&D headquarters and manufacturing base for UK and international deployments.', '{"company_type": "Hydrogen Electrolyser", "website_url": "https://www.cph2.com", "contact_email": "info@cph2.com", "contact_phone": "+44 (0)1302 328075", "contact_linkedin": "https://uk.linkedin.com/company/clean-power-hydrogen-plc", "location": "Doncaster, South Yorkshire, UK", "certifications": ["ISO 9001:2015", "ISO 14001:2015", "ISO 45001:2018", "CE Marking", "Fit for Hydrogen (F4H2)", "LSE Green Economy Mark"], "capabilities": ["Membrane-Free Electrolyser design and manufacture", "Green hydrogen production systems", "Modular electrolyser scaling", "R&D in cryogenic hydrogen electrolysis", "Industrial hydrogen supply solutions"], "industries": ["Hydrogen Production", "Renewable Energy", "Heavy Transport", "Industrial Decarbonisation", "Energy Storage"], "employees": "51-100", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Kensa Heat Pumps', 'Kensa Heat Pumps is the UK''s only dedicated manufacturer of ground source heat pumps and the long-established market leader in the sector, having designed and manufactured GSHPs from its Cornwall base since 1999. The company specialises in retrofitting social housing and high-rise buildings with low-carbon heating, and operates investor-funded ground source heat pump networks. With major investment from Legal & General and Octopus Energy, Kensa has ramped up manufacturing capacity to over 23,000 GSHPs per year.', '{"company_type": "Heat Pump Manufacturer", "website_url": "https://kensa.co.uk", "contact_email": "info1@kensa.co.uk", "contact_phone": "+44 1872 862140", "contact_linkedin": "https://uk.linkedin.com/company/kensa-heat-pumps", "location": "Truro, Cornwall", "certifications": ["MCS", "Made in Britain"], "capabilities": ["Ground source heat pump manufacturing", "Residential and social housing GSHP installation", "Communal GSHP district network development", "Heat pump system design and commissioning", "Underground infrastructure ownership", "Social housing decarbonisation"], "industries": ["Residential Heating", "Social Housing", "Commercial Buildings", "Renewable Energy"], "employees": "51-200", "established": 1999, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mixergy', 'Mixergy makes smart connected hot water cylinders that function as heat batteries, enabling grid operators to connect more renewable energy while reducing bills for homeowners and tenants. Founded in 2014 in Thame, Oxfordshire, the company''s patented top-down heating technology delivers hot water up to 5x faster with electric and 2x faster with gas than conventional tanks. Mixergy received the King''s Award for Enterprise in Innovation in 2025, recognising its mission to decarbonise buildings and support the UK''s net zero heating transition.', '{"company_type": "Heat Battery / Smart Hot Water", "website_url": "https://www.mixergy.co.uk", "contact_email": "info@mixergy.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/mixergy-ltd", "location": "Thame, Oxfordshire", "certifications": ["King''s Award for Enterprise: Innovation 2025", "MCS"], "capabilities": ["Smart hot water cylinder manufacturing", "Heat battery technology", "Grid demand flexibility services", "IoT connectivity for heating systems", "Residential and commercial hot water storage", "Renewable energy integration via thermal storage"], "industries": ["Residential Buildings", "Commercial Buildings", "Energy Flexibility", "Renewable Energy Integration"], "employees": "51-100", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Sunamp', 'Sunamp pioneers compact thermal energy storage using patented phase change materials, manufacturing Thermino heat batteries that are up to ten times more energy dense and occupy up to 90% less space than conventional hot water cylinders. Founded in 2005 and headquartered near Edinburgh, Scotland, the company has received £9.25 million in UK Government funding and its batteries integrate with heat pumps from Mitsubishi and NIBE for residential and commercial applications. Sunamp actively supports grid stabilisation through its EXTEND project, which addresses periods of low renewable energy output.', '{"company_type": "Thermal Energy Storage", "website_url": "https://sunamp.com", "contact_email": "info@sunamp.com", "contact_phone": "+44 1875 610001", "contact_linkedin": "https://uk.linkedin.com/company/sunamp-limited", "location": "Macmerry, East Lothian, Scotland", "certifications": ["MCS", "Innovate UK funded"], "capabilities": ["Phase change material thermal battery manufacturing", "Compact hot water and heating storage", "Heat pump compatible thermal storage", "Renewable energy integration", "Grid flexibility services", "District heating thermal storage"], "industries": ["Residential Heating", "Commercial Buildings", "Renewable Energy", "Energy Storage"], "employees": "51-100", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'tepeo', 'tepeo is a London-based clean technology company that developed the Zero Emission Boiler (ZEB), a heat battery boiler that stores electrical energy as heat and distributes it via a home''s existing radiators with no fuel combustion whatsoever. Founded in 2018, the ZEB installs in one to two days as a direct replacement for conventional gas boilers, cutting 100% of direct home heating carbon emissions and reducing running costs by up to £1,500 per year on smart tariffs. tepeo''s products are designed for grid demand response, helping balance renewable energy on the UK electricity network.', '{"company_type": "Heat Battery / Zero Emission Boiler", "website_url": "https://www.tepeo.com", "contact_email": "customer.service@tepeo.com", "contact_linkedin": "https://uk.linkedin.com/company/tepeo", "location": "London", "certifications": ["MCS"], "capabilities": ["Zero emission electric boiler manufacturing", "Heat battery thermal storage", "Smart tariff energy optimisation", "Drop-in retrofit heating replacement", "Grid demand response", "Home heating decarbonisation"], "industries": ["Residential Heating", "Building Decarbonisation", "Renewable Energy Integration", "Smart Energy"], "employees": "11-50", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'NIBE Energy Systems UK', 'NIBE Energy Systems UK is the British subsidiary of Swedish heating technology leader NIBE, distributing and supporting a comprehensive range of air source, ground source, and exhaust air heat pumps across the UK residential and commercial markets. Based in Chesterfield, the UK operation supports a national installer network and provides technical training, specification support, and after-sales service for NIBE''s award-winning heat pump range. NIBE products won multiple UK awards in 2024 including Energy Saving Product of the Year, Heat Pump of the Year, and Technology of the Year.', '{"company_type": "Heat Pump Manufacturer / Distributor", "website_url": "https://www.nibe.co.uk", "contact_phone": "+44 330 311 2201", "contact_linkedin": "https://www.linkedin.com/company/nibe-energy-systems/", "location": "Chesterfield, Derbyshire", "certifications": ["MCS", "Heat Pump Association member"], "capabilities": ["Air source heat pump supply and support", "Ground source heat pump distribution", "Exhaust air heat pump systems", "Installer training and certification", "Technical specification support", "Commercial HVAC and heat pump systems"], "industries": ["Residential Heating", "Commercial HVAC", "Building Services", "Renewable Energy"], "employees": "51-100", "established": 2006, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Vaillant Group UK', 'Vaillant Group UK is the British operation of the global heating technology manufacturer, supplying air source heat pumps, hybrid heating systems, boilers, and smart energy management solutions to the UK residential and commercial markets. Based in Belper, Derbyshire, Vaillant UK provides its full aroTHERM and flexoCOMPACT heat pump range to a national installer network supported by training programmes and the myVaillant Pro digital platform. The company plays a key role in supporting UK decarbonisation of heating through its heat pump adoption programmes.', '{"company_type": "Heat Pump Manufacturer / HVAC", "website_url": "https://www.vaillant.co.uk", "contact_phone": "+44 1773 824141", "contact_linkedin": "https://uk.linkedin.com/company/vaillant-ltd", "location": "Belper, Derbyshire", "certifications": ["MCS", "Which? Trusted Trader"], "capabilities": ["Air source heat pump supply", "Hybrid heating systems", "Smart energy management", "Installer training and certification", "Nationwide service and maintenance", "Commercial HVAC solutions"], "industries": ["Residential Heating", "Commercial HVAC", "Building Services", "Renewable Energy"], "employees": "101-200", "established": 1874, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Daikin Airconditioning UK', 'Daikin Airconditioning UK Limited is a wholly owned subsidiary of Daikin Europe NV, serving as the UK''s primary supplier and distributor of Daikin heat pumps, air conditioning, and HVAC solutions for residential, commercial, and industrial applications. Incorporated in 2002 and headquartered in Weybridge, Surrey, the company delivers air-to-water and air-to-air heat pump technologies, ventilation, and refrigeration products across the UK. Daikin UK expanded its residential heat pump service network in Scotland through the acquisition of Saltire Facilities Management Ltd in 2025.', '{"company_type": "Heat Pump Manufacturer / HVAC", "website_url": "https://www.daikin.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/daikinuk", "location": "Weybridge, Surrey", "certifications": ["MCS", "REFCOM"], "capabilities": ["Air source heat pump supply", "Air conditioning systems", "Ventilation and air quality", "Refrigeration systems", "Heat pump installation and servicing", "Smart HVAC controls"], "industries": ["Residential Heating", "Commercial HVAC", "Industrial Cooling", "Building Services"], "employees": "201-500", "established": 2002, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Highview Power', 'Highview Power is a pioneer in long-duration energy storage using Liquid Air Energy Storage (LAES) technology, which stores excess renewable energy by cooling air to a cryogenic liquid and converting it back to electricity on demand. Founded in 2005 and headquartered in London, the company secured £300 million in 2024 from the UK Infrastructure Bank and Centrica to build the first commercial-scale LAES plant at Carrington, Manchester, providing 300MWh of storage at 50MW over six hours. Highview''s technology requires no lithium or rare earth materials, offering a sustainable long-duration storage pathway at grid scale.', '{"company_type": "Grid Storage / Long Duration", "website_url": "https://highviewpower.com", "contact_phone": "+44 20 7872 0000", "contact_linkedin": "https://www.linkedin.com/company/highview-power", "location": "London", "certifications": ["Innovate UK funded", "UK Infrastructure Bank backed"], "capabilities": ["Liquid air energy storage (LAES) technology", "Long-duration grid storage development", "Renewable energy integration", "Grid stability and inertia services", "Large-scale energy storage project delivery", "Cryogenic energy systems engineering"], "industries": ["Grid Storage", "Renewable Energy", "Power Generation", "Energy Infrastructure"], "employees": "51-100", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gravitricity', 'Gravitricity is an Edinburgh-based clean energy company developing gravity-based long-duration underground energy storage systems that raise and lower heavy weights in mine shafts to store and release grid electricity. Founded in 2011, the company demonstrated its GraviStore technology at Leith Port in Edinburgh and is developing commercial mine-shaft storage projects across Europe, partnering with ABB for hoist and winch technology integration. Gravitricity''s systems offer unlimited cycling without degradation, 85% round-trip efficiency, and fast 0.5-second response time, repurposing existing mining infrastructure for the energy transition.', '{"company_type": "Gravity Energy Storage", "website_url": "https://gravitricity.com", "contact_email": "info@gravitricity.com", "contact_phone": "+44 131 554 6966", "contact_linkedin": "https://www.linkedin.com/company/gravitricity", "location": "Edinburgh, Scotland", "certifications": ["Innovate UK funded", "European Investment Bank supported"], "capabilities": ["Gravity energy storage system design", "Mine shaft energy storage projects", "Long-duration underground storage", "Grid balancing and frequency response", "Mining infrastructure repurposing", "European mine-site project development"], "industries": ["Grid Storage", "Long Duration Energy Storage", "Mining Sector Decarbonisation", "Renewable Energy"], "employees": "11-50", "established": 2011, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Invinity Energy Systems', 'Invinity Energy Systems is a publicly listed UK manufacturer of vanadium flow batteries for large-scale, long-duration energy storage, traded on the London Stock Exchange AIM market under ticker IES. Created in 2020 through the merger of redT energy plc and Avalon Battery Corporation, Invinity manufactures its Endurium vanadium flow battery range at facilities in Bathgate and Motherwell, Scotland, with over 65 MWh deployed across 70 sites in 14 countries. In 2025, nine Invinity flow battery projects were selected for UK Government LDES cap-and-floor bids representing over 400 MWh of capacity.', '{"company_type": "Grid Storage / Flow Battery", "website_url": "https://invinity.com", "contact_email": "connect@invinity.com", "contact_linkedin": "https://www.linkedin.com/company/invinity-energy-systems", "location": "Edinburgh, Scotland", "certifications": ["AIM listed (IES)", "Made in Britain"], "capabilities": ["Vanadium flow battery manufacturing", "Long-duration energy storage systems", "Commercial and industrial storage projects", "Utility-scale storage deployment", "Battery system integration and commissioning", "UK LDES scheme project delivery"], "industries": ["Grid Storage", "Renewable Energy Integration", "Utility Scale Storage", "Long Duration Storage"], "employees": "101-200", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Zenobe Energy', 'Zenobe Energy is the largest independent owner and operator of battery storage in the UK, providing grid-scale BESS and EV fleet electrification solutions from development and financing through to long-term operation. Founded in 2017 and headquartered in London, Zenobe operates 730MW of grid-scale battery storage across the UK and supports over 1,000 electric vehicles worldwide, including bus and commercial vehicle fleets. The company works with grid operators, bus operators, and renewable energy developers, and is backed by JERA, the Japanese global energy company.', '{"company_type": "Grid Storage / BESS Operator", "website_url": "https://www.zenobe.com", "contact_email": "ukprojects@zenobe.com", "contact_linkedin": "https://www.linkedin.com/company/zenobe-energy-ltd", "location": "London", "capabilities": ["Grid-scale BESS development and operation", "EV fleet electrification solutions", "Battery asset financing and ownership", "Frequency response and balancing services", "Renewable energy storage", "Long-term battery asset management"], "industries": ["Grid Storage", "EV Infrastructure", "Renewable Energy", "Transport Decarbonisation"], "employees": "201-400", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Harmony Energy', 'Harmony Energy is one of the UK''s leading developers, owners, and operators of utility-scale battery energy storage systems, having surpassed 1GW of UK battery consents in 2025 and operating some of Europe''s largest BESS assets. Founded in 2010 and headquartered in Knaresborough, North Yorkshire, the company''s flagship Pillswood project in East Yorkshire at 196MW/392MWh was one of the largest BESS projects in Europe when commissioned. Harmony Energy also develops BESS projects in France, New Zealand, Poland, and Germany, and manages the listed Harmony Energy Income Trust plc.', '{"company_type": "Grid Storage / BESS Developer", "website_url": "https://harmonyenergy.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/harmony-energy", "location": "Knaresborough, North Yorkshire", "capabilities": ["Utility-scale BESS development and construction", "Battery storage asset operation", "Grid frequency response services", "Merchant energy trading", "International battery storage development", "Listed investment trust management"], "industries": ["Grid Storage", "Renewable Energy", "Energy Infrastructure", "Power Trading"], "employees": "51-100", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Carbon Clean', 'Carbon Clean is a leading global industrial carbon capture company headquartered in London, having captured over 2.1 million tonnes of CO2 across 49 sites in 10 countries using its proprietary solvent and modular CycloneCC technology. Founded in 2009 and backed by $243M from Chevron, Marubeni, and CEMEX, the company launched the CycloneCC C1 series capable of capturing up to 100,000 tonnes of CO2 per year per modular unit. Carbon Clean ranked 24th in the 2024 Deloitte Technology Fast 50 UK and operates the world''s largest post-combustion carbon capture plant at Tuticorin, India.', '{"company_type": "Carbon Capture", "website_url": "https://www.carbonclean.com", "contact_email": "info@carbonclean.com", "contact_phone": "+44 20 3507 0175", "contact_linkedin": "https://uk.linkedin.com/company/carbon-clean-ltd-official", "location": "London (Bankside)", "certifications": ["Deloitte Technology Fast 50 2024"], "capabilities": ["Industrial carbon capture technology development", "Modular CycloneCC system manufacturing", "Proprietary carbon capture solvent supply", "Point-source industrial CO2 capture", "Carbon capture for cement, steel, and power", "Turnkey carbon capture project delivery"], "industries": ["Carbon Capture", "Industrial Decarbonisation", "Cement", "Steel", "Power Generation"], "employees": "101-250", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'C-Capture', 'C-Capture is a University of Leeds spin-out specialising in novel solvent chemistry for point-source industrial carbon capture, having developed nitrogen-free solvents that require 40% less energy to regenerate than conventional amine-based systems. Founded in 2009 by Professor Chris Rayner, the company piloted its technology at Drax Power Station in North Yorkshire in partnership with Drax and bp, successfully demonstrating stable and efficient CO2 capture from biomass flue gas in 2024. C-Capture is based in Leeds and targets hard-to-abate industrial sectors including power, cement, and chemicals.', '{"company_type": "Carbon Capture", "website_url": "https://c-capture.co.uk", "contact_email": "info@c-capture.co.uk", "contact_linkedin": "https://uk.linkedin.com/company/c-capture-ltd-university-of-leeds", "location": "Leeds, West Yorkshire", "certifications": ["Innovate UK funded", "University of Leeds spin-out"], "capabilities": ["Novel carbon capture solvent chemistry", "Industrial flue gas CO2 capture", "Pilot-scale carbon capture systems", "Low-energy solvent regeneration", "Hard-to-abate sector decarbonisation", "BECCS solvent technology"], "industries": ["Carbon Capture", "Power Generation", "Industrial Decarbonisation", "Chemical Technology"], "employees": "11-50", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Storegga', 'Storegga is an independent UK carbon management business pioneering carbon capture and storage, direct air capture, and hydrogen projects, most notably as lead developer of the Acorn CCS Project in North East Scotland. Founded in 2020 and headquartered in London, Storegga leads the Scottish Cluster as part of the UK Government''s Track-1 CCUS programme and received investment from ADNOC alongside backing from Macquarie, GIC, Mitsui, Snam, and M&G. The Acorn Project targets CO2 storage in depleted offshore fields beneath the North Sea, leveraging existing North Sea infrastructure.', '{"company_type": "Carbon Capture & Storage / CCS", "website_url": "https://storegga.earth", "contact_phone": "+44 20 3757 4980", "contact_linkedin": "https://www.linkedin.com/company/storegga/", "location": "London", "certifications": ["UK Government Track-1 CCUS programme"], "capabilities": ["Carbon capture and storage project development", "Offshore CO2 geological storage", "CCS cluster project management", "Direct air capture development", "Hydrogen project development", "Carbon markets and credit structuring"], "industries": ["Carbon Capture", "Oil & Gas Transition", "Hydrogen", "Energy Infrastructure"], "employees": "51-150", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Mission Zero Technologies', 'Mission Zero Technologies is a London-based direct air capture company that has pioneered electrochemical DAC technology capable of removing historic CO2 from the atmosphere at any scale and location. Founded in 2020, the company deployed the UK''s first commercial DAC plant at the University of Sheffield and opened a second site in Norfolk in 2025 that converts captured CO2 into limestone, while also delivering its third DAC system to Deep Sky''s project in Canada. The company raised £21.8M in a Series A round from investors including Breakthrough Energy, 2150, World Fund, Fortescue, and Siemens Financial Services.', '{"company_type": "Direct Air Capture / Carbon Removal", "website_url": "https://www.missionzero.tech", "contact_email": "hello@missionzero.tech", "contact_phone": "+44 1858 438800", "contact_linkedin": "https://uk.linkedin.com/company/missionzerotech", "location": "London", "certifications": ["Breakthrough Energy backed"], "capabilities": ["Electrochemical direct air capture systems", "Modular DAC unit manufacturing", "Carbon dioxide removal (CDR)", "CO2 mineralisation to building materials", "Carbon credit generation", "International DAC project deployment"], "industries": ["Direct Air Capture", "Carbon Removal", "Climate Technology", "Building Materials"], "employees": "11-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford PV (Oxford Photovoltaics)', 'Oxford Photovoltaics (Oxford PV) is a world leader in perovskite-on-silicon tandem solar cells, having set a module efficiency record of 26.9% and shipping its first commercial 24.5% efficient tandem solar panels to utility-scale customers. Founded in 2010 as a spin-out from the University of Oxford by Professor Henry Snaith and Kevin Arthur, the company is headquartered in Yarnton, Oxfordshire, with a manufacturing pilot line in Brandenburg, Germany. Oxford PV''s tandem technology delivers higher solar output from the same roof area at cost-competitive prices, representing a generational step forward from standard silicon panels.', '{"company_type": "Solar Components / Perovskite Manufacturing", "website_url": "https://www.oxfordpv.com", "contact_phone": "+44 1865 300000", "contact_linkedin": "https://uk.linkedin.com/company/oxfordpv", "location": "Yarnton, Oxfordshire", "certifications": ["Innovate UK funded", "University of Oxford spin-out"], "capabilities": ["Perovskite-on-silicon tandem solar cell R&D", "High-efficiency solar module production", "Solar technology commercialisation", "Thin film photovoltaic manufacturing", "Industrial-scale PV process development", "Solar panel supply to utility-scale projects"], "industries": ["Solar Energy", "Photovoltaics", "Renewable Energy", "Advanced Materials"], "employees": "51-150", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Midsummer Energy', 'Midsummer Energy is one of the UK''s largest wholesale distributors of renewable energy systems, distributing solar PV panels, battery storage, EV charging equipment, off-grid systems, and renewable heat products to installers and contractors across Britain. Founded in 2005 by Dr Andrew Rankin in Cambridge, the company was voted the UK''s best renewables distributor in 2020 and 2022 and appears in Cambridgeshire''s top 100 privately-owned companies. Midsummer operates both trade and consumer channels through midsummerenergy.co.uk and midsummerwholesale.co.uk.', '{"company_type": "Solar Components / Distribution", "website_url": "https://midsummerenergy.co.uk", "contact_email": "sales@midsummerenergy.co.uk", "contact_phone": "+44 1223 851535", "contact_linkedin": "https://uk.linkedin.com/company/midsummer-energy", "location": "Cambridge, Cambridgeshire", "certifications": ["Solar Energy UK member", "RECC member"], "capabilities": ["Solar PV panel wholesale distribution", "Battery storage system supply", "EV charging equipment distribution", "Off-grid renewable system supply", "Heat pump equipment distribution", "Solar design software provision"], "industries": ["Solar Energy", "Renewable Energy Distribution", "Battery Storage", "EV Infrastructure"], "employees": "51-200", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Power Roll', 'Power Roll is a County Durham cleantech company developing ultra-thin flexible solar film technology using a patented microgroove and perovskite approach that produces cells less than 1mm thick and 25 times lighter than conventional silicon panels. Founded in 2012 and headquartered in Seaham, the company has partnered with Amcor for packaging-scale roll-to-roll manufacturing and with Queen Mary University of London for in-situ quality control technology. Power Roll''s film can be applied to surfaces where rigid panels are impractical, such as roofing membranes, agricultural buildings, and curved infrastructure.', '{"company_type": "Solar Components / Thin Film Manufacturing", "website_url": "https://www.powerroll.solar", "contact_linkedin": "https://uk.linkedin.com/company/power-roll", "location": "Seaham, County Durham", "certifications": ["Innovate UK funded", "British Business Bank backed"], "capabilities": ["Flexible thin-film solar cell development", "Perovskite solar film manufacturing", "Microgroove photovoltaic technology", "Roll-to-roll solar manufacturing", "Solar integration for non-traditional surfaces", "Lightweight portable solar applications"], "industries": ["Solar Energy", "Flexible Electronics", "Agriculture", "Built Environment"], "employees": "11-50", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lightsource bp', 'Lightsource bp is Europe''s largest solar developer and the third largest globally outside China, developing, constructing, and operating utility-scale solar PV and co-located battery storage projects across the UK and internationally. Founded in 2010 as Lightsource Renewable Energy and fully acquired by BP in 2024, the London-headquartered company has developed over 10GW of solar projects worldwide. Lightsource bp energised its first UK co-located BESS in 2024 and delivered a UK-first night-time reactive power service from a solar farm.', '{"company_type": "Solar Developer / EPC", "website_url": "https://lightsourcebp.com", "contact_email": "info@lightsourcebp.com", "contact_phone": "+44 3332 000755", "contact_linkedin": "https://uk.linkedin.com/company/lightsourcebp", "location": "London", "certifications": ["Solar Energy UK member"], "capabilities": ["Utility-scale solar project development", "Solar EPC contracting", "Solar asset operation and management", "Co-located battery storage", "Power purchase agreement structuring", "International solar project delivery"], "industries": ["Solar Energy", "Renewable Energy", "Energy Infrastructure", "Power Generation"], "employees": "1001-1500", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'British Solar Renewables (BSR)', 'British Solar Renewables is an independent UK power producer and solar project developer, EPC contractor, and asset manager specialising in utility-scale solar PV and battery energy storage systems. Founded in 2010 by Angus Macdonald and headquartered in Shepton Mallet, Somerset, BSR secured a £345M debt facility in 2025 for its 609MW portfolio and is actively developing solar-plus-storage projects across the UK and internationally. The company builds, connects, operates, and manages solar and storage projects from development through long-term operation.', '{"company_type": "Solar Developer / EPC", "website_url": "https://britishrenewables.com", "contact_phone": "+44 1458 224900", "contact_linkedin": "https://uk.linkedin.com/company/bsrgroup", "location": "Shepton Mallet, Somerset", "certifications": ["Solar Energy UK member"], "capabilities": ["Utility-scale solar project development", "Solar EPC contracting", "Battery energy storage development", "Solar and storage asset management", "Grid connection management", "Operation and maintenance services"], "industries": ["Solar Energy", "Battery Storage", "Renewable Energy", "Energy Infrastructure"], "employees": "51-150", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Anesco', 'Anesco is a UK market leader in large-scale solar and battery storage, having designed and built 144 solar farms and BESS and managing a 3GW development pipeline, with expanding operations in the Netherlands and Germany. Founded in 2010 and headquartered in Reading, Berkshire, the company develops, designs, constructs, operates, maintains, and optimises high-performing grid-scale renewable energy assets. Anesco joined Solar Energy UK as a sponsor member in 2025 and also provides energy efficiency services including LED lighting and building management systems for commercial and public sector clients.', '{"company_type": "Solar Developer / Grid Storage", "website_url": "https://anesco.com", "contact_email": "info@anesco.com", "contact_phone": "+44 845 894 4444", "contact_linkedin": "https://uk.linkedin.com/company/anesco-limited", "location": "Reading, Berkshire", "certifications": ["Solar Energy UK sponsor member"], "capabilities": ["Solar farm development and construction", "Battery energy storage systems", "Renewable asset operation and management", "Energy efficiency solutions", "Grid-scale renewable development", "European renewable energy expansion"], "industries": ["Solar Energy", "Battery Storage", "Energy Efficiency", "Commercial Buildings"], "employees": "51-200", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Drax Group', 'Drax Group plc operates the UK''s largest power station in Selby, North Yorkshire, fully converted from coal to sustainable biomass to become the UK''s largest renewable electricity generator, and is a pioneer of Bioenergy with Carbon Capture and Storage (BECCS). Listed on the London Stock Exchange, Drax received planning consent in 2024 to convert two biomass units to BECCS, targeting removal of approximately 8 million tonnes of CO2 per year when operational by the late 2020s. The company also operates a global biomass supply chain through its Drax Pellet Production business in the USA.', '{"company_type": "BECCS / Bioenergy / Carbon Capture", "website_url": "https://www.drax.com", "contact_phone": "+44 1757 618381", "contact_linkedin": "https://uk.linkedin.com/company/drax-group", "location": "Selby, North Yorkshire", "certifications": ["LSE listed (DRX)", "UK Government BECCS Development Consent Order"], "capabilities": ["Bioenergy with carbon capture and storage (BECCS)", "Sustainable biomass power generation", "Large-scale CO2 removal", "Pellet production and biomass supply chain", "Grid balancing and ancillary services", "Negative emissions technology"], "industries": ["Power Generation", "Carbon Capture", "Bioenergy", "Carbon Removal"], "employees": "1001-2500", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Field Energy', 'Field is a London-based developer, owner, and operator of grid-scale battery energy storage systems, building out a 4.5 GWh UK and European BESS pipeline backed by £200M from DIF Capital Partners. Founded in 2020 by Amit Gudka, co-founder of Bulb Energy, the company operates BESS projects in Oldham, Gerrards Cross, and Newport and has expanded into Italy and Germany. Field focuses on merchant BESS projects that provide frequency response, balancing mechanism trading, and ancillary services to support the UK energy transition.', '{"company_type": "Grid Storage / BESS Developer", "website_url": "https://www.field.energy", "contact_email": "hello@field.energy", "contact_linkedin": "https://uk.linkedin.com/company/field-energy", "location": "Shoreditch, London", "capabilities": ["Grid-scale BESS project development", "Battery storage asset operation", "Frequency response and grid balancing", "Merchant energy market participation", "European battery storage development", "Renewable energy integration"], "industries": ["Grid Storage", "Renewable Energy", "Energy Infrastructure", "Power Trading"], "employees": "201-400", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Ceres Power', 'Ceres Power Holdings plc is a FTSE 250-listed UK developer of solid oxide fuel cell (SOFC) and solid oxide electrolyser cell (SOEC) technology, licensing its SteelCell platform to major global manufacturers for green hydrogen production and distributed low-carbon power. Founded in 2001 as an Imperial College spin-out and headquartered in Horsham, West Sussex, Ceres licenses its technology to Doosan (now in mass production) and Weichai, with the South Korean manufacturer shipping commercial products in 2025. The company''s technology can generate power at up to 60% efficiency or produce green hydrogen at the highest electrolyser efficiency in the sector.', '{"company_type": "Fuel Cell / Hydrogen Technology", "website_url": "https://www.ceres.tech", "contact_email": "info@cerespower.com", "contact_linkedin": "https://www.linkedin.com/company/ceres-power/", "location": "Horsham, West Sussex", "certifications": ["LSE main market listed (CWR)", "FTSE 250"], "capabilities": ["Solid oxide fuel cell (SOFC) technology licensing", "Solid oxide electrolyser (SOEC) technology", "Green hydrogen production systems", "Distributed power generation", "Technology licensing to OEM manufacturers", "Data centre and industrial power systems"], "industries": ["Fuel Cells", "Hydrogen", "Data Centres", "Industrial Power", "Transport"], "employees": "401-550", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AFC Energy', 'AFC Energy plc is a Surrey-based manufacturer of alkaline fuel cell systems that generate clean electricity and water from hydrogen, targeting zero-emission power for construction sites, data centres, and EV charging. Founded in 2006, the AIM-listed company is headquartered at Dunsfold Aerodrome in Cranleigh and secured a partnership in 2025 with a global industrial S&P 500 company for the development of ammonia cracker technology to enable low-cost green hydrogen supply. AFC Energy''s H-Power fuel cell systems displace diesel generators in off-grid and temporary power applications.', '{"company_type": "Fuel Cell / Hydrogen Power", "website_url": "https://www.afcenergy.com", "contact_email": "info@afcenergy.com", "contact_phone": "+44 1483 276726", "contact_linkedin": "https://uk.linkedin.com/company/afc-energy", "location": "Cranleigh, Surrey", "certifications": ["AIM listed (AFC)"], "capabilities": ["Alkaline fuel cell manufacturing", "Hydrogen-to-power generation", "Zero-emission site power systems", "Data centre fuel cell power", "EV charging from hydrogen", "Ammonia cracker development"], "industries": ["Fuel Cells", "Hydrogen", "Construction", "Data Centres", "EV Infrastructure"], "employees": "11-50", "established": 2006, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Bramble Energy', 'Bramble Energy is a Crawley-based hydrogen fuel cell company that has developed a revolutionary Printed Circuit Board Fuel Cell (PCBFC) technology, replacing expensive stamped metal plates in PEM stacks with printed circuit boards to dramatically reduce manufacturing cost and complexity. Founded in 2016 as a spin-out from University College London and Imperial College London, the company employs 85 staff at its Hydrogen Innovation Hub in West Sussex and raised £35M in 2023. Bramble''s PCBFC technology targets commercial vehicle range extenders, stationary power, and portable hydrogen applications.', '{"company_type": "Fuel Cell / Hydrogen Technology", "website_url": "https://www.brambleenergy.com", "contact_email": "getintouch@brambleenergy.com", "contact_linkedin": "https://uk.linkedin.com/company/brambleenergyltd", "location": "Crawley, West Sussex", "certifications": ["Innovate UK funded", "IP Group backed"], "capabilities": ["Printed circuit board fuel cell (PCBFC) manufacturing", "PEM fuel cell stack production", "Commercial vehicle range extenders", "Stationary hydrogen power systems", "Low-cost fuel cell manufacturing technology", "High-volume fuel cell production"], "industries": ["Fuel Cells", "Hydrogen", "Commercial Vehicles", "Stationary Power", "Portable Power"], "employees": "51-100", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Tokamak Energy', 'Tokamak Energy is an Oxfordshire-based private fusion energy company developing compact spherical tokamak reactors and manufacturing high-temperature superconducting (HTS) magnets that are critical to commercial fusion and multiple other sectors. Founded in 2009 as a spin-out from the UK Atomic Energy Authority, the company raised $125M in 2024 and received a joint £40.5M UK-US government fusion project award in December 2024. Beyond fusion, Tokamak Energy''s HTS magnet technology is being commercialised for medical imaging, particle accelerators, and clean energy infrastructure.', '{"company_type": "Fusion Energy / Advanced Magnetics", "website_url": "https://tokamakenergy.com", "contact_linkedin": "https://uk.linkedin.com/company/tokamak-energy-ltd", "location": "Milton, Abingdon, Oxfordshire", "certifications": ["UKAEA spin-out", "Innovate UK funded"], "capabilities": ["Compact spherical tokamak design and development", "High-temperature superconducting magnet manufacturing", "Fusion plasma physics research", "HTS magnet technology for multiple sectors", "Fusion energy commercialisation", "Advanced energy technology R&D"], "industries": ["Fusion Energy", "Advanced Magnetics", "Clean Energy Technology", "Medical Imaging"], "employees": "201-300", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Rolls-Royce SMR', 'Rolls-Royce SMR Limited is the developer of the UK''s selected small modular reactor (SMR) technology, having been named the preferred bidder in the Great British Nuclear competition in 2025 with £2.5B in government backing and £280M consortium funding. Incorporated in 2020 and headquartered in Derby, the company employs around 600 staff across Derby, Warrington, and Manchester, developing a 470MW modular reactor designed to be factory-built and shipped in standardised modules for rapid, lower-cost deployment. Rolls-Royce SMR''s programme aims to create 40,000 UK supply chain jobs and connect the first units to the grid in the mid-2030s.', '{"company_type": "Nuclear / Small Modular Reactor", "website_url": "https://www.rolls-royce-smr.com", "contact_linkedin": "https://uk.linkedin.com/company/rolls-royce-smr", "location": "Derby, Derbyshire", "certifications": ["UK Government Great British Nuclear preferred bidder"], "capabilities": ["Small modular reactor design and development", "Factory-built nuclear module engineering", "Nuclear safety and regulatory compliance", "Low-carbon baseload power generation", "Nuclear supply chain management", "SMR project development and siting"], "industries": ["Nuclear Energy", "Power Generation", "Energy Infrastructure", "Low-Carbon Electricity"], "employees": "501-700", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Naked Energy', 'Naked Energy is a West Sussex-based global innovator in solar PVT (photovoltaic-thermal) technology, producing the world''s highest energy density solar collectors that simultaneously generate electricity and useful heat from a single roof-mounted unit. Founded in 2009 by CEO Christophe Williams, the company''s Virtu collector enables buildings to decarbonise both power and heat demand from the same solar installation. Naked Energy launched a dedicated solar thermal system design service in 2024 to help businesses plan, model, and deliver integrated solar thermal installations for industrial process heat and building decarbonisation.', '{"company_type": "Solar Thermal / PVT Technology", "website_url": "https://www.nakedenergy.com", "contact_phone": "+44 1293 541449", "contact_linkedin": "https://uk.linkedin.com/company/naked-energy-limited", "location": "Crawley, West Sussex", "certifications": ["Innovate UK funded", "Solar Energy UK member"], "capabilities": ["Solar PVT (photovoltaic-thermal) collector manufacturing", "Solar thermal system design and delivery", "Vacuum tube solar technology", "Industrial process heat from solar", "Combined heat and power generation", "Solar thermal system integration"], "industries": ["Solar Thermal", "Renewable Heat", "Industrial Decarbonisation", "Commercial Buildings"], "employees": "11-50", "established": 2009, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Storelectric', 'Storelectric is a Chester-based developer of grid-scale Compressed Air Energy Storage (CAES) using underground salt caverns in Cheshire, with each installation designed to provide 500MW of output and over 45GWh of storage capacity for long-duration grid balancing. Founded in 2012 by Jeff Draper, the company''s novel adiabatic CAES design stores compression heat and uses it during generation, avoiding gas combustion and improving efficiency compared to conventional CAES. Storelectric''s technology offers very low-cost, large-scale, zero-carbon long-duration storage to support high-renewable electricity grids.', '{"company_type": "Compressed Air Energy Storage", "website_url": "https://storelectric.com", "contact_email": "enquiries@storelectric.com", "contact_phone": "+44 203 318 6049", "contact_linkedin": "https://www.linkedin.com/company/storelectric", "location": "Chester, Cheshire", "capabilities": ["Compressed air energy storage (CAES) system design", "Salt cavern energy storage development", "Grid-scale long-duration storage", "Adiabatic CAES thermal efficiency technology", "Renewable energy balancing at GWh scale", "Energy storage project development"], "industries": ["Grid Storage", "Long Duration Energy Storage", "Renewable Energy", "Energy Infrastructure"], "employees": "1-10", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RheEnergise', 'RheEnergise is a London-based cleantech startup that developed High-Density Hydro (HD Hydro) long-duration energy storage, a compact pumped-hydro system using a fluid 2.5 times denser than water that can operate on low, hilly terrain without needing high mountains. Founded in 2019 by CEO Stephen Crosher, the company commissioned the UK''s first HD Hydro plant at the Cornwood mine site in Devon in January 2026, backed by £8.25M from the UK Government and €2.5M from the European Innovation Council. RheEnergise is now progressing commercial-scale projects in the UK, Italy, Poland, Spain, and North America.', '{"company_type": "Long Duration Energy Storage", "website_url": "https://www.rheenergise.com", "contact_linkedin": "https://uk.linkedin.com/company/rheenergise", "location": "London", "certifications": ["Innovate UK funded", "EIC Accelerator grant"], "capabilities": ["High-density hydro energy storage technology", "Low-head long-duration storage systems", "Grid-scale storage project development", "Brownfield and mine site repurposing", "Renewable energy grid balancing", "International storage project development"], "industries": ["Grid Storage", "Long Duration Energy Storage", "Renewable Energy", "Mining Sector Transition"], "employees": "11-50", "established": 2019, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'EDF Renewables UK', 'EDF Renewables UK is the renewable energy subsidiary of the EDF Group operating in Britain and Ireland, developing, constructing, and operating onshore and offshore wind, solar, and battery energy storage projects across the UK. Founded in 2008 and headquartered in London, the company is deploying over 300MW of battery storage projects across multiple UK sites in partnership with Wartsila, including completed BESS at Sundon in Bedfordshire and Bramford in Suffolk. EDF Renewables UK is targeting up to 2GW of transmission-connected battery storage in its UK pipeline, with over 400MW already consented.', '{"company_type": "Grid Storage / Renewable Energy Developer", "website_url": "https://www.edf-re.uk", "contact_phone": "+44 1452 652233", "contact_linkedin": "https://uk.linkedin.com/company/edf-renewables-uk-ireland", "location": "London (Victoria)", "certifications": ["Solar Energy UK member"], "capabilities": ["Onshore and offshore wind development", "Utility-scale solar PV development", "Grid-scale battery energy storage", "Renewable energy asset operation", "Power purchase agreements", "Grid connection and balancing services"], "industries": ["Renewable Energy", "Grid Storage", "Solar Energy", "Wind Energy", "Energy Infrastructure"], "employees": "501-700", "established": 2008, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Octopus Energy Generation', 'Octopus Energy Generation is the renewable energy investment and ownership arm of Octopus Energy Group, one of Europe''s largest specialist renewables investors managing over £7 billion of green energy assets including 138 solar farms, 16 onshore wind farms, offshore wind, and battery storage in over 15 countries. Incorporated in 2020 and headquartered in London, the company has announced a £2 billion UK renewable energy investment programme by 2030, including 222MW of new solar capacity in the pipeline. Octopus Energy Generation also co-invested with Legal & General in the UK''s largest ground source heat pump network through a partnership with Kensa.', '{"company_type": "Renewable Energy Investment / Solar & Wind", "website_url": "https://www.octopusenergygeneration.com", "contact_linkedin": "https://uk.linkedin.com/company/octopus-energy-generation", "location": "London", "capabilities": ["Solar farm ownership and operation", "Onshore and offshore wind investment", "Battery storage project investment", "Ground source heat pump network investment", "Power purchase agreement structuring", "Renewable energy asset management"], "industries": ["Solar Energy", "Wind Energy", "Grid Storage", "Renewable Energy Infrastructure", "Heat Pumps"], "employees": "101-300", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Aggreko', 'Aggreko is a Glasgow-headquartered global supplier of temporary and permanent modular power generation, battery energy storage, and temperature control equipment, serving construction, events, utilities, and industrial sectors worldwide. Founded in 1962 and formerly listed on the London Stock Exchange before going private in 2021, the company employs between 5,000 and 10,000 people globally and provides clean power solutions including hybrid solar-battery-diesel systems for off-grid and remote applications. In 2024 Aggreko acquired RenEnergy''s UK and South African businesses, strengthening its renewable energy and BESS integration capability.', '{"company_type": "Modular Power / Energy Storage", "website_url": "https://www.aggreko.com", "contact_linkedin": "https://uk.linkedin.com/company/aggreko", "location": "Glasgow, Scotland", "capabilities": ["Temporary and permanent power generation", "Mobile battery energy storage systems", "Hybrid solar-battery-diesel systems", "Temperature control and cooling", "Oil-free compressed air supply", "Clean energy transition solutions for remote sites"], "industries": ["Construction", "Events", "Utilities", "Industrial", "Mining", "Renewable Energy"], "employees": "5001-10000", "established": 1962, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');


