INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Surrey Satellite Technology Ltd (SSTL)', 'Surrey Satellite Technology Ltd (SSTL) is a world-leading small satellite manufacturer, a spin-out from the University of Surrey founded in 1985 and now wholly owned by Airbus Defence and Space. The company pioneered the design, build, test, and operation of small satellites and has launched over 70 satellites for international customers. SSTL operates two sites in Guildford and Bordon, Hampshire, employing around 500 engineers and technicians. Its portfolio spans Earth observation, navigation, science, and defence missions.', '{"company_type": "Satellite Manufacturer", "website_url": "https://www.sstl.co.uk", "contact_email": "info@sstl.co.uk", "contact_phone": "+44 (0)1483 803803", "contact_linkedin": "https://www.linkedin.com/company/sstl", "location": "Guildford, Surrey", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Small satellite design and manufacture", "Earth observation satellites", "Navigation payloads", "Satellite platforms (50kg–1000kg)", "Ground segment systems", "Satellite operations and mission control", "In-orbit demonstration missions"], "industries": ["Defence", "Earth Observation", "Navigation", "Science", "Government"], "employees": "501-1000", "established": 1985, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Airbus Defence and Space Ltd (UK)', 'Airbus Defence and Space is the UK''s largest space company, headquartered in Stevenage, Hertfordshire, with additional sites in Portsmouth and Farnborough. The Stevenage facility is the primary centre for satellite design, manufacturing, and operations in the UK, building approximately 25% of the world''s geostationary telecommunications satellites. The company employs over 3,000 skilled workers across its UK sites and has built landmark satellites including the ESA Aeolus and Sentinel 5P. Airbus Defence and Space UK contributes over £1 billion in turnover annually.', '{"company_type": "Satellite Manufacturer", "website_url": "https://www.airbus.com/en/products-services/space/space-technology-made-in-uk", "contact_email": "space@airbus.com", "contact_phone": "+44 (0)1438 773003", "contact_linkedin": "https://www.linkedin.com/company/airbus-defence-and-space", "location": "Stevenage, Hertfordshire", "certifications": ["ISO 9001", "AS9100", "ISO 14001"], "capabilities": ["Geostationary telecommunications satellites", "Earth observation spacecraft", "Navigation satellites", "Military and government satellites", "Satellite ground systems", "Space robotics and exploration", "Propulsion integration"], "industries": ["Telecommunications", "Earth Observation", "Defence", "Navigation", "Government"], "employees": "3001-5000", "established": 1989, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Eutelsat OneWeb', 'Eutelsat OneWeb (formerly OneWeb) is a global satellite internet communications company operating a constellation of Low Earth Orbit (LEO) satellites, providing high-speed, low-latency broadband connectivity worldwide. Founded in 2012 and headquartered in London, the company merged with the French Eutelsat Group in September 2023. It operates its UK headquarters at 195 Wood Lane, London, serving maritime, aviation, enterprise, and government sectors. OneWeb''s LEO constellation provides resilient connectivity even in the most remote and underserved regions.', '{"company_type": "Satellite Communications", "website_url": "https://www.eutelsat.com/en/home.html", "contact_email": "info@eutelsat.com", "contact_phone": "+44 (0)20 7034 8800", "contact_linkedin": "https://www.linkedin.com/company/oneweb", "location": "London, England", "capabilities": ["LEO satellite constellation operation", "Global broadband internet connectivity", "Maritime satellite communications", "Aviation in-flight connectivity", "Government and defence connectivity", "Enterprise satellite communications"], "industries": ["Telecommunications", "Maritime", "Aviation", "Government", "Enterprise"], "employees": "201-500", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Spire Global UK', 'Spire Global UK is the UK arm of Spire Global Inc., a leading provider of space-based data, analytics, and services, with its primary UK operations based in Glasgow, Scotland. The company designs, builds, tests, and operates all its satellites in-house from its Glasgow facility, operating a constellation of over 100 nanosatellites. Spire provides global maritime tracking (AIS), aviation surveillance (ADS-B), weather monitoring, and radio occultation data. The UK subsidiary operates from Skypark in Glasgow and the Harwell Campus in Oxfordshire.', '{"company_type": "Earth Observation", "website_url": "https://spire.com", "contact_email": "info@spire.com", "contact_phone": "+44 (0)141 343 8260", "contact_linkedin": "https://www.linkedin.com/company/spireglobal", "location": "Glasgow, Scotland", "capabilities": ["Nanosatellite manufacture and operation", "Maritime domain awareness (AIS)", "Aviation surveillance (ADS-B)", "Weather and climate monitoring", "Radio occultation data", "Satellite data analytics", "Space-as-a-Service"], "industries": ["Maritime", "Aviation", "Weather & Climate", "Government", "Insurance"], "employees": "501-1000", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Open Cosmos', 'Open Cosmos is a UK-founded NewSpace company that designs, builds, launches, and operates advanced small satellites and space missions through its end-to-end OpenOrbit mission management platform. Founded in 2015 at the Harwell Campus, the company simplifies access to space for government agencies, research organisations, and commercial customers worldwide. Open Cosmos provides straightforward access to high-quality satellite data and insights at scale, with offices in the UK, Spain, Portugal, and Greece. The company has delivered missions for ESA, the UK Space Agency, and numerous international clients.', '{"company_type": "Satellite Manufacturer", "website_url": "https://www.open-cosmos.com", "contact_email": "info@open-cosmos.com", "contact_linkedin": "https://www.linkedin.com/company/opencosmos", "location": "Harwell, Oxfordshire", "capabilities": ["Small satellite design and manufacture", "End-to-end mission management", "Satellite data services", "Earth observation analytics", "Launch services coordination", "On-orbit operations", "Mission control software"], "industries": ["Earth Observation", "Government", "Research", "Agriculture", "Environment"], "employees": "51-200", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'In-Space Missions Limited', 'In-Space Missions Limited is a UK-based satellite manufacturer and operator, wholly owned by BAE Systems Digital Intelligence, headquartered in Alton, Hampshire with purpose-built satellite cleanrooms. Founded in 2015, the company designs, manufactures, integrates, and tests satellites ranging from 1U CubeSats up to 150 kg small satellites. In-Space offers full end-to-end mission services including payload development, launch, commissioning, on-orbit operations, and secure data delivery. It also operates a commercial hosted payload service known as the Faraday Dragon missions.', '{"company_type": "Satellite Manufacturer", "website_url": "https://in-space.co.uk", "contact_email": "info@in-space.co.uk", "contact_phone": "+44 (0)1420 200140", "contact_linkedin": "https://www.linkedin.com/company/inspacemissions", "location": "Alton, Hampshire", "certifications": ["ISO 9001"], "capabilities": ["Small satellite and CubeSat manufacture", "Hosted payload services", "Satellite integration and testing", "On-orbit operations", "Rideshare mission management", "Space-as-a-Service", "Secure data delivery"], "industries": ["Defence", "Government", "Research", "Earth Observation", "IoT"], "employees": "51-200", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Satellite Applications Catapult', 'The Satellite Applications Catapult is a UK innovation and technology company established in 2013 by Innovate UK, dedicated to accelerating the take-up of satellite technologies and helping businesses develop new satellite-based products, services, and applications. Based at Harwell Campus, Oxfordshire — the heart of the UK''s largest space cluster — the Catapult works with businesses, researchers, investors, and end-users to translate ideas from concept to market. The organisation hosts the Harwell Space Cluster, home to over 100 space organisations, and provides technical expertise in Earth observation, navigation, satcoms, and data analytics.', '{"company_type": "Space Technology Innovation", "website_url": "https://sa.catapult.org.uk", "contact_email": "info@sa.catapult.org.uk", "contact_phone": "+44 (0)1235 567999", "contact_linkedin": "https://www.linkedin.com/company/satellite-applications-catapult", "location": "Harwell, Oxfordshire", "capabilities": ["Satellite technology commercialisation", "Earth observation data analytics", "Space cluster management", "Business incubation and acceleration", "Technical consultancy", "Research and development", "Market development support"], "industries": ["Government", "Research", "Agriculture", "Environment", "Maritime", "Defence"], "employees": "51-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AAC Clyde Space', 'AAC Clyde Space is a leading small satellite manufacturer formed in 2019 through the merger of Scottish company Clyde Space and Swedish company AAC Microtec, with the Glasgow facility serving as the primary manufacturing hub. The company specialises in designing, building, and operating CubeSats and small satellites for commercial, government, and scientific customers worldwide. AAC Clyde Space is notable for its heritage in CubeSat power systems and satellite platforms, and it offers constellation services and space data products. It operates facilities in Glasgow, Sweden, the Netherlands, the US, and South Africa.', '{"company_type": "Satellite Manufacturer", "website_url": "https://www.aac-clyde.space", "contact_email": "info@aac-clyde.space", "contact_phone": "+44 (0)141 945 2000", "contact_linkedin": "https://www.linkedin.com/company/aac-clyde-space", "location": "Glasgow, Scotland", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["CubeSat and small satellite design", "Satellite power systems (EPS)", "Satellite constellation services", "Satellite data products", "Space system integration", "Ground station services", "On-orbit operations"], "industries": ["Earth Observation", "IoT", "Government", "Defence", "Research"], "employees": "101-250", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Astroscale Ltd', 'Astroscale Ltd is the UK and European subsidiary of Japanese company Astroscale Holdings Inc., a pioneering company developing on-orbit servicing and active debris removal technologies. Founded in 2017 and based at Harwell Science and Innovation Campus, Oxfordshire, Astroscale UK has grown to over 100 employees in its dedicated 20,000 sq ft satellite manufacturing facility. The company is developing the world''s first commercial active debris removal mission (ELSA-M) and life extension services, with support from the UK Space Agency. Astroscale is at the forefront of addressing the growing threat of space debris to sustain the orbital environment.', '{"company_type": "Space Sustainability", "website_url": "https://www.astroscale.com", "contact_email": "info@astroscale.com", "contact_phone": "+44 (0)1235 320000", "contact_linkedin": "https://www.linkedin.com/company/astroscale", "location": "Harwell, Oxfordshire", "capabilities": ["Active debris removal", "On-orbit servicing", "Life extension services", "Space situational awareness", "Satellite manufacturing", "Rendezvous and proximity operations", "End-of-life satellite disposal"], "industries": ["Space Sustainability", "Government", "Defence", "Commercial Satellite"], "employees": "101-250", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Inmarsat', 'Inmarsat is a British satellite telecommunications company providing global mobile satellite communications services, now part of Viasat following a $7.3 billion acquisition completed in May 2023. Headquartered at 99 City Road, London, Inmarsat has provided satellite connectivity for over 40 years through a fleet of geostationary satellites covering maritime, aviation, and land mobile sectors. The company supports critical communications for shipping, airlines, mining, governments, and aid organisations worldwide. Viasat has reconfirmed that its global international business headquarters remains in London.', '{"company_type": "Satellite Communications", "website_url": "https://www.inmarsat.com", "contact_email": "customer.care@inmarsat.com", "contact_phone": "+44 (0)20 7728 1000", "contact_linkedin": "https://www.linkedin.com/company/inmarsat", "location": "London, England", "certifications": ["ISO 9001", "ISO 27001"], "capabilities": ["Global maritime satellite communications (GMDSS)", "Aviation in-flight connectivity", "Land mobile satellite services", "Fleet broadband", "Government and military comms", "Safety-of-life communications", "IoT and M2M connectivity"], "industries": ["Maritime", "Aviation", "Government", "Energy", "Mining", "Aid & Humanitarian"], "employees": "1001-2000", "established": 1979, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SatixFy UK', 'SatixFy UK is the British division of SatixFy Communications Ltd, a satellite communications chipset and modem developer with operations in Farnborough and Manchester. Established in the UK in 2016 with an investment of over €15 million, SatixFy designs next-generation satellite communication systems based on in-house developed integrated circuits and Software Defined Radio (SDR) technology. The UK team delivers innovative Electronically Steered Multi Beam Antenna (ESMA) chipset solutions for the world''s most advanced satellite standards including DVB-S2X. In September 2023, MDA Space acquired SatixFy''s digital payload division.', '{"company_type": "Satellite Communications", "website_url": "https://www.satixfy.com", "contact_email": "info@satixfy.com", "contact_phone": "+44 (0)1252 816600", "contact_linkedin": "https://www.linkedin.com/company/satixfy", "location": "Farnborough, Hampshire", "capabilities": ["Satellite communications chipset design", "Software Defined Radio (SDR)", "Electronically Steered Multi Beam Antennas", "DVB-S2X modem technology", "Satellite payload development", "ASIC design for space", "Ground terminal electronics"], "industries": ["Telecommunications", "Defence", "Broadcasting", "Government"], "employees": "51-200", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ALL.SPACE (formerly Isotropic Systems)', 'ALL.SPACE (formerly Isotropic Systems) is a UK satellite antenna technology company based in Reading, Berkshire, founded in 2013 by John Finney. The company developed the world''s first multi-link, multi-orbit flat panel antenna terminal capable of simultaneously connecting to multiple satellite constellations without performance compromise. Its patented lens-based technology tracks multiple satellites without moving parts. ALL.SPACE has raised over $202 million from investors including Boeing, SES, and Seraphim Capital, and operates a manufacturing facility near Reading employing over 180 people.', '{"company_type": "Satellite Communications", "website_url": "https://www.all.space", "contact_email": "info@all.space", "contact_phone": "+44 (0)118 900 1700", "contact_linkedin": "https://www.linkedin.com/company/allspaceltd", "location": "Reading, Berkshire", "capabilities": ["Multi-orbit flat panel satellite antennas", "Multi-link simultaneous connectivity", "Electronically steered antenna technology", "LEO, MEO and GEO terminal solutions", "Military and commercial satcom terminals", "Antenna manufacturing", "Ground user terminals"], "industries": ["Telecommunications", "Defence", "Maritime", "Aviation", "Government"], "employees": "101-250", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Telespazio UK', 'Telespazio UK is a British space services company headquartered in Luton, Bedfordshire, founded in 1978 and operating as a subsidiary of Telespazio (a joint venture of Leonardo and Thales). The company provides satellite operations, ground segment engineering, Earth observation services, and satellite communications solutions for institutional and commercial customers. Telespazio UK works with ESA, ECMWF, the UK Space Agency, and major space primes across Earth observation, navigation, and satellite communications domains. The company employs approximately 100 specialists and also owns two US teleports.', '{"company_type": "Satellite Services", "website_url": "https://telespazio.co.uk", "contact_email": "info_uk@telespazio.com", "contact_phone": "+44 (0)1582 399000", "contact_linkedin": "https://www.linkedin.com/showcase/telespaziouk", "location": "Luton, Bedfordshire", "certifications": ["ISO 9001", "ISO 27001"], "capabilities": ["Satellite ground segment engineering", "Earth observation data services", "Satellite navigation services", "Mission operations support", "Satellite communications management", "Climate change monitoring", "Space systems consulting"], "industries": ["Government", "Earth Observation", "Navigation", "Meteorology", "Defence"], "employees": "51-200", "established": 1978, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Space Systems', 'Oxford Space Systems (OSS) is a UK space technology company founded in 2013 at Harwell Campus, specialising in the development and manufacture of deployable antennas and structural mechanisms for the space segment. The company offers deployable antenna products for Synthetic Aperture Radar (SAR), IoT, telecommunications, VDES/AIS, and data relay applications across the RF spectrum from VHF to Ka-band. OSS''s patented Wrapped Rib antenna technology has been successfully demonstrated in orbit on SSTL''s CarbSAR mission in early 2026. With over 100 employees and a new production facility in Abingdon, OSS is scaling for large antenna production.', '{"company_type": "Satellite Technology", "website_url": "https://oxford.space", "contact_email": "info@oxford.space", "contact_phone": "+44 (0)1235 425840", "contact_linkedin": "https://www.linkedin.com/company/oxford-space-systems", "location": "Harwell, Oxfordshire", "certifications": ["ISO 9001"], "capabilities": ["Deployable satellite antennas", "SAR antenna systems", "Wrapped rib antenna technology", "Deployable structures for spacecraft", "RF antenna design (VHF to Ka-band)", "Composite structure manufacturing", "In-orbit deployment mechanisms"], "industries": ["Earth Observation", "Telecommunications", "IoT", "Defence", "Navigation"], "employees": "51-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lacuna Space', 'Lacuna Space is a UK and Dutch satellite IoT connectivity company founded in 2016 at the ESA Business Incubation Centre at Harwell Campus. The company provides global, direct-to-device IoT connectivity using its proprietary LoneWhisper technology over a constellation of fifteen nanosatellites designed to de-orbit after five years. Lacuna enables reliable global coverage with ultra-low-power protocols for remote sensors across agriculture, environment, utilities, and ocean monitoring without requiring ground infrastructure. Supported by the UK and European Space Agencies, Lacuna serves partners and customers in over 50 countries.', '{"company_type": "Satellite IoT", "website_url": "https://lacuna-space.com", "contact_email": "get_me_started@lacuna.space", "contact_linkedin": "https://www.linkedin.com/company/lacuna-space", "location": "Harwell, Oxfordshire", "capabilities": ["Satellite IoT connectivity", "Direct-to-device communications", "LoRaWAN satellite integration", "Asset tracking and monitoring", "Nanosatellite constellation operation", "Low-power wide area network (LPWAN)", "Remote sensor connectivity"], "industries": ["Agriculture", "Environment", "Utilities", "Maritime", "Logistics", "IoT"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Goonhilly Earth Station Ltd', 'Goonhilly Earth Station Ltd is the operator of the historic Goonhilly satellite ground station on the Lizard peninsula in Cornwall, the largest satellite earth station in the world at its peak with over 30 antennas. Since being privatised under a 999-year lease from BT in 2014, Goonhilly has been rejuvenated as a world-class commercial satellite and deep space communications facility. The company provides ground station services for GEO, MEO, and LEO constellations, deep space tracking, and cloud-based managed services. Goonhilly also owns two US teleports (COMSAT Southbury and Santa Paula) and operates a facility in Farnborough, Hampshire.', '{"company_type": "Ground Station Services", "website_url": "https://www.goonhilly.org", "contact_email": "info@goonhilly.org", "contact_phone": "+44 (0)800 043 7768", "contact_linkedin": "https://www.linkedin.com/company/goonhilly-earth-station-ltd", "location": "Helston, Cornwall", "certifications": ["ISO 27001"], "capabilities": ["Satellite ground station operations", "Deep space communications tracking", "Telemetry, tracking and command (TT&C)", "LEO, MEO and GEO satellite support", "Cloud-based ground station services", "Satellite data downlink and uplink", "UK Space Gateway services"], "industries": ["Government", "Defence", "Commercial Satellite", "Deep Space Exploration", "Telecommunications"], "employees": "11-50", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'QinetiQ', 'QinetiQ is a global integrated defence, security, and space company headquartered in Farnborough, Hampshire, established as a private company from the UK government''s Defence Evaluation and Research Agency (DERA) in 2001. The company is one of Europe''s leading space system integrators with over 250 engineers involved in over 100 space missions, delivering observation platforms, small satellite platforms, science instruments, navigation payloads, propulsion systems, and secure communications. QinetiQ''s space capabilities align with the UK Government''s Defence Space Strategy and Space Industrial Plan, providing services across Space Domain Awareness, space control, satellite data, satcoms, and PNT.', '{"company_type": "Space Systems Integrator", "website_url": "https://www.qinetiq.com", "contact_email": "enquiries@qinetiq.com", "contact_phone": "+44 (0)1252 393000", "contact_linkedin": "https://www.linkedin.com/company/qinetiq", "location": "Farnborough, Hampshire", "certifications": ["ISO 9001", "AS9100", "ISO 14001", "ISO 27001"], "capabilities": ["Small satellite platforms", "Space Domain Awareness (SDA)", "Navigation and PNT systems", "Secure satellite communications", "Space system testing and evaluation", "Satellite propulsion", "Defence space intelligence"], "industries": ["Defence", "Government", "Navigation", "Security", "Space Surveillance"], "employees": "1001-5000", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Bright Ascension Ltd', 'Bright Ascension Ltd is a Scottish space software company founded in 2011 by Dr Peter Mendham, providing flight software, mission control software, and satellite integration tools for the global small satellite market. Based in Dundee with offices in Edinburgh and Bristol, the company became employee-owned in 2019. Bright Ascension''s products include GenerationOne flight software framework and Mission Control products supporting assembly, integration, verification, and testing of satellites. The company has contributed software to missions for the UK Space Agency, SSTL, and international customers.', '{"company_type": "Satellite Software", "website_url": "https://brightascension.com", "contact_email": "info@brightascension.com", "contact_phone": "+44 (0)1382 602041", "contact_linkedin": "https://www.linkedin.com/company/bright-ascension-ltd", "location": "Dundee, Scotland", "capabilities": ["Satellite flight software", "Mission control software", "Satellite simulator development", "AIVT tooling for spacecraft", "On-board software frameworks", "CubeSat and small satellite software", "R&D consultancy for space software"], "industries": ["Government", "Research", "Earth Observation", "Defence", "Commercial Satellite"], "employees": "11-50", "established": 2011, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Earth-i Ltd', 'Earth-i is a UK geospatial intelligence and Earth observation company headquartered at Surrey Research Park, Guildford, founded in 2015. The company develops advanced analytics combining multi-resolution satellite data including satellite video with AI-driven data science to provide actionable insights for defence, security, intelligence, and commercial customers. Earth-i has launched its own prototype satellite (Vivid-X2) and partners with Planet to deliver high-revisit surveillance solutions. The company provides near real-time intelligence for applications including site monitoring, commodity tracking, and environmental assessment.', '{"company_type": "Earth Observation", "website_url": "https://earthi.space", "contact_email": "info@earthi.space", "contact_phone": "+44 (0)1483 685400", "contact_linkedin": "https://www.linkedin.com/company/earth-i", "location": "Guildford, Surrey", "capabilities": ["Satellite imagery analytics", "Geospatial intelligence (GEOINT)", "Satellite video analysis", "AI-powered data processing", "Defence and security intelligence", "Commodity market monitoring", "Change detection and monitoring"], "industries": ["Defence", "Security & Intelligence", "Energy", "Finance", "Government"], "employees": "11-50", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Satellite Vu (SatVu)', 'Satellite Vu (SatVu) is a London-based thermal imaging satellite company founded in 2016 by Anthony Baker, developing the world''s highest-resolution thermal infrared satellite constellation for monitoring heat emissions from any structure on Earth. The company''s first satellite, HotSat-1, was launched in June 2023, built by SSTL, and SatVu is planning a constellation of seven mid-wave infrared (MWIR) satellites. With €68 million raised in total equity funding from investors including Lockheed Martin and In-Q-Tel, SatVu serves energy efficiency, sustainable finance, disaster response, and activity-based intelligence markets.', '{"company_type": "Earth Observation", "website_url": "https://www.satellitevu.com", "contact_email": "info@satellitevu.com", "contact_linkedin": "https://www.linkedin.com/company/satvu", "location": "London, England", "capabilities": ["Thermal infrared satellite imagery", "High-resolution MWIR data", "Building heat monitoring", "Industrial emissions tracking", "Activity-based intelligence", "Energy efficiency analytics", "Climate change monitoring"], "industries": ["Energy", "Finance", "Government", "Insurance", "Environment", "Real Estate"], "employees": "11-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Space Forge Ltd', 'Space Forge is a Cardiff-based in-space manufacturing company founded in 2018 by Joshua Western and Andrew Bacon, developing reusable on-orbit fabrication capabilities for producing advanced semiconductors and alloys in microgravity. The company''s ForgeStar platform is a reusable manufacturing satellite with a proprietary Pridwen heat shield for re-entry and recovery. ForgeStar-1 was successfully launched in June 2025 on a SpaceX Falcon 9 and has demonstrated its microgravity furnace at 1000°C. Space Forge raised £22.6 million in Series A funding and leverages microgravity to produce next-generation materials impossible to create on Earth.', '{"company_type": "In-Space Manufacturing", "website_url": "https://www.spaceforge.com", "contact_email": "hello@spaceforge.com", "contact_linkedin": "https://www.linkedin.com/company/space-forge-ltd", "location": "Cardiff, Wales", "capabilities": ["In-space manufacturing platform", "Reusable satellite development", "Microgravity materials processing", "Semiconductor manufacturing in orbit", "Re-entry vehicle technology", "Advanced alloy production", "On-orbit manufacturing operations"], "industries": ["Semiconductors", "Advanced Materials", "Pharmaceuticals", "Research"], "employees": "51-100", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Alba Orbital', 'Alba Orbital is the world''s leading PocketQube satellite company, founded in 2012 by Tom Walkinshaw in Glasgow, Scotland. The company designs and builds PocketQube (5cm x 5cm) pico-satellites and the AlbaPod satellite deployer, having launched over 50 satellites to date — more than half of all PocketQubes ever flown. Operating a vertically integrated model spanning satellite manufacture, rideshare launch services, and ground station operations, Alba Orbital democratises access to space for universities, startups, and emerging space nations on 4 continents. The company operates the world''s first PocketQube factory at Hillington Industrial Estate, Glasgow.', '{"company_type": "Satellite Manufacturer", "website_url": "https://www.albaorbital.com", "contact_email": "contact@albaorbital.com", "contact_linkedin": "https://www.linkedin.com/company/alba-orbital", "location": "Glasgow, Scotland", "capabilities": ["PocketQube satellite manufacture", "Satellite rideshare launch services", "Ground station services", "AlbaPod satellite deployer", "Pico-satellite bus design", "End-to-end mission services", "Access to space for universities"], "industries": ["Research", "Education", "Earth Observation", "Technology Demonstration"], "employees": "11-50", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Deimos Space UK Ltd', 'Deimos Space UK Ltd is a space systems engineering company established in 2013 at Harwell Oxford Campus as the UK subsidiary of Elecnor Deimos (acquired by Indra in November 2024). The company specialises in flight systems engineering, ground segment systems, space situational awareness, satellite navigation, Earth observation data processing, and AI/machine learning for space applications. Deimos UK serves the European and UK Space Agencies, the UK MoD, and major space primes including Airbus, OHB System, and Thales Alenia Space. The company is particularly strong in machine learning for EO data processing and GNSS navigation technologies.', '{"company_type": "Space Systems Engineering", "website_url": "https://deimos-space.com", "contact_email": "info@deimos-space.com", "contact_phone": "+44 (0)1235 444100", "contact_linkedin": "https://www.linkedin.com/company/deimos-space-uk-limited", "location": "Harwell, Oxfordshire", "certifications": ["ISO 9001"], "capabilities": ["Flight systems engineering", "Ground segment design", "Space situational awareness (SSA)", "GNSS navigation systems", "Earth observation data processing", "AI/ML for satellite data", "Mission analysis and design"], "industries": ["Government", "Defence", "Earth Observation", "Navigation", "Research"], "employees": "11-50", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Horizon Technologies Ltd', 'Horizon Technologies is a UK small business headquartered in Reading, Berkshire, and a global leader in innovative signals intelligence and space-based Maritime Domain Awareness (MDA) solutions. The company''s Amber constellation of satellites provides space-based maritime surveillance intelligence, detecting vessel RF emissions including AIS, L-band satphones, and maritime radars — enabling tracking of dark vessels involved in illegal activities even when AIS is disabled. Horizon Technologies operates two business units: Horizon Aerospace Technologies and Horizon Space Technologies. The company has received UK Space Agency and DASA funding for its satellite maritime surveillance programme.', '{"company_type": "Earth Observation", "website_url": "https://horizontechnologies.eu", "contact_email": "info@horizontechnologies.eu", "contact_linkedin": "https://www.linkedin.com/company/horizon-technologies-ltd", "location": "Reading, Berkshire", "capabilities": ["Maritime domain awareness (MDA)", "Satellite-based signals intelligence", "Vessel RF emissions detection", "AIS data collection and analysis", "Dark vessel detection", "Airborne intelligence solutions", "Space-based surveillance"], "industries": ["Maritime Security", "Border Security", "Defence", "Government", "Fisheries"], "employees": "11-50", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GMV NSL Ltd', 'GMV NSL Ltd (GMV-UK) is an advanced technology company based in Nottingham and Harwell, formed in 2020 through the merger of GMV Innovating Solutions Ltd and NSL Ltd. The company is a wholly owned subsidiary of GMV, a Spanish technology group founded in 1984. GMV NSL specialises in space, position navigation and timing (PNT), GNSS technologies, robotics, and AI for critical markets including defence, safety, and national strategy. With nearly 100 employees in the UK, the company is a pioneer in GNSS satellite navigation technologies and provides solutions for aviation, maritime, land, and autonomous systems.', '{"company_type": "Satellite Navigation", "website_url": "https://www.gmv.com", "contact_email": "info@gmv.com", "contact_phone": "+44 (0)115 880 5360", "contact_linkedin": "https://www.linkedin.com/company/gmv", "location": "Nottingham, England", "certifications": ["ISO 9001", "DO-178C"], "capabilities": ["GNSS satellite navigation systems", "Position, Navigation and Timing (PNT)", "Space robotics and autonomy", "AI for space applications", "GNSS receivers and testing", "Ground segment software", "Augmentation system development"], "industries": ["Navigation", "Aviation", "Defence", "Autonomous Vehicles", "Government"], "employees": "51-200", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Thales Alenia Space UK Ltd', 'Thales Alenia Space UK Ltd is the British subsidiary of Thales Alenia Space, the joint venture between Thales Group (67%) and Leonardo (33%), incorporated in the UK in 2013 with facilities at Harwell and Bristol. The UK team specialises in designing and building propulsion systems and modules for telecommunications satellites, operating a Propulsion Integration Centre at Thales Belfast and a facility at Harwell''s Science and Innovation Campus. Thales Alenia Space expanded its UK presence through the acquisition of SEA''s space business. The UK operation contributes to major geostationary satellite programmes and provides propulsion expertise across the global group.', '{"company_type": "Satellite Technology", "website_url": "https://www.thalesaleniaspace.com", "contact_email": "contact@thalesaleniaspace.com", "contact_phone": "+44 (0)1235 445000", "contact_linkedin": "https://www.linkedin.com/company/thales-alenia-space", "location": "Harwell, Oxfordshire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Satellite propulsion systems", "Propulsion module integration", "Telecommunications satellite systems", "Navigation satellite systems", "Earth observation spacecraft", "Space exploration systems", "Space infrastructure"], "industries": ["Telecommunications", "Navigation", "Earth Observation", "Government"], "employees": "51-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Pulsar Fusion Ltd', 'Pulsar Fusion is a UK-based clean space propulsion company headquartered in Bletchley, Milton Keynes, developing advanced propulsion technologies including chemical thrusters currently in service and breakthrough nuclear fusion rocket propulsion for future deep-space missions. Founded by Richard Dinan in 2011 as Applied Fusion Systems, the company manufactures state-of-the-art chemical propulsion systems for small satellites, including the hybrid thruster product line. The company''s flagship Sunbird project, based on its Dual Direct Fusion Drive (DDFD), aims for an In-Orbit Demonstration in 2027, with support from the UK Atomic Energy Authority and Princeton Satellite Systems.', '{"company_type": "Satellite Technology", "website_url": "https://pulsarfusion.com", "contact_email": "info@pulsarfusion.com", "contact_phone": "+44 (0)1908 041500", "contact_linkedin": "https://www.linkedin.com/company/applied-fusion-company", "location": "Bletchley, Milton Keynes", "capabilities": ["Satellite chemical propulsion systems", "Hybrid rocket propulsion", "Nuclear fusion propulsion research", "In-space propulsion development", "Thruster manufacturing", "Propulsion testing facilities", "Advanced propellant technologies"], "industries": ["Space Propulsion", "Defence", "Government", "Commercial Satellite"], "employees": "51-200", "established": 2011, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Gravitilab Aerospace Services Ltd', 'Gravitilab Aerospace Services is a British company founded in 2018, providing accessible and affordable research and testing services in microgravity and space environments using novel UAV-based and suborbital rocket technology. The company was the first in the world to use unmanned aerial vehicles (drones) to provide microgravity services to research and industrial clients, operating from Predannack military airfield in Cornwall. Gravitilab''s hybrid-powered suborbital launch vehicle ISAAC targets a 250 km altitude, offering approximately 300 seconds of microgravity. The company serves pharmaceutical, materials science, life sciences, and space technology research customers.', '{"company_type": "Space Services", "website_url": "https://gravitilab.space", "contact_email": "hello@gravitilab.space", "contact_phone": "+44 (0)1603 738459", "contact_linkedin": "https://www.linkedin.com/company/gravitilab-aerospace-services", "location": "Cornwall, England", "capabilities": ["Drone-based microgravity services", "Suborbital rocket flights", "Microgravity research and testing", "Space environment simulation", "Payload testing in microgravity", "Sub-orbital launch services", "Reusable test vehicle operations"], "industries": ["Pharmaceuticals", "Materials Science", "Life Sciences", "Space Technology", "Research"], "employees": "11-50", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Skyrora Ltd', 'Skyrora Ltd is a British private space launch company founded in 2017 and headquartered in Glasgow, Scotland, focused on designing and manufacturing small satellite launch vehicles and portable launch systems. The company is developing the Skyrora XL orbital launch vehicle, capable of delivering 315 kg to Sun-Synchronous Orbit, as well as the Skylark-L sounding rocket. Skyrora operates Europe''s largest privately owned rocket engine testing facility in Midlothian, Scotland, covering 120,000 square feet. With a manufacturing facility in Cumbernauld, the company is one of the largest NewSpace companies in Europe with over 100 UK-based employees.', '{"company_type": "Launch Services", "website_url": "https://skyrora.com", "contact_email": "info@skyrora.com", "contact_phone": "+44 (0)131 460 5600", "contact_linkedin": "https://www.linkedin.com/company/skyrora-limited", "location": "Glasgow, Scotland", "capabilities": ["Orbital launch vehicle development", "Sounding rocket services", "Rocket engine development and testing", "Small satellite launch services", "Portable launch systems", "Launch vehicle manufacturing", "Green propellant technology"], "industries": ["Launch Services", "Government", "Commercial Satellite", "Research"], "employees": "101-250", "established": 2017, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Raytheon UK', 'Raytheon UK is the British subsidiary of RTX Corporation (formerly Raytheon Technologies), a leading defence, aerospace, and technology company employing 1,700 people across 22 sites in England, Scotland, and Wales. The company''s Space and Airborne division develops and delivers advanced space systems, satellite communications, and space domain awareness capabilities for UK and allied defence customers. Raytheon UK maintains a high-technology space-grade manufacturing capability in Scotland and has developed LOCI (space domain awareness sensor) and other bespoke UK space solutions. The company works closely with the UK MoD and Space Command on sovereign space capabilities.', '{"company_type": "Defence Space Systems", "website_url": "https://www.raytheon.co.uk", "contact_email": "ukinfo@raytheon.com", "contact_phone": "+44 (0)1425 463000", "contact_linkedin": "https://www.linkedin.com/company/raytheon-uk", "location": "Farnborough, Hampshire", "certifications": ["ISO 9001", "AS9100", "ISO 27001"], "capabilities": ["Space domain awareness sensors", "Satellite communications systems", "Cyber-secure space communications", "Space-grade electronics manufacturing", "Orbital analysis and SSA", "Defence satellite payloads", "Space system integration"], "industries": ["Defence", "Government", "Security", "Space Surveillance"], "employees": "1001-2000", "established": 1991, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Leonardo UK (Space Division)', 'Leonardo UK is a major aerospace and defence company employing over 8,500 people across the UK, with a world-class space technology division based in Southampton with over 50 years of heritage. The Southampton team has contributed to more than 20 space programmes for NASA, ESA, and JAXA, providing advanced instruments, sensors, and subsystems for Earth observation, planetary exploration, and science missions. Leonardo UK offers satellite ground segment systems, EO instruments, radar technology, and expert space engineering consulting. Leonardo is a shareholder in both Telespazio and Thales Alenia Space.', '{"company_type": "Space Systems", "website_url": "https://uk.leonardo.com/en/space", "contact_email": "space.uk@leonardo.com", "contact_phone": "+44 (0)23 8061 6000", "contact_linkedin": "https://www.linkedin.com/company/leonardo_company", "location": "Southampton, Hampshire", "certifications": ["ISO 9001", "AS9100", "ISO 14001"], "capabilities": ["Earth observation instruments", "Satellite ground segment systems", "Radar and sonar systems", "Space science instruments", "Electro-optic systems", "Space system integration", "Mission engineering and consulting"], "industries": ["Government", "Defence", "Earth Observation", "Science", "Navigation"], "employees": "1001-5000", "established": 1948, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'MDA Space UK', 'MDA Space UK is the British arm of Canadian space technology company MDA Space Ltd., with facilities across Didcot (Harwell Campus), Stevenage, Manchester, and Farnborough. MDA expanded significantly in the UK following its 2023 acquisition of SatixFy''s digital payload division, doubling its UK workforce to over 150 employees and establishing the UK as a key hub for digital satellite payload engineering. The company develops advanced digital satellite payloads, antenna systems, in-orbit servicing technologies, and space exploration hardware. MDA''s UK teams work on satellite communications payloads, robotics systems, and mission critical space infrastructure for commercial and government customers.', '{"company_type": "Satellite Technology", "website_url": "https://mda.space", "contact_email": "info@mda.space", "contact_phone": "+44 (0)1235 442400", "contact_linkedin": "https://www.linkedin.com/company/mda-space", "location": "Harwell, Oxfordshire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Digital satellite payloads", "Satellite communications systems", "Antenna design and manufacturing", "In-orbit servicing hardware", "Space robotics systems", "Satellite electronics and software", "Mission systems integration"], "industries": ["Telecommunications", "Government", "Defence", "Earth Observation", "Space Exploration"], "employees": "101-250", "established": 2023, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Oxford Space Systems Ltd', 'Oxford Space Systems (OSS) is a growth-stage space technology company specialising in the development and manufacture of deployable antennas and structures for satellite missions. Founded in 2013 and headquartered at the Harwell Space Cluster with a manufacturing facility in Abingdon, OSS has grown to over 100 staff. Its products span CubeSat-compatible solutions to large deployable reflectors and cover RF spectrum from VHF to Ka-band, with flight heritage on the CarbSAR mission.', '{"company_type": "Space Components", "website_url": "https://oxford.space", "contact_email": "info@oxford.space", "contact_phone": "+44 (0)1235 425 840", "contact_linkedin": "https://www.linkedin.com/company/oxford-space-systems", "location": "Harwell / Abingdon, Oxfordshire", "capabilities": ["Deployable antenna design and manufacture", "SAR antennas", "IoT helical antennas", "Wrapped rib reflectors", "Composite structures for satellites", "Antenna manufacturing at scale"], "industries": ["Earth Observation", "IoT Connectivity", "Telecommunications", "Defence", "Science"], "employees": "100-200", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'RAL Space (STFC Rutherford Appleton Laboratory)', 'RAL Space is the UK''s national space research and technology organisation, operating as part of the Science and Technology Facilities Council (STFC) at the Harwell Campus in Oxfordshire. With over 60 years of expertise, RAL Space has contributed to more than 210 space instruments and missions, covering Earth observation, space physics, astrophysics, and technology development. The organisation provides space qualification testing, instrument development, and satellite systems design for national and international space agencies.', '{"company_type": "Space Components", "website_url": "https://www.ralspace.stfc.ac.uk", "contact_email": "ralspaceenquiries@stfc.ac.uk", "contact_phone": "+44 (0) 1235 445 000", "contact_linkedin": "https://www.linkedin.com/company/stfc-rutherford-appleton-laboratory", "location": "Harwell Campus, Didcot, Oxfordshire", "certifications": ["ISO 9001"], "capabilities": ["Space instrument design and manufacture", "Environmental testing (thermal, vibration, EMC)", "Satellite systems engineering", "Earth observation technology", "Space plasma physics instruments", "Ground segment development"], "industries": ["Science", "Earth Observation", "Government", "Defence", "Astrophysics"], "employees": "500-1000", "established": 1957, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Magdrive Ltd', 'Magdrive is a spacecraft propulsion manufacturer based at Harwell Campus in Oxfordshire, developing next-generation electric plasma thrusters for small satellites using solid metal propellant. The company opened the £3.8 million Disruptive Experimental Electric Propulsion (DEEP) Lab at Harwell in 2026, co-funded by the UK Space Agency. Its product range includes the Rogue (10 mN) and Warlock (50 mN) thrusters for LEO satellites, with a high-thrust SuperMagdrive system in development.', '{"company_type": "Space Propulsion", "website_url": "https://magdrive.space", "contact_email": "investment@magdrive.space", "contact_linkedin": "https://www.linkedin.com/company/magdrive-ltd", "location": "Harwell Campus, Didcot, Oxfordshire", "capabilities": ["Electric plasma thruster design and manufacture", "Solid metal propellant propulsion", "In-space propulsion testing", "Satellite station-keeping systems", "High-thrust in-space manoeuvring"], "industries": ["Small Satellites", "Defence", "In-Orbit Services", "Commercial Spacecraft"], "employees": "20-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'EnerSys ABSL (Space Division)', 'EnerSys ABSL at the Culham Science Centre in Oxfordshire is the UK''s leading developer and manufacturer of lithium-ion batteries for space applications. With heritage on over 70 space programmes including the International Space Station, James Webb Space Telescope, and the first ESA Li-ion powered satellite PROBA-1, ABSL batteries have logged more than 6.5 billion cell hours in space without a mission failure. The division supplies batteries for satellites, launchers, planetary landers, and rovers.', '{"company_type": "Space Components", "website_url": "https://www.enersys.com/en-gb/products/batteries/absl/", "contact_phone": "+44-1865-408-710", "contact_linkedin": "https://www.linkedin.com/company/absl-space-products", "location": "Culham Science Centre, Abingdon, Oxfordshire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Lithium-ion space battery design and manufacture", "Battery management systems", "Power systems for satellites and launchers", "Space-grade cell qualification", "Energy storage for planetary landers and rovers"], "industries": ["Satellite Manufacturing", "Launch Vehicles", "Planetary Exploration", "Government Space Agencies"], "employees": "50-150", "established": 1998, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Open Cosmos Ltd', 'Open Cosmos is a UK space mission company founded in 2015 and based at the Harwell Campus, providing end-to-end satellite mission services including design, build, launch campaign, in-orbit operations, and data delivery. The company has built and operates satellites for Earth observation, communications, and navigation applications, with projects including the UK Atlantic Constellation pathfinder satellite. Open Cosmos employs approximately 145 people across its Harwell headquarters and offices in Barcelona and Porto.', '{"company_type": "Space Components", "website_url": "https://www.open-cosmos.com", "contact_email": "hello@open-cosmos.com", "contact_linkedin": "https://www.linkedin.com/company/opencosmos", "location": "Harwell Campus, Didcot, Oxfordshire", "capabilities": ["End-to-end small satellite missions", "Satellite manufacturing and integration", "Launch campaign management", "In-orbit operations", "Earth observation data products", "Satellite constellation design"], "industries": ["Earth Observation", "Telecommunications", "Government", "Navigation", "Environment"], "employees": "100-200", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Telespazio UK Ltd', 'Telespazio UK is one of Europe''s leading space applications and services companies, with nearly 50 years of experience providing consulting, technology, engineering, and space operations services. Based in Luton with a second office at Harwell, the company delivers satellite communications, Earth observation, navigation, space engineering, and operations services. Telespazio UK is a subsidiary of Telespazio, a joint venture between Leonardo (67%) and Thales (33%), and has held ground segment contracts for Inmarsat, Eutelsat, OneWeb, and Galileo.', '{"company_type": "Ground Station", "website_url": "https://telespazio.co.uk", "contact_email": "info_uk@telespazio.com", "contact_phone": "+44 (0)1582 399 000", "contact_linkedin": "https://www.linkedin.com/company/telespazio", "location": "Luton, Bedfordshire", "certifications": ["ISO 9001", "ISO 27001"], "capabilities": ["Ground segment design and operations", "Satellite TT&C services", "Earth observation processing", "Navigation system support", "Space situational awareness", "Fixed and mobile satellite communications"], "industries": ["Telecommunications", "Earth Observation", "Navigation", "Government", "Defence"], "employees": "200-500", "established": 2010, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Satellite Vu Ltd (SatVu)', 'SatVu is a London-based satellite thermal intelligence company developing and operating a constellation of high-resolution thermal imaging satellites. The company''s HotSat constellation captures Earth''s heat emissions at 3.5-metre resolution, day and night, for applications in national security, economic monitoring, industrial process tracking, and climate resilience. SatVu has raised over £60 million in equity funding and has two satellites planned for orbit in 2026 under sovereign UK capability contracts.', '{"company_type": "Space Components", "website_url": "https://www.satellitevu.com", "contact_email": "info@satellitevu.com", "contact_linkedin": "https://www.linkedin.com/company/satvu", "location": "London (County Hall), SE1", "capabilities": ["High-resolution thermal imaging satellites", "Persistent Earth observation", "Thermal constellation design and operation", "Intelligence and surveillance data services", "Urban heat mapping"], "industries": ["Defence and Intelligence", "Government", "Energy and Infrastructure", "Climate Monitoring", "Insurance"], "employees": "38-100", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'In-Space Missions Ltd', 'In-Space Missions, now a wholly owned subsidiary of BAE Systems Digital Intelligence, is a satellite design, manufacture, integration and operations company based in Alton, Hampshire. The company builds satellites from 1U CubeSats up to 150 kg small satellites and offers Space as a Service through its InSpace Digital platform. In-Space Missions has managed programmes including the Faraday Phoenix and UK International Bilateral Funding rideshare missions, and operates purpose-built satellite cleanrooms.', '{"company_type": "Space Components", "website_url": "https://in-space.co.uk", "contact_email": "info@in-space.co.uk", "contact_linkedin": "https://www.linkedin.com/company/inspacemissions", "location": "Alton, Hampshire", "certifications": ["ISO 9001"], "capabilities": ["Satellite design and manufacture (1U to 150 kg)", "Payload integration", "Environmental and functional testing", "Launch campaign management", "In-orbit operations", "Hosted payload services"], "industries": ["Government", "Defence", "Earth Observation", "Technology Demonstration"], "employees": "75-150", "established": 2015, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'AAC Clyde Space Ltd', 'AAC Clyde Space is a Glasgow-based world leader in nanosatellite and small satellite technologies, with hardware supporting 40% of all CubeSat missions and more in-orbit heritage than any other small satellite provider. Originally founded as Clyde Space in 2005, the company joined Swedish parent AAC Microtec in 2018. The Glasgow facility has capacity to produce more than one spacecraft per week, supplying power systems, ADCS, structures, communications, and full satellite platforms to global customers.', '{"company_type": "Space Components", "website_url": "https://www.aac-clyde.space", "contact_email": "enquiries@aac-clydespace.com", "contact_phone": "+44 (0)141 946 4440", "contact_linkedin": "https://www.linkedin.com/company/aac-clyde-space", "location": "Glasgow, Scotland", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["CubeSat and nanosatellite manufacture", "Power control and distribution units", "Solar arrays for small satellites", "Attitude determination and control systems", "Satellite communications hardware", "Satellite constellation deployment"], "industries": ["Earth Observation", "IoT", "Science", "Defence", "Telecommunications"], "employees": "100-300", "established": 2005, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Spire Global UK Ltd', 'Spire Global UK is the Glasgow-based subsidiary of the US space-to-cloud data and analytics company, responsible for designing, building, and testing the company''s CubeSat constellation in Scotland. The Glasgow facility expanded to a 29,500 sq ft purpose-built satellite manufacturing and test facility at Skypark in 2021 and employs approximately 100 people. Spire''s constellation of more than 110 CubeSats delivers maritime AIS, aviation ADS-B, and weather data to customers worldwide.', '{"company_type": "Space Components", "website_url": "https://spire.com", "contact_email": "info@spire.com", "contact_phone": "+44 (0) 141 343 8260", "contact_linkedin": "https://www.linkedin.com/company/spireglobal", "location": "Glasgow, Scotland", "capabilities": ["Nanosatellite manufacture and test", "Satellite constellation operations", "Maritime AIS data services", "Aviation tracking data", "Weather and climate data", "Space-to-cloud analytics"], "industries": ["Maritime", "Aviation", "Weather and Climate", "Government", "Agriculture"], "employees": "100-200", "established": 2014, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Nammo UK Ltd (Nammo Westcott)', 'Nammo UK at Westcott Venture Park in Buckinghamshire is a leading developer and manufacturer of spacecraft propulsion systems for Earth orbit, lunar, and interplanetary missions. With origins at the UK Rocket Propulsion Establishment founded in 1946, Nammo UK produces the LEROS family of liquid apogee engines and bipropellant thrusters deployed across more than 150 space missions. The company also manages the UK National Space Propulsion Test Facility at Westcott on behalf of the UK Space Agency.', '{"company_type": "Space Propulsion", "website_url": "https://www.nammo.com/location/westcott/", "contact_phone": "+44 (0) 1296 652000", "contact_linkedin": "https://www.linkedin.com/company/nammo-westcott", "location": "Westcott Venture Park, Aylesbury, Buckinghamshire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Liquid apogee engines (LEROS series)", "Bipropellant thrusters", "Monopropellant thrusters", "Lunar lander propulsion (ESA Argonaut)", "National Space Propulsion Test Facility management", "Propellant management systems"], "industries": ["Commercial Satellite", "Government Space Agencies", "Planetary Exploration", "Defence"], "employees": "100-300", "established": 1998, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Horizon Technologies Consultants Ltd', 'Horizon Technologies is a Reading-based UK company and global leader in SIGINT and space-based Maritime Domain Awareness intelligence solutions, founded in 1993. The company is the original equipment manufacturer (OEM) for the FlyingFish and BlackFish airborne satellite phone monitoring SIGINT systems used by governments worldwide. Through the AMBER programme, Horizon Technologies is the prime contractor for a UK Government constellation of CubeSats providing global maritime surveillance and detection of illegal activity.', '{"company_type": "Space Components", "website_url": "https://horizontechnologies.eu", "contact_email": "info@horizontechnologies.eu", "contact_phone": "+44-2036-089996", "contact_linkedin": "https://www.linkedin.com/company/horizon-technologies-ltd", "location": "Sonning, Reading, Berkshire", "capabilities": ["SIGINT payload design and manufacture", "Space-based Maritime Domain Awareness (MDA)", "CubeSat constellation operations", "Airborne satellite phone monitoring systems", "RF intelligence from orbit", "Maritime surveillance data services"], "industries": ["Defence and Intelligence", "Border Force / Homeland Security", "Government", "Maritime"], "employees": "50-150", "established": 1993, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ClearSpace Ltd (UK Operations)', 'ClearSpace is an in-orbit servicing company specialising in active debris removal and space sustainability, with UK operations at Harwell Campus in Oxfordshire. The company was founded in 2018 and is leading the CLEAR mission — the UK''s first national active debris removal mission — contracted by the UK Space Agency, targeting the removal of two derelict objects from low Earth orbit. ClearSpace operates as part of a consortium including Astroscale, D-Orbit, and Orbit Fab.', '{"company_type": "In-Orbit Services", "website_url": "https://clearspace.today", "contact_email": "info@clearspace.today", "contact_linkedin": "https://www.linkedin.com/company/clearspace-sa", "location": "Harwell Campus, Didcot, Oxfordshire", "capabilities": ["Active debris removal (ADR) missions", "In-orbit rendezvous and capture", "Space situational awareness", "Inspection and proximity operations", "In-orbit servicing system design"], "industries": ["Space Sustainability", "Government", "Commercial Satellite Operators", "Defence"], "employees": "50-100", "established": 2018, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Lacuna Space Ltd', 'Lacuna Space is an Oxford-based UK and Dutch company recognised as the global leader in scalable direct-to-satellite IoT connectivity using the open LoRaWAN standard. Founded in 2016 and headquartered at Harwell Campus, Lacuna operates its own satellite constellation using its proprietary LoneWhisper technology to provide ultra-low-power bidirectional communications for sensors in remote areas. Applications span agriculture, environment, maritime, utilities, and land transport industries globally.', '{"company_type": "Space Components", "website_url": "https://lacuna-space.com", "contact_email": "info@lacuna-space.com", "contact_linkedin": "https://www.linkedin.com/company/lacuna-space", "location": "Harwell Campus, Didcot, Oxfordshire", "capabilities": ["Direct-to-satellite IoT connectivity (LoRaWAN)", "Satellite constellation design and operation", "LoneWhisper proprietary payload technology", "Remote asset tracking", "Agricultural and environmental IoT data services"], "industries": ["Agriculture", "Environment and Utilities", "Maritime", "Land Transport", "Industrial IoT"], "employees": "17-50", "established": 2016, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'ALL.SPACE Ltd (formerly Isotropic Systems)', 'ALL.SPACE (formerly Isotropic Systems) is a Reading-based UK company that designs and manufactures multi-beam, multi-orbit satellite antenna terminals. Founded in 2013, the company''s patented radio frequency optics technology enables a single terminal to simultaneously connect to multiple satellites across LEO, MEO, and GEO orbits without performance compromise. ALL.SPACE employs approximately 182 people and has raised over $200 million in funding from investors including SES, Boeing, and Seraphim Capital.', '{"company_type": "Ground Station", "website_url": "https://www.all.space", "contact_email": "info@all.space", "contact_linkedin": "https://www.linkedin.com/company/all-space", "location": "Reading, Berkshire", "capabilities": ["Multi-orbit satellite antenna terminals", "Multi-beam RF optics technology", "Flat-panel electronically steered arrays", "Multi-link antenna for aviation and maritime", "LEO/MEO/GEO simultaneous connectivity"], "industries": ["Telecommunications", "Aviation", "Maritime", "Defence", "Government"], "employees": "100-250", "established": 2013, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Celestia UK Ltd', 'Celestia UK is a UK leader in advanced satellite ground segment technologies, forming part of the pan-European Celestia Technologies Group. The company designs and delivers Ka-Band gateway systems, compact teleport solutions, satellite test systems, and cryogenic systems, with sites at Harwell Campus in Oxfordshire and Heriot-Watt University Research Park in Edinburgh. Founded in 1996, Celestia UK is notable for delivering the first verified Ka-Band Gateway product in the industry and serves customers across the European satellite sector.', '{"company_type": "Ground Station", "website_url": "https://www.celestia-uk.com", "contact_email": "sales@celestia-uk.com", "contact_phone": "+44 (0) 1235 431278", "contact_linkedin": "https://www.linkedin.com/company/celestia-technologies-group-uk", "location": "Harwell Campus, Oxfordshire / Edinburgh, Scotland", "capabilities": ["Ka-Band gateway systems", "Compact teleport solutions", "Radiofrequency and antenna systems", "Baseband modems", "Satellite test and EGSE systems", "Monitoring and control solutions"], "industries": ["Telecommunications", "Broadband Satellite", "Government", "Defence"], "employees": "50-150", "established": 1996, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Alba Orbital Ltd', 'Alba Orbital is a Glasgow-based company that is the world''s leading PocketQube satellite manufacturer and launch broker. Founded in 2012, the company operates the world''s first PocketQube factory at Hillington Industrial Estate in Glasgow and has crossed the milestone of 50 satellite launches via SpaceX rideshare missions. Alba Orbital develops PocketQube satellite platforms, the AlbaPod deployer system, and provides end-to-end satellite services from design through launch for universities, research institutions, and commercial customers.', '{"company_type": "Space Components", "website_url": "https://www.albaorbital.com", "contact_email": "contact@albaorbital.com", "contact_linkedin": "https://www.linkedin.com/company/alba-orbital", "location": "Hillington Industrial Estate, Glasgow, Scotland", "capabilities": ["PocketQube satellite manufacture", "AlbaPod PocketQube deployer system", "Small satellite launch brokerage", "Satellite mission design", "CubeSat components supply"], "industries": ["Education and Research", "Earth Observation", "Technology Demonstration", "IoT"], "employees": "15-40", "established": 2012, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'GMV-NSL Ltd', 'GMV-NSL is the UK subsidiary of the GMV Group, formed in 2020 through the merger of GMV Innovating Solutions UK and Nottingham Scientific Limited (NSL). With offices at Harwell and Nottingham, the company specialises in satellite navigation, flight dynamics, space situational awareness, space debris tracking, autonomy, robotics, and ground control centre systems. GMV-NSL works extensively for ESA, the European Commission, the UK Space Agency, and DSTL across civil and defence space programmes.', '{"company_type": "Space Components", "website_url": "https://www.gmv.com", "contact_email": "info@gmv.com", "contact_linkedin": "https://www.linkedin.com/company/gmv", "location": "Harwell, Oxfordshire / Nottingham, Nottinghamshire", "certifications": ["ISO 9001", "ECSS"], "capabilities": ["GNSS and satellite navigation systems", "Flight dynamics and mission planning", "Space situational awareness", "Space debris tracking and removal guidance", "Autonomous robotic systems", "Ground control centre development"], "industries": ["Government Space Agencies", "Navigation", "Defence", "Space Sustainability", "Earth Observation"], "employees": "100-300", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'SaxaVord Spaceport Ltd (Shetland Space Centre)', 'SaxaVord Spaceport, operated by Shetland Space Centre Ltd, is the UK and Western Europe''s first licensed vertical orbital spaceport, located on the Lamba Ness peninsula on Unst, Shetland. Licensed by the UK Civil Aviation Authority in December 2023, the spaceport hosts multiple launch operators including RFA (Rocket Factory Augsburg) and Skyrora. Its polar high-inclination location provides optimal access to sun-synchronous and polar orbits for Earth observation and communications satellites.', '{"company_type": "Launch Vehicle", "website_url": "https://saxavord.com", "contact_email": "info@saxavord.com", "contact_linkedin": "https://www.linkedin.com/company/saxavord-spaceport", "location": "Unst, Shetland Islands, Scotland", "capabilities": ["Vertical launch spaceport operations", "Launch pad management", "Payload processing and integration facilities", "Multiple launch operator hosting", "Range safety and airspace management", "Ground support infrastructure"], "industries": ["Commercial Launch Services", "Earth Observation", "Telecommunications", "Government"], "employees": "20-50", "established": 2020, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Roxel (UK Rocket Motors) Ltd', 'Roxel UK is a Kidderminster-based manufacturer of solid propulsion rocket motors and propellant systems for tactical missiles and space launch applications, with roots tracing back to Royal Ordnance Rocket Motors and a history at Summerfield Research Station dating to the 1940s. Now a wholly owned subsidiary of MBDA, Roxel UK designs, manufactures, and tests solid rocket motors and can support external customers in propulsion system development including solid, liquid, hybrid, and air-breathing systems. The company''s test facilities at Summerfield make it one of the UK''s primary solid propellant rocket centres.', '{"company_type": "Space Propulsion", "website_url": "https://www.roxelgroup.com", "contact_linkedin": "https://www.linkedin.com/company/roxel-uk-rocket-motors-limited", "location": "Kidderminster, Worcestershire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Solid propellant rocket motor design and manufacture", "Rocket motor testing facilities", "Tactical and space propulsion systems", "Composite and aluminised propellant processing", "Motor design analysis and qualification"], "industries": ["Defence", "Space Launch", "Government"], "employees": "100-300", "established": 2002, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Airbus Defence and Space Ltd (UK - Stevenage)', 'Airbus Defence and Space UK at Stevenage is a major satellite manufacturing and systems engineering facility serving as the primary UK production hub for Airbus DS satellites, propulsion systems, and digital payloads. The site produces structures and propulsion systems for large GEO telecommunications and Earth observation satellites including Skynet 6A and Sentinel-6B, and is home to SSTL (a wholly owned subsidiary) in Guildford. The Stevenage facility is one of the largest satellite manufacturing sites in the UK, employing several hundred aerospace engineers.', '{"company_type": "Space Components", "website_url": "https://www.airbus.com/en/products-services/space", "contact_linkedin": "https://www.linkedin.com/company/airbus-defence-and-space", "location": "Stevenage, Hertfordshire", "certifications": ["ISO 9001", "AS9100", "ECSS"], "capabilities": ["Large satellite manufacture and integration", "Satellite propulsion system supply and test", "Digital signal processing payloads", "Spacecraft structural assembly", "Satellite systems engineering", "Environmental testing"], "industries": ["Telecommunications", "Earth Observation", "Defence", "Government"], "employees": "500-1500", "established": 2000, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'QinetiQ Ltd (Space Division)', 'QinetiQ is a UK defence technology company with a leading space division headquartered at its Farnborough site, employing over 250 space engineers with involvement in more than 100 missions. QinetiQ is a world leader in electric propulsion systems for satellites and is one of Europe''s leading space system integrators, providing mission design, satellite components, scientific instruments, and testing services. The company has more than 35 mission-years in orbit and supports military, security, and civil space programmes including Space Domain Awareness, space communications, and navigation.', '{"company_type": "Space Components", "website_url": "https://www.qinetiq.com/en/markets/space", "contact_linkedin": "https://www.linkedin.com/company/qinetiq", "location": "Farnborough, Hampshire", "certifications": ["ISO 9001", "AS9100"], "capabilities": ["Electric propulsion systems for satellites", "Small satellite design and integration", "Scientific space instruments", "Space system testing and evaluation", "Space Domain Awareness", "Secure satellite communications"], "industries": ["Defence", "Government", "Commercial Satellite", "Science"], "employees": "500-1000", "established": 2001, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'CGI UK Ltd (Space Division, formerly SciSys)', 'CGI''s space division in the UK, operating from Chippenham and Bristol, is a world-class supplier of spacecraft ground segment software systems and onboard software to ESA and international customers. Originally SciSys (founded 1980), the division was acquired by CGI Group in 2019 for $103 million. The company''s Pleniter product suite provides satellite mission planning and control, and 2met real-time data processing for Earth observation. CGI UK''s space team has delivered ground systems for programmes including Galileo, OneWeb, and multiple ESA Earth observation missions.', '{"company_type": "Ground Station", "website_url": "https://www.cgi.com/uk/en-gb/space", "contact_phone": "+44 (0)1249 466466", "contact_linkedin": "https://www.linkedin.com/company/cgi-inc", "location": "Chippenham, Wiltshire", "certifications": ["ISO 9001", "ISO 27001"], "capabilities": ["Mission planning and control software", "Earth observation data processing (2met)", "Ground segment system design", "Onboard software development", "Navigation ground systems (Galileo GNMF)", "Satellite constellation ground software"], "industries": ["Government Space Agencies", "Navigation", "Earth Observation", "Telecommunications"], "employees": "200-500", "established": 1980, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');

INSERT INTO public.marketplace_listings (category, subcategory, title, description, attributes, image_url, is_verified, is_demo, verification_tier)
VALUES ('Products', 'Manufacturer', 'Inmarsat Global Ltd', 'Inmarsat is the UK''s pioneering global mobile satellite communications operator, headquartered in London and operating a fleet of geostationary satellites that provide global connectivity for maritime, aviation, energy, government, and emergency response sectors. Founded as an intergovernmental organisation in 1979 and privatised in 1999, Inmarsat now operates as part of Viasat following a 2023 acquisition and continues to provide the BGAN, Fleet Xpress, SwiftBroadband, and GX (Global Xpress) Ka-band services globally.', '{"company_type": "Space Components", "website_url": "https://www.inmarsat.com", "contact_linkedin": "https://www.linkedin.com/company/inmarsat", "location": "London (Old Street), EC1", "capabilities": ["Global mobile satellite communications (L-band and Ka-band)", "Maritime broadband connectivity", "Aviation in-flight connectivity", "Government and military satellite communications", "IoT and M2M connectivity services", "Emergency and safety services"], "industries": ["Maritime", "Aviation", "Energy", "Government and Defence", "Emergency Services"], "employees": "1000-2000", "established": 1979, "lead_time": null, "min_order": null, "data_source": "company_website", "data_confidence": "high", "last_verified": "2026-02"}', NULL, true, true, 'claimed');
